{"command":"export GOTOOLCHAIN=local; cd /tmp/t2
cat > /tmp/collect.py <<'PY'
import subprocess, json, collections, concurrent.futures, os
env=dict(os.environ); env["GOTOOLCHAIN"]="local"
def run(i):
    try:
        out=subprocess.check_output(["/workspace/executable","-formatter","sarif","."], cwd="/tmp/t2", env=env, timeout=10)
        j=json.loads(out)
        return [r["id"] for r in j["runs"][0]["tool"]["driver"]["rules"]]
    except Exception as e:
        return []
cnt=collections.Counter()
with concurrent.futures.ThreadPoolExecutor(max_workers=8) as ex:
    for res in ex.map(run, range(300)):
        cnt.update(res)
print(len(cnt))
for k,v in sorted(cnt.items()): print(k,v)
PY
python3 /tmp/collect.py"}

