{"command":"cat > /tmp/bgcollect.py <<'PY'
import subprocess, json, concurrent.futures, os
env=dict(os.environ); env["GOTOOLCHAIN"]="local"
def run(i):
    try:
        out=subprocess.check_output(["/workspace/executable","-formatter","sarif","-config","all.toml","."], cwd="/tmp/t2", env=env, timeout=30)
        j=json.loads(out)
        return [r["id"] for r in j["runs"][0]["tool"]["driver"]["rules"]]
    except Exception:
        return []
with open("/tmp/allrules2.txt","a") as f:
    with concurrent.futures.ThreadPoolExecutor(max_workers=3) as ex:
        futs=[ex.submit(run,i) for i in range(2000)]
        for fut in concurrent.futures.as_completed(futs):
            for k in fut.result():
                f.write(k+"\n"); f.flush()
PY
nohup python3 /tmp/bgcollect.py >/tmp/bg.log 2>&1 &
echo started $!"}

