{"command":"cd /tmp/fmt; export GOTOOLCHAIN=local
cat > cc.toml <<'EOF'
[rule.exported]
[rule.package-comments]
EOF
run(){ echo "--- $1"; cat a.go; echo "OUT:"; /workspace/executable -config cc.toml . 2>&1; }
cat > a.go <<'EOF'
//revive:disable
package p
func Exported() {}
//revive:enable
func Exported2() {}
EOF
run disable-enable
cat > a.go <<'EOF'
package p
//revive:disable-next-line
func Exported() {}
func Exported2() {}
EOF
run disable-next-line
cat > a.go <<'EOF'
package p
func Exported() {} //revive:disable-line
func Exported2() {}
EOF
run disable-line
cat > a.go <<'EOF'
package p
//revive:disable:exported
func Exported() {}
//revive:enable:exported
func Exported2() {}
EOF
run disable-specific
cat > a.go <<'EOF'
package p
// revive:disable
func Exported() {}
// revive:enable
func Exported2() {}
EOF
run space-after-slashes
cat > a.go <<'EOF'
package p
//revive:disable-next-line:exported
func Exported() {}
func Exported2() {}
EOF
run disable-next-line-specific
cat > a.go <<'EOF'
package p
func Exported() {} //revive:disable-line:exported
func Exported2() {}
EOF
run disable-line-specific
"}

