{"command":"cat > /tmp/probe/exported_groups.py <<'PY'
import sys; sys.path.insert(0,"/tmp/probe"); from run import run
import itertools
for kind in ["var","const","type"]:
  for mask in range(8):
    specs=[]
    names=["A","B","C"]
    for i,n in enumerate(names):
        if mask>>i &1: specs.append(f"// {n} doc")
        val = "struct{}" if kind=="type" else ("= 1" if kind=="const" else "int")
        specs.append(f"{n} {val}" if kind!="type" else f"{n} {val}")
    code="package p\n"+kind+" (\n"+"\n".join(specs)+"\n)\n"
    print(f"--- {kind} docmask {mask:03b}")
    run("exported", code)
PY
python3 /tmp/probe/exported_groups.py"}

