{"command":"cat > /workspace/main.go <<'EOF'
package main

import (
	"flag"
	"fmt"
	"os"
)

const version = "5570362"
const commit = "5570362e88f0b23eb901a0ea856e77c3fd66ea95"
const buildStamp = "2026-08-10 23:10 UTC"

type arrayFlags []string

func (a *arrayFlags) String() string { return "" }
func (a *arrayFlags) Set(v string) error {
	*a = append(*a, v)
	return nil
}

func main() {
	os.Exit(run())
}

func run() int {
	var (
		configPath     string
		formatterName  string
		maxOpenFiles   int
		setExitStatus  bool
		displayVersion bool
		excludeFlags   arrayFlags
	)
	flag.Usage = func() {
		fmt.Println(`
 _ __ _____   _(_)__  _____
| '__/ _ \ \ / / \ \ / / _ \
| | |  __/\ V /| |\ V /  __/
|_|  \___| \_/ |_| \_/ \___|

Example:
  revive -config c.toml -formatter friendly -exclude a.go -exclude b.go ./...`)
		fmt.Fprintf(flag.CommandLine.Output(), "\nUsage of %s:\n", os.Args[0])
		flag.PrintDefaults()
	}
	flag.StringVar(&configPath, "config", "", "path to the configuration TOML file, defaults to $XDG_CONFIG_HOME/revive.toml or $HOME/revive.toml, if present (i.e. -config myconf.toml)")
	flag.Var(&excludeFlags, "exclude", "list of globs which specify files to be excluded (i.e. -exclude foo/...)")
	flag.StringVar(&formatterName, "formatter", "", "formatter to be used for the output (i.e. -formatter stylish)")
	flag.IntVar(&maxOpenFiles, "max_open_files", 0, "maximum number of open files at the same time")
	flag.BoolVar(&setExitStatus, "set_exit_status", false, "set exit status to 1 if any issues are found, overwrites errorCode and warningCode in config")
	flag.BoolVar(&displayVersion, "version", false, "get revive version")
	flag.Parse()
	_ = maxOpenFiles

	if displayVersion {
		fmt.Printf("Version:\t%s\nCommit:\t\t%s\nBuilt\t\t%s by build.sh\n", version, commit, buildStamp)
		return 0
	}

	cfg, err := getConfig(configPath)
	if err != nil {
		fmt.Fprintln(os.Stderr, err.Error())
		if ec, ok := err.(interface{ ExitCode() int }); ok {
			return ec.ExitCode()
		}
		return 1
	}

	// CLI excludes replace those in the config file.
	if len(excludeFlags) > 0 {
		cfg.Exclude = []string(excludeFlags)
	}

	rules, err := getLintRules(cfg)
	if err != nil {
		fmt.Fprintf(os.Stderr, "initializing revive - getting lint rules: %s\n", err.Error())
		return 1
	}

	patterns := flag.Args()
	if len(patterns) == 0 {
		patterns = []string{"."}
	}

	failures, err := lintAll(patterns, cfg, rules)
	if err != nil {
		fmt.Fprintf(os.Stderr, "linting - getting packages: getting packages - resolving packages in dots: %s\n", err.Error())
		return 1
	}

	formatter, err := getFormatter(formatterName)
	if err != nil {
		fmt.Fprintf(os.Stderr, "formatting - getting formatter: %s\n", err.Error())
		return 1
	}
	output, err := formatter.Format(failures, cfg)
	if err != nil {
		fmt.Fprintf(os.Stderr, "formatting - formatting failure: %s\n", err.Error())
		return 1
	}
	fmt.Print(output)

	if setExitStatus {
		if len(failures) > 0 {
			return 1
		}
		return 0
	}
	exitCode := 0
	for _, f := range failures {
		if f.Severity == severityError {
			exitCode = cfg.ErrorCode
		} else if exitCode == 0 {
			exitCode = cfg.WarningCode
		}
		// Original semantics: any error => errorCode; otherwise any failure => warningCode.
		// The loop below is redone precisely after this loop for clarity.
		_ = exitCode
