	Exclude   []string
	Disabled  bool
}

type config struct {
	IgnoreGeneratedHeader bool
	Severity              severity
	Confidence            float64
	ErrorCode             int
	WarningCode           int
	EnableAllRules        bool
	Rules                 map[string]*ruleConfig `toml:"rule"`
	Exclude               []string
	formatter             string // unused, preserved like original (ignored unknown-ish key actually)
}

var defaultRuleNames = []string{
	"blank-imports",
	"context-as-argument",
	"context-keys-type",
	"dot-imports",
	"empty-block",
	"error-naming",
	"error-return",
	"error-strings",
	"errorf",
	"exported",
	"increment-decrement",
	"indent-error-flow",
	"package-comments",
	"range",
	"receiver-naming",
	"redefines-builtin-id",
	"superfluous-else",
	"time-naming",
	"unexported-return",
	"unreachable-code",
	"unused-parameter",
	"var-declaration",
	"var-naming",
}

func defaultConfig() *config {
	cfg := &config{
		Confidence: 0.8,
		Rules:      map[string]*ruleConfig{},
	}
	for _, name := range defaultRuleNames {
		cfg.Rules[name] = &ruleConfig{Severity: severityWarning}
	}
	return cfg
}

func getConfig(path string) (*config, error) {
	if path == "" {
		// Default lookup: $XDG_CONFIG_HOME/revive.toml then $HOME/revive.toml
		// (Join of an empty dir yields "revive.toml" in the CWD, matching original behaviour).
		candidates := []string{
			filepath.Join(os.Getenv("XDG_CONFIG_HOME"), "revive.toml"),
			filepath.Join(os.Getenv("HOME"), "revive.toml"),
		}
		for _, candidate := range candidates {
			if _, err := os.Stat(candidate); err == nil {
				path = candidate
				break
			}
		}
	}
	if path == "" {
		return defaultConfig(), nil
	}
	content, err := os.ReadFile(path)
	if err != nil {
		return nil, errors.New("cannot read the config file")
	}
	cfg := &config{Rules: map[string]*ruleConfig{}}
	// BurntSushi: use Unmarshal so error strings match the original tool.
	if err := toml.Unmarshal(content, cfg); err != nil {
		return nil, fmt.Errorf("cannot parse the config file: %w", err)
