	if cfg.Rules == nil {
		cfg.Rules = map[string]*ruleConfig{}
	}
	normalizeConfig(cfg)
	return cfg, nil
}

func normalizeConfig(cfg *config) {
	// Expand enableAllRules into the rules map first (so e.g. the SARIF
	// formatter sees all rules, including disabled ones).
	if cfg.EnableAllRules {
		for name := range allRuleDefs {
			if _, ok := cfg.Rules[name]; !ok {
				cfg.Rules[name] = &ruleConfig{}
			}
		}
	}
	for _, rc := range cfg.Rules {
		if rc == nil {
			continue
		}
		if rc.Severity == "" {
			rc.Severity = cfg.Severity
		}
	}
}

// effectiveSeverity converts a raw configured severity into the severity
// recorded on failures: only exactly "error" is an error, everything
// else becomes a warning.
func effectiveSeverity(s severity) severity {
	if s == severityError {
		return severityError
	}
	return severityWarning
}

func getLintRules(cfg *config) ([]*activeRule, error) {
	var result []*activeRule
	for name, rc := range cfg.Rules {
		def, ok := allRuleDefs[name]
		if !ok {
			return nil, fmt.Errorf("cannot find rule: %s", name)
		}
		if rc == nil {
			rc = &ruleConfig{}
			cfg.Rules[name] = rc
		}
		if rc.Disabled {
			continue
		}
		var opts interface{}
		var err error
		if def.configure != nil {
			opts, err = def.configure(rc.Arguments)
			if err != nil {
				return nil, fmt.Errorf("cannot configure rule: %q: %w", name, err)
			}
		}
		result = append(result, &activeRule{def: def, cfg: rc, opts: opts})
	}
	// deterministic ordering (original order is nondeterministic due to map iteration;
	// sorted-by-name via registry canonical order)
	order := map[string]int{}
	for i, n := range allRuleOrder {
		order[n] = i
	}
	// simple insertion sort by canonical order
	for i := 1; i < len(result); i++ {
		for j := i; j > 0 && order[result[j].def.name] < order[result[j-1].def.name]; j-- {
			result[j], result[j-1] = result[j-1], result[j]
		}
	}
	return result, nil
}
