package main

import (
	"fmt"
	"regexp"
	"strings"
)

type fileFilter struct {
	raw       string
	isTest    bool
	isRegex   bool
	isGlob    bool
	regex     *regexp.Regexp
	globRegex *regexp.Regexp
}

func globToRegexpSource(pattern string) string {
	var b strings.Builder
	b.WriteString("^")
	for i := 0; i < len(pattern); {
		c := pattern[i]
		switch c {
		case '*':
			if i+1 < len(pattern) && pattern[i+1] == '*' {
				b.WriteString(".*")
				i += 2
			} else {
				b.WriteString("[^/]*")
				i++
			}
		case '?':
			b.WriteString("[^/]")
			i++
		case '[':
			// copy character class if well-formed
			j := i + 1
			if j < len(pattern) && (pattern[j] == '^' || pattern[j] == '!') {
				j++
			}
			if j < len(pattern) && pattern[j] == ']' {
				j++
			}
			for j < len(pattern) && pattern[j] != ']' {
				j++
			}
			if j >= len(pattern) {
				b.WriteString(regexp.QuoteMeta(string(c)))
				i++
			} else {
				class := pattern[i : j+1]
				if len(class) > 1 && class[1] == '!' {
					class = "[^" + class[2:]
				}
				b.WriteString(class)
				i = j + 1
			}
		default:
			b.WriteString(regexp.QuoteMeta(string(c)))
			i++
		}
	}
	b.WriteString("$")
	return b.String()
}

func newFileFilter(raw string) (*fileFilter, error) {
	if raw == "TEST" {
		return &fileFilter{raw: raw, isTest: true}, nil
	}
	if strings.HasPrefix(raw, "~") {
		re, err := regexp.Compile(raw[1:])
		if err != nil {
			return nil, fmt.Errorf("invalid file filter [%s], regexp compile error: [%s]", raw, err.Error())
		}
		return &fileFilter{raw: raw, isRegex: true, regex: re}, nil
	}
	if strings.Contains(raw, "*") {
		// validate ** placement like doublestar: ** flanked on both sides by non-separators is invalid
		idx := 0
		for {
			i := strings.Index(raw[idx:], "**")
			if i < 0 {
				break
			}
			pos := idx + i
			beforeOK := pos == 0 || raw[pos-1] == '/'
			afterPos := pos + 2
			afterOK := afterPos >= len(raw) || raw[afterPos] == '/'
			if !beforeOK && !afterOK {
				return nil, fmt.Errorf("invalid file filter [%s], invalid glob pattern", raw)
			}
			idx = pos + 2
		}
		re, err := regexp.Compile(globToRegexpSource(raw))
		if err != nil {
			// Patterns such as "*[" are silently never matching in the reference.
			return &fileFilter{raw: raw, isGlob: true}, nil
		}
		return &fileFilter{raw: raw, isGlob: true, globRegex: re}, nil
	}
	// literal full path -> anchored regexp, dots escaped, backslashes as slashes
	p := strings.ReplaceAll(raw, "\\", "/")
	p = strings.ReplaceAll(p, ".", "\\.")
	re, err := regexp.Compile("^" + p + "$")
	if err != nil {
		return nil, fmt.Errorf("invalid file filter [%s], regexp compile full path: [%s]", raw, err.Error())
	}
	return &fileFilter{raw: raw, regex: re}, nil
}

func (f *fileFilter) matches(filename string, isTest bool) bool {
	if f.isTest {
		return isTest
	}
	if f.isGlob {
		return f.globRegex != nil && f.globRegex.MatchString(filename)
	}
	return f.regex != nil && f.regex.MatchString(filename)
}

func compileRuleFilters(rc *ruleConfig) ([]*fileFilter, error) {
	var filters []*fileFilter
	for _, raw := range rc.Exclude {
		f, err := newFileFilter(raw)
		if err != nil {
			return nil, err
		}
		filters = append(filters, f)
	}
	return filters, nil
}

func validateRuleExcludes(cfg *config) error {
	for name, rc := range cfg.Rules {
		if rc == nil {
			continue
		}
		if _, err := compileRuleFilters(rc); err != nil {
			return fmt.Errorf("error in config of rule [%s] : [%s]", name, err.Error())
		}
	}
	return nil
}
