{"command":"cat > /workspace/linter.go <<'EOF'
package main

import (
	"go/ast"
	"go/importer"
	"go/parser"
	"go/scanner"
	"go/token"
	"go/types"
	"os"
	"regexp"
	"strings"
)

var generatedRe = regexp.MustCompile(`(?m)^// Code generated .* DO NOT EDIT\.$`)

type fileContext struct {
	name     string
	content  []byte
	lines    []string
	ast      *ast.File
	fset     *token.FileSet
	types    *types.Info
	pkg      *packageContext
	isTest   bool
	isXTest  bool // _test.go with package name ending _test (set after parse)
	comments []*ast.CommentGroup
}

type packageContext struct {
	files    []*fileContext
	fset     *token.FileSet
	typesPkg *types.Package
	name     string
	dir      string
}

type activeRule struct {
	def     *ruleDef
	cfg     *ruleConfig
	opts    interface{}
	filters []*fileFilter
}

func (fc *fileContext) pos(p token.Pos) token.Position {
	return fc.fset.Position(p)
}

func (fc *fileContext) nodeFailure(node ast.Node, msg, category string, confidence float64, replacement string) failure {
	return failure{
		Failure:  msg,
		Category: category,
		Position: failurePosition{
			Start: fc.fset.Position(node.Pos()),
			End:   fc.fset.Position(node.End()),
		},
		Confidence:      confidence,
		ReplacementLine: replacement,
	}
}

func (fc *fileContext) isTestFile() bool { return fc.isTest }

func lintAll(patterns []string, cfg *config, rules []*activeRule) ([]failure, error) {
	packages, err := resolvePatterns(patterns)
	if err != nil {
		return nil, err
	}
	// Compile per-rule filters.
	for _, r := range rules {
		filters, err := compileRuleFilters(r.cfg)
		if err != nil {
			// normally validated earlier
			r.filters = nil
		} else {
			r.filters = filters
		}
	}
	// Global excludes (already merged flag/config in cfg.Exclude)
	excludedFiles := resolveExcludeFiles(cfg.Exclude)

	var failures []failure
	for _, pkg := range packages {
		var files []string
		for _, f := range pkg.files {
			if !excludedFiles[f] {
				files = append(files, f)
			}
		}
		if len(files) == 0 {
			continue
		}
		failures = append(failures, lintPackage(files, pkg.dir, cfg, rules)...)
	}
	return failures, nil
}

func lintPackage(filenames []string, dir string, cfg *config, rules []*activeRule) []failure {
	fset := token.NewFileSet()
	pctx := &packageContext{fset: fset, dir: dir}
	var failures []failure

	// Parse files
	type parsedFile struct {
		fc        *fileContext
		parseErr  error
		errPos    token.Position
		generated bool
	}
	var parsed []*parsedFile
	for _, filename := range filenames {
		content, err := os.ReadFile(filename)
		if err != nil {
			continue
		}
		if !cfg.IgnoreGeneratedHeader && generatedRe.Match(content) {
			parsed = append(parsed, &parsedFile{generated: true})
			continue
		}
		astFile, parseErr := parser.ParseFile(fset, filename, content, parser.ParseComments)
		if parseErr != nil {
			pf := &parsedFile{parseErr: parseErr}
			// extract first position
			if list, ok := parseErr.(scanner.ErrorList); ok && len(list) > 0 {
				p := list[0].Pos
				p.Filename = filename
				p.Offset = 0
				pf.errPos = p
			} else if serr, ok := parseErr.(*scanner.Error); ok {
				p := serr.Pos
				p.Filename = filename
				p.Offset = 0
				pf.errPos = p
			} else {
				pf.errPos = token.Position{Filename: filename, Line: 1, Column: 1}
			}
			parsed = append(parsed, pf)
			continue
		}
		lines := strings.Split(string(content), "\n")
		fc := &fileContext{
			name:     filename,
			content:  content,
			lines:    lines,
			ast:      astFile,
			fset:     fset,
			pkg:      pctx,
			isTest:   strings.HasSuffix(filename, "_test.go"),
			comments: astFile.Comments,
		}
		if astFile.Name != nil && strings.HasSuffix(astFile.Name.Name, "_test") {
			fc.isXTest = true
		}
		pctx.files = append(pctx.files, fc)
		if pctx.name == "" && astFile.Name != nil {
			pctx.name = astFile.Name.Name
		}
		parsed = append(parsed, &parsedFile{fc: fc})
	}

	// Type-check grouped by package name
	typesByFile := map[*fileContext]*types.Info{}
	pkgByFile := map[*fileContext]*types.Package{}
	groups := map[string][]*fileContext{}
	var groupOrder []string
	for _, fc := range pctx.files {
		pname := fc.ast.Name.Name
		if _, ok := groups[pname]; !ok {
			groupOrder = append(groupOrder, pname)
		}
		groups[pname] = append(groups[pname], fc)
	}
	for _, pname := range groupOrder {
		group := groups[pname]
		var astFiles []*ast.File
		for _, fc := range group {
			astFiles = append(astFiles, fc.ast)
		}
		info := &types.Info{
			Types:      map[ast.Expr]types.TypeAndValue{},
			Defs:       map[*ast.Ident]types.Object{},
			Uses:       map[*ast.Ident]types.Object{},
			Implicits:  map[ast.Node]types.Object{},
			Selections: map[*ast.SelectorExpr]*types.Selection{},
			Scopes:     map[ast.Node]*types.Scope{},
			Instances:  map[*ast.Ident]types.Instance{},
		}
		conf := types.Config{Importer: defaultImporter(), FakeImportC: true, Error: func(error) {}}
		tpkg, _ := conf.Check(pname, fset, astFiles, info)
		for _, fc := range group {
			typesByFile[fc] = info
			pkgByFile[fc] = tpkg
		}
		if pctx.typesPkg == nil {
			pctx.typesPkg = tpkg
		}
	}
	for _, fc := range pctx.files {
		fc.types = typesByFile[fc]
		// store the package's types package specific to file's group on fc via pctx
		_ = pkgByFile[fc]
	}

	// Emit failures in file order as they were parsed (including invalid files)
	for _, pf := range parsed {
		if pf.generated {
			continue
		}
		if pf.parseErr != nil {
			// filename from errPos
			fname := pf.errPos.Filename
			f := failure{
				Severity:   severityWarning,
				Failure:    "invalid file " + fname + ": " + pf.parseErr.Error(),
				RuleName:   "",
				Category:   "validity",
				Position:   failurePosition{Start: pf.errPos, End: token.Position{}},
				Confidence: 1,
			}
			if f.Confidence >= cfg.Confidence {
				failures = append(failures, f)
			}
			continue
		}
		fc := pf.fc
		directives := parseDirectives(fc)
		for _, r := range rules {
			// per-rule file filters
			skip := false
			for _, filter := range r.filters {
				if filter.matches(fc.name, fc.isTest) {
					skip = true
					break
				}
			}
			if skip {
				continue
			}
			found := r.def.apply(fc, r.opts)
			for _, f := range found {
				if f.Confidence < cfg.Confidence {
					continue
				}
				if isDisabledByDirectives(directives, r.def.name, f.Position.Start.Line) {
					continue
				}
				f.RuleName = r.def.name
				f.Severity = effectiveSeverity(r.cfg.Severity)
				failures = append(failures, f)
			}
		}
	}
	return failures
}

var sharedImporter types.Importer

func defaultImporter() types.Importer {
	if sharedImporter == nil {
		sharedImporter = &fallbackImporter{gc: importer.Default(), src: importer.ForCompiler(token.NewFileSet(), "source", nil), cache: map[string]*types.Package{}}
	}
	return sharedImporter
}

type fallbackImporter struct {
	gc    types.Importer
	src   types.Importer
	cache map[string]*types.Package
}

func (fi *fallbackImporter) Import(path string) (*types.Package, error) {
	if p, ok := fi.cache[path]; ok {
		return p, nil
	}
	p, err := fi.gc.Import(path)
	if err != nil {
		p2, err2 := fi.src.Import(path)
		if err2 == nil {
			fi.cache[path] = p2
			return p2, nil
		}
		return nil, err
	}
	fi.cache[path] = p
	return p, nil
}
EOF
