package main

import (
	"strings"
)

type directive struct {
	line     int
	modifier string // disable, enable, disable-line, disable-next-line
	rules    []string // nil means all rules
}

func parseDirectives(fc *fileContext) []directive {
	var result []directive
	for _, group := range fc.comments {
		for _, c := range group.List {
			text := c.Text
			if !strings.HasPrefix(text, "//") {
				continue
			}
			d, ok := parseDirective(text)
			if !ok {
				continue
			}
			d.line = fc.fset.Position(c.Pos()).Line
			result = append(result, d)
		}
	}
	return result
}

func parseDirective(text string) (directive, bool) {
	s := strings.TrimLeft(text[2:], " \t")
	if !strings.HasPrefix(s, "revive:") {
		return directive{}, false
	}
	s = s[len("revive:"):]
	modifiers := []string{"disable-next-line", "disable-line", "disable", "enable"}
	var modifier string
	for _, m := range modifiers {
		if strings.HasPrefix(s, m) {
			modifier = m
			break
		}
	}
	if modifier == "" {
		return directive{}, false
	}
	rest := s[len(modifier):]
	if rest == "" {
		return directive{modifier: modifier}, true
	}
	switch {
	case rest[0] == ':':
		token := rest[1:]
		if idx := strings.IndexAny(token, " \t"); idx >= 0 {
			token = token[:idx]
		}
		token = strings.TrimSuffix(token, "\r")
		if token == "" {
			return directive{}, false
		}
		var rules []string
		for _, part := range strings.Split(token, ",") {
			if part != "" {
				rules = append(rules, part)
			}
		}
		// token consisting only of commas -> all rules (nil)
		return directive{modifier: modifier, rules: rules}, true
	case rest[0] == ' ' || rest[0] == '\t':
		return directive{modifier: modifier}, true
	default:
		return directive{}, false
	}
}

func (d directive) appliesTo(rule string) bool {
	if d.rules == nil {
		return true
	}
	for _, r := range d.rules {
		if r == rule {
			return true
		}
	}
	return false
}

func isDisabledByDirectives(directives []directive, rule string, line int) bool {
	// single-line directives
	for _, d := range directives {
		if !d.appliesTo(rule) {
			continue
		}
		if d.modifier == "disable-line" && d.line == line {
			return true
		}
		if d.modifier == "disable-next-line" && d.line+1 == line {
			return true
		}
	}
	// range directives
	disabled := false
	open := false
	start := 0
	type interval struct{ from, to int }
	var intervals []interval
	for _, d := range directives {
		if !d.appliesTo(rule) {
			continue
		}
		switch d.modifier {
		case "disable":
			if !open {
				open = true
				start = d.line
			}
		case "enable":
			if open {
				intervals = append(intervals, interval{from: start, to: d.line})
				open = false
			}
		}
	}
	if open {
		intervals = append(intervals, interval{from: start, to: int(^uint(0) >> 1)})
	}
	for _, iv := range intervals {
		if line >= iv.from && line <= iv.to {
			disabled = true
			break
		}
	}
	return disabled
}
