}

type checkstyleFormatter struct{}

func confidenceString(c float64) string {
	// Go's %v for float64: 1 -> "1", 0.8 -> "0.8"
	return fmt.Sprintf("%v", c)
}

func (checkstyleFormatter) Format(failures []failure, cfg *config) (string, error) {
	byFile := map[string][]failure{}
	var files []string
	for _, f := range failures {
		fn := f.Position.Start.Filename
		if _, ok := byFile[fn]; !ok {
			files = append(files, fn)
		}
		byFile[fn] = append(byFile[fn], f)
	}
	sort.Strings(files)
	root := checkstyleRoot{Version: "5.0"}
	for _, fn := range files {
		cf := checkstyleFile{Name: fn}
		for _, f := range byFile[fn] {
			cf.Errors = append(cf.Errors, checkstyleError{
				Line:     f.Position.Start.Line,
				Column:   f.Position.Start.Column,
				Message:  fmt.Sprintf("%s (confidence %s)", f.Failure, confidenceString(f.Confidence)),
				Severity: string(f.Severity),
				Source:   "revive/" + f.RuleName,
			})
		}
		root.Files = append(root.Files, cf)
	}
	out, err := xml.MarshalIndent(root, "", "    ")
	if err != nil {
		return "", err
	}
	// Original output: header with single quotes, root element on own line pretty printed.
	// xml.MarshalIndent output reworked to match observed indentation:
	pretty := reworkCheckstyle(string(out))
	return "<?xml version='1.0' encoding='UTF-8'?>\n" + pretty + "\n", nil
}

func reworkCheckstyle(s string) string {
	// encoding/xml with indent "    " produces
	// <checkstyle...>\n    <file...>\n        <error...></error> ...
	// Original has:
	// <checkstyle version="5.0">
	//     <file name="...">
	//       <error .../>
	//     </file>
	// </checkstyle>
	// In particular <error> indented by 6 spaces and self-closed.
	// We reconstruct manually form the xml lib output is brittle; instead
	// this function transforms lines.
	lines := strings.Split(s, "\n")
	var out []string
	for _, line := range lines {
		trimmed := strings.TrimSpace(line)
		switch {
		case strings.HasPrefix(trimmed, "<file "):
			out = append(out, "    "+trimmed)
		case strings.HasPrefix(trimmed, "<error "):
			// convert <error ...></error> to <error .../>
			trimmed = strings.Replace(trimmed, "></error>", "/>", 1)
			out = append(out, "      "+trimmed)
		case trimmed == "</file>":
			out = append(out, "    </file>")
		default:
			out = append(out, trimmed)
		}
	}
	return strings.Join(out, "\n")
}

// sarif

type sarifRoot struct {
	Runs    []sarifRun `json:"runs"`
	Version string     `json:"version"`
}
type sarifRun struct {
	Results []sarifResult `json:"results,omitempty"`
	Tool    sarifTool     `json:"tool"`
}
type sarifTool struct {
	Driver sarifDriver `json:"driver"`
}
type sarifDriver struct {
	InformationURI string      `json:"informationUri"`
	Name           string      `json:"name"`
	Rules          []sarifRule `json:"rules,omitempty"`
}
type sarifRule struct {
	HelpURI    string           `json:"helpUri"`
	ID         string           `json:"id"`
	Properties sarifRuleProps   `json:"properties"`
}
type sarifRuleProps struct {
	Severity string `json:"severity"`
}
type sarifResult struct {
	Level     string          `json:"level,omitempty"`
	Locations []sarifLocation `json:"locations"`
	Message   sarifMessage    `json:"message"`
	RuleID    string          `json:"ruleId"`
}
type sarifMessage struct {
	Text string `json:"text"`
}
type sarifLocation struct {
	PhysicalLocation sarifPhysicalLocation `json:"physicalLocation"`
}
type sarifPhysicalLocation struct {
	ArtifactLocation sarifArtifactLocation `json:"artifactLocation"`
	Region           sarifRegion           `json:"region"`
}
type sarifArtifactLocation struct {
	URI string `json:"uri"`
}
type sarifRegion struct {
	StartColumn int `json:"startColumn"`
	StartLine   int `json:"startLine"`
}

type sarifFormatter struct{}

func (sarifFormatter) Format(failures []failure, cfg *config) (string, error) {
	var results []sarifResult
	for _, f := range failures {
		level := ""
		if rc, ok := cfg.Rules[f.RuleName]; ok && rc != nil {
			level = string(rc.Severity)
		}
		results = append(results, sarifResult{
			Level: level,
			Locations: []sarifLocation{{
				PhysicalLocation: sarifPhysicalLocation{
					ArtifactLocation: sarifArtifactLocation{URI: f.Position.Start.Filename},
					Region:           sarifRegion{StartColumn: f.Position.Start.Column, StartLine: f.Position.Start.Line},
				},
			}},
			Message: sarifMessage{Text: f.Failure},
			RuleID:  f.RuleName,
		})
	}
	var rules []sarifRule
	// Reference behaviour: exactly one (map-iteration chosen) rule entry.
	for name, rc := range cfg.Rules {
		sev := ""
		if rc != nil {
			sev = string(rc.Severity)
		}
		rules = []sarifRule{{
			HelpURI:    ruleURL(name),
			ID:         name,
			Properties: sarifRuleProps{Severity: sev},
		}}
		break
	}
	root := sarifRoot{
		Runs: []sarifRun{{
			Results: results,
			Tool: sarifTool{Driver: sarifDriver{
				InformationURI: "https://revive.run",
				Name:           "revive",
				Rules:          rules,
			}},
		}},
		Version: "2.1.0",
	}
	var buf bytes.Buffer
	enc := json.NewEncoder(&buf)
	enc.SetIndent("", "  ")
	enc.SetEscapeHTML(false)
	if err := enc.Encode(root); err != nil {
		return "", err
	}
	return buf.String(), nil
}
