type friendlyFormatter struct{}

func plural(n int, singular, plural string) string {
	if n == 1 {
		return singular
	}
	return plural
}

func (friendlyFormatter) Format(failures []failure, cfg *config) (string, error) {
	if len(failures) == 0 {
		return "", nil
	}
	var b strings.Builder
	errorsByRule := map[string]int{}
	warningsByRule := map[string]int{}
	numErrors, numWarnings := 0, 0
	for _, f := range failures {
		icon := "⚠"
		if f.Severity == severityError {
			icon = "✘"
			numErrors++
			errorsByRule[f.RuleName]++
		} else {
			numWarnings++
			warningsByRule[f.RuleName]++
		}
		s := f.Position.Start
		fmt.Fprintf(&b, "  %s  %s  %s\n", icon, ruleURL(f.RuleName), f.Failure)
		fmt.Fprintf(&b, "  %s:%d:%d\n", s.Filename, s.Line, s.Column)
		b.WriteString("\n")
	}
	summaryIcon := "⚠"
	if numErrors > 0 {
		summaryIcon = "✘"
	}
	total := len(failures)
	fmt.Fprintf(&b, "%s %d %s (%d %s, %d %s)\n", summaryIcon, total, plural(total, "problem", "problems"), numErrors, plural(numErrors, "error", "errors"), numWarnings, plural(numWarnings, "warning", "warnings"))
	b.WriteString("\n")
	writeCounts := func(title string, counts map[string]int) {
		if len(counts) == 0 {
			return
		}
		fmt.Fprintf(&b, "%s:\n", title)
		type kv struct {
			name  string
			count int
		}
		var list []kv
		for k, v := range counts {
			list = append(list, kv{k, v})
		}
		sort.Slice(list, func(i, j int) bool {
			if list[i].count != list[j].count {
				return list[i].count > list[j].count
			}
			return list[i].name < list[j].name
		})
		for _, kv := range list {
			fmt.Fprintf(&b, "  %d  %s\n", kv.count, kv.name)
		}
		b.WriteString("\n")
	}
	writeCounts("Errors", errorsByRule)
	writeCounts("Warnings", warningsByRule)
	b.WriteString("\n")
	return b.String(), nil
}

