	byFile := map[string][]failure{}
	var files []string
	for _, f := range failures {
		fn := f.Position.Start.Filename
		if _, ok := byFile[fn]; !ok {
			files = append(files, fn)
		}
		byFile[fn] = append(byFile[fn], f)
	}
	sort.Strings(files)
	var b strings.Builder
	numErrors, numWarnings := 0, 0
	for _, f := range failures {
		if f.Severity == severityError {
			numErrors++
		} else {
			numWarnings++
		}
	}
	for _, fn := range files {
		group := byFile[fn]
		b.WriteString(fn + "\n")
		// column widths
		maxPos, maxURL := 0, 0
		for _, f := range group {
			pos := fmt.Sprintf("(%d, %d)", f.Position.Start.Line, f.Position.Start.Column)
			if len(pos) > maxPos {
				maxPos = len(pos)
			}
			if l := len(ruleURL(f.RuleName)); l > maxURL {
				maxURL = l
			}
		}
		for _, f := range group {
			pos := fmt.Sprintf("(%d, %d)", f.Position.Start.Line, f.Position.Start.Column)
			url := ruleURL(f.RuleName)
			fmt.Fprintf(&b, "  %s%s  %s%s  %s\n", pos, strings.Repeat(" ", maxPos-len(pos)), url, strings.Repeat(" ", maxURL-len(url)), f.Failure)
		}
		b.WriteString("\n")
	}
	total := len(failures)
	fmt.Fprintf(&b, "\n ✖ %d %s (%d %s) (%d %s)\n", total, plural(total, "problem", "problems"), numErrors, plural(numErrors, "error", "errors"), numWarnings, plural(numWarnings, "warning", "warnings"))
