package main

import (
	"bytes"
	"fmt"
	"go/ast"
	"go/printer"
	"go/token"
	"go/types"
	"strings"
	"unicode"
)

func (fc *fileContext) nodeString(node interface{}) string {
	if s, ok := node.(string); ok {
		return s
	}
	var buf bytes.Buffer
	_ = printer.Fprint(&buf, fc.fset, node)
	return buf.String()
}

// String representation of a node's source (as in source text, trimmed)
func (fc *fileContext) sourceText(node ast.Node) string {
	if node == nil {
		return ""
	}
	start := fc.fset.Position(node.Pos()).Offset
	end := fc.fset.Position(node.End()).Offset
	if start < 0 || end > len(fc.content) || start > end {
		return fc.nodeString(node)
	}
	return string(fc.content[start:end])
}

func isExportedName(name string) bool {
	for _, r := range name {
		return unicode.IsUpper(r)
	}
	return false
}

func (fc *fileContext) typeOf(expr ast.Expr) types.Type {
	if fc.types == nil || expr == nil {
		return nil
	}
	if tv, ok := fc.types.Types[expr]; ok {
		return tv.Type
	}
	// For idents, check Defs/Uses
	if id, ok := expr.(*ast.Ident); ok {
		if obj := fc.types.Defs[id]; obj != nil {
			return obj.Type()
		}
		if obj := fc.types.Uses[id]; obj != nil {
			return obj.Type()
		}
	}
	return nil
}

func isErrorType(t types.Type) bool {
	if t == nil {
		return false
	}
	// error interface (universe)
	errorType := types.Universe.Lookup("error").Type()
	if types.Identical(t, errorType) {
		return true
	}
	// named type implementing error? For error-return golint only checks error interface identity via isNamedType?
	// We check implements error
	iface, _ := errorType.Underlying().(*types.Interface)
	if iface != nil && types.Implements(t, iface) {
		// But that would treat custom error impl as error; golint's check uses types equivalent? See probes: func e()(E,int) where E implements error was not flagged by error-return, so only identical error interface.
		return false
	}
	return false
}

// object type for an Ident
func (fc *fileContext) objectOf(id *ast.Ident) types.Object {
	if fc.types == nil || id == nil {
		return nil
	}
	if obj := fc.types.Uses[id]; obj != nil {
		return obj
	}
	return fc.types.Defs[id]
}

func baseTypeName(expr ast.Expr) string {
	switch t := expr.(type) {
	case *ast.Ident:
		return t.Name
	case *ast.StarExpr:
		return baseTypeName(t.X)
	case *ast.SelectorExpr:
		return t.Sel.Name
	case *ast.IndexExpr:
		return baseTypeName(t.X)
	case *ast.IndexListExpr:
		return baseTypeName(t.X)
	default:
		return ""
	}
}

// receiver type name for FuncDecl
func receiverTypeName(fd *ast.FuncDecl) string {
	if fd.Recv == nil || len(fd.Recv.List) == 0 {
		return ""
	}
	return baseTypeName(fd.Recv.List[0].Type)
}

func receiverTypeString(fc *fileContext, fd *ast.FuncDecl) string {
	if fd.Recv == nil || len(fd.Recv.List) == 0 {
		return ""
	}
	return fc.nodeString(fd.Recv.List[0].Type)
}

func isBoolIdent(e ast.Expr) bool {
	id, ok := e.(*ast.Ident)
	return ok && (id.Name == "true" || id.Name == "false")
}

func typeStringQualified(t types.Type) string {
	return types.TypeString(t, func(p *types.Package) string {
		if p == nil {
			return ""
		}
		return p.Name()
	})
}

// Checks if node is a call to a selector pkgName.Func where pkgName is the local import name resolving to given import path (if types info usable), otherwise lexical name.
func (fc *fileContext) isCallTo(call *ast.CallExpr, pkgPath, funcName string) bool {
	sel, ok := call.Fun.(*ast.SelectorExpr)
	if !ok || sel.Sel.Name != funcName {
		return false
	}
	// Resolve via types: object for sel.Sel
	if fc.types != nil {
		if obj, ok := fc.types.Uses[sel.Sel]; ok && obj != nil && obj.Pkg() != nil {
			return obj.Pkg().Path() == pkgPath
		}
		// If selection info
		if selInfo := fc.types.Selections[sel]; selInfo != nil && selInfo.Obj() != nil && selInfo.Obj().Pkg() != nil {
			return selInfo.Obj().Pkg().Path() == pkgPath
		}
	}
	// Lexical fallback: X is ident equal to last component of pkgPath or alias
	id, ok := sel.X.(*ast.Ident)
	if !ok {
		return false
