	registerRule("range", nil, ruleRange)
	registerRule("receiver-naming", nil, ruleReceiverNaming)
	registerRule("redefines-builtin-id", nil, ruleRedefinesBuiltin)
	registerRule("superfluous-else", nil, ruleSuperfluousElse)
	registerRule("time-naming", nil, ruleTimeNaming)
	registerRule("unexported-return", nil, ruleUnexportedReturn)
	registerRule("unreachable-code", nil, ruleUnreachableCode)
	registerRule("unused-parameter", configureUnusedParameter, ruleUnusedParameter)
	registerRule("var-declaration", nil, ruleVarDeclaration)
	registerRule("var-naming", configureVarNaming, ruleVarNaming)
}

func ruleBlankImports(fc *fileContext, _ interface{}) []failure {
	if fc.ast.Name != nil && fc.ast.Name.Name == "main" {
		return nil
	}
	if fc.isTest {
		return nil
	}
	var out []failure
	for _, decl := range fc.ast.Decls {
		gd, ok := decl.(*ast.GenDecl)
		if !ok || gd.Tok != token.IMPORT {
			continue
		}
		for _, spec := range gd.Specs {
			is, ok := spec.(*ast.ImportSpec)
			if !ok || is.Name == nil || is.Name.Name != "_" {
				continue
			}
			if is.Doc != nil && len(is.Doc.List) > 0 {
				continue
			}
			if is.Comment != nil && len(is.Comment.List) > 0 {
				continue
			}
			out = append(out, fc.nodeFailure(is, "a blank import should be only in a main or test package, or have a comment justifying it", "imports", 1, ""))
		}
	}
	return out
}

func ruleDotImports(fc *fileContext, _ interface{}) []failure {
	var out []failure
	for _, decl := range fc.ast.Decls {
		gd, ok := decl.(*ast.GenDecl)
		if !ok || gd.Tok != token.IMPORT {
			continue
		}
		for _, spec := range gd.Specs {
			is, ok := spec.(*ast.ImportSpec)
			if !ok || is.Name == nil {
				continue
			}
			if is.Name.Name == "." {
				out = append(out, fc.nodeFailure(is, "should not use dot imports", "imports", 1, ""))
			}
		}
	}
	return out
}

// context-as-argument
type ctxArgOptions struct {
	allowTypesBefore []string
}

func configureContextAsArgument(args []interface{}) (interface{}, error) {
	opts := &ctxArgOptions{}
	if len(args) == 0 {
		return opts, nil
	}
	// Only the first argument is inspected by the reference implementation.
	arg := args[0]
	m, ok := arg.(map[string]interface{})
	if !ok {
		return nil, fmt.Errorf("invalid argument to the context-as-argument rule. Expecting a k,v map, got %s", typeName(arg))
	}
	for k, v := range m {
		if k != "allowTypesBefore" {
			return nil, fmt.Errorf("invalid argument to the context-as-argument rule. Unrecognized key %s", k)
		}
		s, ok := v.(string)
		if !ok {
			return nil, fmt.Errorf("invalid argument to the context-as-argument.allowTypesBefore rule. Expecting a string, got %s", typeName(v))
		}
		opts.allowTypesBefore = strings.Split(s, ",")
	}
	return opts, nil
}

func (fc *fileContext) isContextType(expr ast.Expr) bool {
	// by type identity if available
	if t := fc.typeOf(expr); t != nil {
		if named, ok := t.(*types.Named); ok {
			obj := named.Obj()
			if obj != nil && obj.Name() == "Context" && obj.Pkg() != nil && obj.Pkg().Path() == "context" {
				return true
			}
		}
	}
	sel, ok := expr.(*ast.SelectorExpr)
	if !ok || sel.Sel.Name != "Context" {
		return false
	}
	id, ok := sel.X.(*ast.Ident)
	return ok && fc.importNameForPath("context") == id.Name
}

func ruleContextAsArgument(fc *fileContext, optsI interface{}) []failure {
	opts, _ := optsI.(*ctxArgOptions)
	if opts == nil {
		opts = &ctxArgOptions{}
	}
	var out []failure
	for _, decl := range fc.ast.Decls {
		fd, ok := decl.(*ast.FuncDecl)
		if !ok || fd.Type.Params == nil {
			continue
		}
		params := fd.Type.Params.List
		if len(params) == 0 {
			continue
		}
		if fc.isContextType(params[0].Type) {
			continue
		}
		for i := 1; i < len(params); i++ {
			if !fc.isContextType(params[i].Type) {
				continue
			}
			// check allowed types before ctx
			allowed := true
			if len(opts.allowTypesBefore) == 0 {
				allowed = false
			} else {
				for j := 0; j < i; j++ {
					ts := fc.nodeString(params[j].Type)
					found := false
					for _, a := range opts.allowTypesBefore {
						if a == ts {
							found = true
							break
						}
					}
					if !found {
						allowed = false
						break
					}
				}
			}
			if !allowed {
				out = append(out, fc.nodeFailure(params[i], "context.Context should be the first parameter of a function", "arg-order", 0.9, ""))
			}
			break // only first context parameter considered
		}
	}
	return out
}

func ruleContextKeysType(fc *fileContext, _ interface{}) []failure {
	var out []failure
	ast.Inspect(fc.ast, func(n ast.Node) bool {
		call, ok := n.(*ast.CallExpr)
		if !ok {
			return true
		}
		if !fc.isCallTo(call, "context", "WithValue") || len(call.Args) < 2 {
			return true
		}
		t := fc.typeOf(call.Args[1])
		if t == nil {
			return true
		}
		if basic, ok := t.Underlying().(*types.Basic); ok {
			// Only if the type itself is a basic type (not a defined type with basic underlying)
			if _, isBasic := t.(*types.Basic); isBasic {
				out = append(out, fc.nodeFailure(call, fmt.Sprintf("should not use basic type %s as key in context.WithValue", basic.String()), "content", 1, ""))
			}
		}
		return true
	})
	return out
}

func ruleEmptyBlock(fc *fileContext, _ interface{}) []failure {
	var out []failure
	// Walk with parent tracking
	var stack []ast.Node
	ast.Inspect(fc.ast, func(n ast.Node) bool {
		if n == nil {
			stack = stack[:len(stack)-1]
			return true
		}
		if block, ok := n.(*ast.BlockStmt); ok && len(block.List) == 0 {
			skip := false
			if len(stack) > 0 {
				switch stack[len(stack)-1].(type) {
				case *ast.FuncDecl, *ast.FuncLit, *ast.SelectStmt, *ast.SwitchStmt, *ast.TypeSwitchStmt:
					skip = true
				}
			}
			if !skip {
				out = append(out, fc.nodeFailure(block, "this block is empty, you can remove it", "logic", 1, ""))
			}
		}
		stack = append(stack, n)
		return true
	})
	return out
}

func isNewErrorCall(fc *fileContext, expr ast.Expr) bool {
	call, ok := expr.(*ast.CallExpr)
	if !ok {
		return false
	}
	return fc.isCallTo(call, "errors", "New") || fc.isCallTo(call, "fmt", "Errorf")
}

func ruleErrorNaming(fc *fileContext, _ interface{}) []failure {
	var out []failure
	for _, decl := range fc.ast.Decls {
		gd, ok := decl.(*ast.GenDecl)
		if !ok || gd.Tok != token.VAR {
			continue
		}
		for _, specI := range gd.Specs {
			spec, ok := specI.(*ast.ValueSpec)
			if !ok || len(spec.Names) != 1 || len(spec.Values) != 1 {
				continue
			}
			if !isNewErrorCall(fc, spec.Values[0]) {
				continue
			}
			name := spec.Names[0]
			if name.Name == "_" {
				continue
			}
			if isExportedName(name.Name) {
				if strings.HasPrefix(name.Name, "Err") || strings.HasPrefix(name.Name, "Error") {
					continue
				}
				out = append(out, fc.nodeFailure(name, fmt.Sprintf("error var %s should have name of the form ErrFoo", name.Name), "naming", 0.9, ""))
			} else {
				if strings.HasPrefix(name.Name, "err") || strings.HasPrefix(name.Name, "error") {
					continue
				}
				out = append(out, fc.nodeFailure(name, fmt.Sprintf("error var %s should have name of the form errFoo", name.Name), "naming", 0.9, ""))
			}
		}
	}
	return out
}

func flattenFieldTypes(fl *ast.FieldList, fc *fileContext) []ast.Expr {
	if fl == nil {
		return nil
	}
	var out []ast.Expr
	for _, f := range fl.List {
		n := len(f.Names)
		if n == 0 {
			n = 1
		}
		for i := 0; i < n; i++ {
			out = append(out, f.Type)
		}
	}
	return out
}

func (fc *fileContext) isErrorExpr(expr ast.Expr) bool {
	if t := fc.typeOf(expr); t != nil {
		return isErrorType(t)
	}
	if id, ok := expr.(*ast.Ident); ok && id.Name == "error" {
		return true
	}
	return false
}

func ruleErrorReturn(fc *fileContext, _ interface{}) []failure {
	var out []failure
	for _, decl := range fc.ast.Decls {
		fd, ok := decl.(*ast.FuncDecl)
		if !ok {
			continue
		}
		results := flattenFieldTypes(fd.Type.Results, fc)
		if len(results) <= 1 {
			continue
		}
		if fc.isErrorExpr(results[len(results)-1]) {
			continue
		}
		for _, r := range results[:len(results)-1] {
			if fc.isErrorExpr(r) {
				out = append(out, fc.nodeFailure(fd, "error should be the last type when returning multiple items", "style", 0.9, ""))
				break
			}
		}
	}
	return out
}

func ruleErrorStrings(fc *fileContext, _ interface{}) []failure {
	var out []failure
	ast.Inspect(fc.ast, func(n ast.Node) bool {
		call, ok := n.(*ast.CallExpr)
		if !ok || len(call.Args) == 0 {
			return true
		}
		if !fc.isCallTo(call, "errors", "New") && !fc.isCallTo(call, "fmt", "Errorf") {
			return true
		}
		lit, ok := call.Args[0].(*ast.BasicLit)
		if !ok || lit.Kind != token.STRING {
			return true
		}
		s, err := strconv.Unquote(lit.Value)
		if err != nil || s == "" {
			return true
		}
		runes := []rune(s)
		last := runes[len(runes)-1]
		if last == '.' || last == '!' || last == ':' || last == '\n' {
			out = append(out, fc.nodeFailure(lit, "error strings should not be capitalized or end with punctuation or a newline", "errors", 0.8, ""))
		}
		return true
	})
	return out
}

func (fc *fileContext) replacementLine(node ast.Node, replacement string) string {
	start := fc.fset.Position(node.Pos())
	end := fc.fset.Position(node.End())
	if start.Line != end.Line {
		return ""
	}
	if start.Line-1 < 0 || start.Line-1 >= len(fc.lines) {
		return ""
	}
	line := fc.lines[start.Line-1]
	line = strings.TrimSuffix(line, "\r")
	lineStart := start.Offset - (start.Column - 1)
	sIdx := start.Offset - lineStart
	eIdx := end.Offset - lineStart
	if sIdx < 0 || eIdx > len(line) || sIdx > eIdx {
		return ""
	}
	return line[:sIdx] + replacement + line[eIdx:]
}

func ruleErrorf(fc *fileContext, _ interface{}) []failure {
	var out []failure
	ast.Inspect(fc.ast, func(n ast.Node) bool {
		call, ok := n.(*ast.CallExpr)
		if !ok || !fc.isCallTo(call, "errors", "New") || len(call.Args) != 1 {
			return true
		}
		inner, ok := call.Args[0].(*ast.CallExpr)
		if !ok || !fc.isCallTo(inner, "fmt", "Sprintf") {
			return true
		}
		var argStrs []string
		for _, a := range inner.Args {
			argStrs = append(argStrs, fc.nodeString(a))
		}
		replacement := fmt.Sprintf("fmt.Errorf(%s)", strings.Join(argStrs, ", "))
		rep := fc.replacementLine(call, replacement)
		out = append(out, fc.nodeFailure(call, "should replace errors.New(fmt.Sprintf(...)) with fmt.Errorf(...)", "errors", 1, rep))
		return true
	})
	return out
}

func ruleIncrementDecrement(fc *fileContext, _ interface{}) []failure {
	var out []failure
	ast.Inspect(fc.ast, func(n ast.Node) bool {
		as, ok := n.(*ast.AssignStmt)
		if !ok {
			return true
		}
		if as.Tok != token.ADD_ASSIGN && as.Tok != token.SUB_ASSIGN {
			return true
		}
		if len(as.Lhs) != 1 || len(as.Rhs) != 1 {
			return true
		}
		lit, ok := as.Rhs[0].(*ast.BasicLit)
		if !ok || lit.Kind != token.INT || lit.Value != "1" {
			return true
		}
		op := "++"
		if as.Tok == token.SUB_ASSIGN {
			op = "--"
		}
		msg := fmt.Sprintf("should replace %s with %s%s", fc.nodeString(as), fc.nodeString(as.Lhs[0]), op)
		out = append(out, fc.nodeFailure(as, msg, "unary-op", 0.8, ""))
		return true
	})
	return out
}

func lastStmt(block *ast.BlockStmt) ast.Stmt {
	if block == nil || len(block.List) == 0 {
		return nil
	}
	return block.List[len(block.List)-1]
}

func ruleIndentErrorFlow(fc *fileContext, _ interface{}) []failure {
	var out []failure
	ast.Inspect(fc.ast, func(n ast.Node) bool {
		ifs, ok := n.(*ast.IfStmt)
		if !ok || ifs.Else == nil {
			return true
		}
		// Else must be a block (not else-if)
		elseBlock, ok := ifs.Else.(*ast.BlockStmt)
		if !ok {
			return true
		}
		if _, isRet := lastStmt(ifs.Body).(*ast.ReturnStmt); isRet {
			out = append(out, fc.nodeFailure(elseBlock, "if block ends with a return statement, so drop this else and outdent its block", "", 1, ""))
		}
		return true
	})
	return out
}

func terminatingCallKind(fc *fileContext, stmt ast.Stmt) (string, bool) {
	exprStmt, ok := stmt.(*ast.ExprStmt)
	if !ok {
		return "", false
	}
	call, ok := exprStmt.X.(*ast.CallExpr)
	if !ok {
		return "", false
	}
	// panic(...)
	if id, ok := call.Fun.(*ast.Ident); ok && id.Name == "panic" {
		return "panic", true
	}
	if fc.isCallTo(call, "os", "Exit") {
		return "os.Exit", true
	}
	for _, fn := range []string{"Fatal", "Fatalf", "Fatalln"} {
		if fc.isCallTo(call, "log", fn) {
			return "log." + fn, true
		}
	}
	return "", false
}

func ruleSuperfluousElse(fc *fileContext, _ interface{}) []failure {
	var out []failure
	ast.Inspect(fc.ast, func(n ast.Node) bool {
		ifs, ok := n.(*ast.IfStmt)
		if !ok || ifs.Else == nil {
			return true
		}
		elseBlock, ok := ifs.Else.(*ast.BlockStmt)
		if !ok {
			return true
		}
		last := lastStmt(ifs.Body)
		var msg string
		switch s := last.(type) {
		case *ast.BranchStmt:
			switch s.Tok {
			case token.BREAK:
				msg = "if block ends with a break statement, so drop this else and outdent its block"
			case token.CONTINUE:
				msg = "if block ends with a continue statement, so drop this else and outdent its block"
			case token.GOTO:
				msg = "if block ends with a goto statement, so drop this else and outdent its block"
			default:
				return true
			}
		default:
			if kind, ok := terminatingCallKind(fc, last); ok {
				msg = fmt.Sprintf("if block ends with call to %s function, so drop this else and outdent its block", kind)
			} else {
				return true
			}
		}
		out = append(out, fc.nodeFailure(elseBlock, msg, "", 1, ""))
		return true
	})
	return out
}

func (fc *fileContext) failureRange(start, end token.Pos, msg, category string, conf float64) failure {
	return failure{
		Failure:    msg,
		Category:   category,
		Position:   failurePosition{Start: fc.fset.Position(start), End: fc.fset.Position(end)},
		Confidence: conf,
	}
}

func rulePackageComments(fc *fileContext, _ interface{}) []failure {
	if fc.isTest {
		return nil
	}
	pkgName := fc.ast.Name.Name
	if fc.ast.Doc != nil {
		text := fc.ast.Doc.Text()
		expected := "Package " + pkgName + " "
		if !strings.HasPrefix(text, expected) {
			return []failure{fc.nodeFailure(fc.ast.Doc, fmt.Sprintf("package comment should be of the form \"Package %s ...\"", pkgName), "comments", 1, "")}
		}
		return nil
	}
	// No doc on this file: if any non-test file in the package has a doc, skip; else only first file reports.
	var firstNonTest *fileContext
	for _, f := range fc.pkg.files {
		if f.isTest {
			continue
		}
		if firstNonTest == nil {
			firstNonTest = f
		}
		if f.ast.Doc != nil {
			return nil
		}
	}
	if firstNonTest != fc {
		return nil
	}
	return []failure{fc.failureRange(fc.ast.Package, fc.ast.Name.End(), "should have a package comment", "comments", 1)}
}

func ruleRange(fc *fileContext, _ interface{}) []failure {
	var out []failure
	ast.Inspect(fc.ast, func(n ast.Node) bool {
		rs, ok := n.(*ast.RangeStmt)
		if !ok || rs.Key == nil || rs.Value == nil {
			return true
		}
		id, ok := rs.Value.(*ast.Ident)
		if !ok || id.Name != "_" {
			return true
		}
		// replacement line: prefix of the line up to '{' of body, with ", _" removed
		rep := ""
		if rs.Body != nil {
			startPos := fc.fset.Position(rs.Pos())
			lineStart := startPos.Offset - (startPos.Column - 1)
			bodyEnd := fc.fset.Position(rs.Body.Pos()).Offset // offset of '{', +1 to include
			if lineStart >= 0 && bodyEnd+1 <= len(fc.content) {
				segment := string(fc.content[lineStart : bodyEnd+1])
				// remove the part between Key.End and Value.End within segment
				keyEnd := fc.fset.Position(rs.Key.End()).Offset - lineStart
				valEnd := fc.fset.Position(rs.Value.End()).Offset - lineStart
				if keyEnd >= 0 && valEnd <= len(segment) && keyEnd <= valEnd && fc.fset.Position(rs.Body.Pos()).Line == startPos.Line {
					rep = segment[:keyEnd] + segment[valEnd:]
				}
			}
		}
		tok := ":="
		if rs.Tok == token.ASSIGN {
			tok = "="
		}
		msg := fmt.Sprintf("should omit 2nd value from range; this loop is equivalent to `for %s %s range ...`", fc.nodeString(rs.Key), tok)
		out = append(out, fc.nodeFailure(rs.Value, msg, "", 1, rep))
		return true
	})
	return out
}

func ruleReceiverNaming(fc *fileContext, _ interface{}) []failure {
	var out []failure
	seen := map[string]string{}
	for _, decl := range fc.ast.Decls {
		fd, ok := decl.(*ast.FuncDecl)
		if !ok || fd.Recv == nil || len(fd.Recv.List) == 0 {
			continue
		}
		field := fd.Recv.List[0]
		if len(field.Names) == 0 {
			continue
		}
		name := field.Names[0].Name
		typeName := baseTypeName(field.Type)
		if name == "_" {
			out = append(out, fc.nodeFailure(fd, "receiver name should not be an underscore, omit the name if it is unused", "naming", 1, ""))
			continue
		}
		if name == "this" || name == "self" {
			out = append(out, fc.nodeFailure(fd, `receiver name should be a reflection of its identity; don't use generic names such as "this" or "self"`, "naming", 1, ""))
			continue
		}
		if prev, ok := seen[typeName]; ok {
			if prev != name {
				out = append(out, fc.nodeFailure(fd, fmt.Sprintf("receiver name %s should be consistent with previous receiver name %s for %s", name, prev, typeName), "naming", 1, ""))
			}
		} else {
			seen[typeName] = name
		}
	}
	return out
}

// builtins
var builtinTypes = map[string]bool{
	"bool": true, "byte": true, "complex64": true, "complex128": true, "error": true,
	"float32": true, "float64": true, "int": true, "int8": true, "int16": true, "int32": true, "int64": true,
	"rune": true, "string": true, "uint": true, "uint8": true, "uint16": true, "uint32": true, "uint64": true,
	"uintptr": true, "any": true,
}
var builtinFuncs = map[string]bool{
	"append": true, "cap": true, "close": true, "complex": true, "copy": true, "delete": true,
	"imag": true, "len": true, "make": true, "new": true, "panic": true, "print": true, "println": true,
	"real": true, "recover": true, "min": true, "max": true, "clear": true,
}
var builtinConsts = map[string]bool{
	"true": true, "false": true, "iota": true, "nil": true,
}

func builtinKind(name string) string {
	if builtinTypes[name] {
		return "type"
	}
	if builtinFuncs[name] {
		return "function"
	}
	if builtinConsts[name] {
		return "constant or variable"
	}
	return ""
}

func ruleRedefinesBuiltin(fc *fileContext, _ interface{}) []failure {
	var out []failure
	checkName := func(node ast.Node, name string) {
		kind := builtinKind(name)
		if kind == "" {
			return
		}
		out = append(out, fc.nodeFailure(node, fmt.Sprintf("redefinition of the built-in %s %s", kind, name), "logic", 1, ""))
	}
	checkFields := func(fl *ast.FieldList) {
		if fl == nil {
			return
		}
		for _, field := range fl.List {
			for _, name := range field.Names {
				if builtinKind(name.Name) != "" {
					out = append(out, fc.nodeFailure(name, fmt.Sprintf("redefinition of the built-in %s %s", builtinKind(name.Name), name.Name), "logic", 1, ""))
				}
			}
		}
	}
	ast.Inspect(fc.ast, func(n ast.Node) bool {
		switch node := n.(type) {
		case *ast.GenDecl:
			if node.Tok == token.IMPORT {
				return true
			}
			for _, spec := range node.Specs {
				switch s := spec.(type) {
				case *ast.ValueSpec:
					for _, name := range s.Names {
						checkName(node, name.Name)
					}
				case *ast.TypeSpec:
					checkName(node, s.Name.Name)
				}
			}
		case *ast.FuncDecl:
			if node.Recv == nil {
				checkName(node, node.Name.Name)
			}
			// params/results/typeparams are checked via *ast.FuncType below to avoid receiver
		case *ast.FuncType:
			checkFields(node.TypeParams)
			checkFields(node.Params)
			checkFields(node.Results)
		case *ast.AssignStmt:
			for _, lhs := range node.Lhs {
				id, ok := lhs.(*ast.Ident)
				if !ok {
					continue
				}
				if builtinConsts[id.Name] {
					var msg string
					if node.Tok == token.DEFINE {
						msg = fmt.Sprintf("assignment creates a shadow of built-in identifier %s", id.Name)
					} else {
						msg = fmt.Sprintf("assignment modifies built-in identifier %s", id.Name)
					}
					out = append(out, fc.nodeFailure(node, msg, "logic", 1, ""))
				} else if builtinKind(id.Name) != "" {
					out = append(out, fc.nodeFailure(node, fmt.Sprintf("redefinition of the built-in %s %s", builtinKind(id.Name), id.Name), "logic", 1, ""))
				}
			}
		}
		return true
	})
	return out
}

var timeSuffixes = []string{
	"Seconds", "Second", "Minutes", "Minute", "Millis", "Milli",
	"Msecs", "Msec", "Usecs", "Usec", "Hours", "Hour", "Mins", "Min",
	"Secs", "Sec", "MS", "Ms",
}

func (fc *fileContext) isDurationType(t types.Type) bool {
	if t == nil {
		return false
	}
	named, ok := t.(*types.Named)
	if !ok {
		return false
	}
	obj := named.Obj()
	return obj != nil && obj.Name() == "Duration" && obj.Pkg() != nil && obj.Pkg().Path() == "time"
}

func ruleTimeNaming(fc *fileContext, _ interface{}) []failure {
	var out []failure
	ast.Inspect(fc.ast, func(n ast.Node) bool {
		spec, ok := n.(*ast.ValueSpec)
		if !ok {
			return true
		}
		for _, name := range spec.Names {
			obj := fc.objectOf(name)
			var t types.Type
			if obj != nil {
				t = obj.Type()
			}
			if t == nil {
				continue
			}
			if !fc.isDurationType(t) {
				continue
			}
			for _, suffix := range timeSuffixes {
				if strings.HasSuffix(name.Name, suffix) {
					out = append(out, fc.nodeFailure(spec, fmt.Sprintf("var %s is of type time.Duration; don't use unit-specific suffix %q", name.Name, suffix), "time", 0.9, ""))
					break
				}
			}
		}
		return true
	})
	return out
}

func isExportedType(t types.Type) bool {
	switch tt := t.(type) {
	case *types.Named:
		return tt.Obj().Exported()
	case *types.Pointer:
		return isExportedType(tt.Elem())
	case *types.Slice:
		return isExportedType(tt.Elem())
	case *types.Array:
		return isExportedType(tt.Elem())
	case *types.Map:
		return isExportedType(tt.Key()) && isExportedType(tt.Elem())
	case *types.Chan:
		return isExportedType(tt.Elem())
	case *types.Basic:
		return true
	default:
		// alias handling via reflection-like check on string representation in definedType check done by caller
		return true
	}
}

func ruleUnexportedReturn(fc *fileContext, _ interface{}) []failure {
	var out []failure
	for _, decl := range fc.ast.Decls {
		fd, ok := decl.(*ast.FuncDecl)
		if !ok || !isExportedName(fd.Name.Name) {
			continue
		}
		kind := "func"
		if fd.Recv != nil {
			kind = "method"
			rt := receiverTypeName(fd)
			if !isExportedName(rt) {
				continue
			}
		}
		if fd.Type.Results == nil {
			continue
		}
		done := false
		for _, field := range fd.Type.Results.List {
			if done {
				break
			}
			t := fc.typeOf(field.Type)
			if t == nil {
				continue
			}
			if !isExportedTypeExpanded(fc, t, field.Type) {
				msg := fmt.Sprintf("exported %s %s returns unexported type %s, which can be annoying to use", kind, fd.Name.Name, typeStringQualified(t))
				out = append(out, fc.nodeFailure(field.Type, msg, "unexported-type-in-api", 0.8, ""))
				done = true
			}
		}
	}
	return out
}

// isExportedTypeExpanded additionally handles type aliases (Go >= 1.22 *types.Alias)
// via checking the AST name if the type is a plain identifier referring to an alias.
func isExportedTypeExpanded(fc *fileContext, t types.Type, expr ast.Expr) bool {
	// If underlying check already says unexported, fine.
	if !isExportedType(t) {
		return false
	}
	// Detect alias: object for ident is *types.TypeName with IsAlias()
	if id, ok := expr.(*ast.Ident); ok {
		if obj := fc.objectOf(id); obj != nil {
			if tn, ok := obj.(*types.TypeName); ok && tn.IsAlias() {
				return tn.Exported()
			}
		}
	}
	return isExportedType(t)
}

func ruleUnreachableCode(fc *fileContext, _ interface{}) []failure {
	var out []failure
	ast.Inspect(fc.ast, func(n ast.Node) bool {
		block, ok := n.(*ast.BlockStmt)
		if !ok {
			return true
		}
		for i, stmt := range block.List {
			if i == len(block.List)-1 {
				break
			}
			if isTerminatingStmt(fc, stmt) {
				out = append(out, fc.nodeFailure(stmt, "unreachable code after this statement", "logic", 1, ""))
				break
			}
		}
		return true
	})
	return out
}

func isTerminatingStmt(fc *fileContext, stmt ast.Stmt) bool {
	switch s := stmt.(type) {
	case *ast.ReturnStmt:
		return true
	case *ast.BranchStmt:
		return s.Tok == token.BREAK || s.Tok == token.CONTINUE || s.Tok == token.GOTO
	case *ast.ExprStmt:
		call, ok := s.X.(*ast.CallExpr)
		if !ok {
			return false
		}
		if fc.isCallTo(call, "os", "Exit") {
			return true
		}
		for _, fn := range []string{"Fatal", "Fatalf", "Fatalln"} {
			if fc.isCallTo(call, "log", fn) {
				return true
			}
		}
		return false
	}
	return false
}

// unused-parameter

type unusedParamOptions struct {
	allowRegex    string
	allowRegexCmp *regexp.Regexp
}

func configureUnusedParameter(args []interface{}) (interface{}, error) {
	opts := &unusedParamOptions{}
	if len(args) == 0 {
		return opts, nil
	}
	m, ok := args[0].(map[string]interface{})
	if !ok {
		return opts, nil
	}
	if v, present := m["allowRegex"]; present {
		s, ok := v.(string)
		if !ok {
			return nil, fmt.Errorf("error configuring unused-parameter rule: allowRegex is not string but [%s]", typeName(v))
		}
		re, err := regexp.Compile(s)
		if err != nil {
			return nil, fmt.Errorf("error configuring unused-parameter rule: allowRegex is not valid regex [%s]: %s", s, err.Error())
		}
		opts.allowRegex = s
		opts.allowRegexCmp = re
	}
	return opts, nil
}

func ruleUnusedParameter(fc *fileContext, optsI interface{}) []failure {
	opts, _ := optsI.(*unusedParamOptions)
	if opts == nil {
		opts = &unusedParamOptions{}
	}
	var out []failure
	checkFunc := func(params *ast.FieldList, body *ast.BlockStmt) {
		if params == nil || body == nil {
			return
		}
		for _, field := range params.List {
			for _, name := range field.Names {
				if name.Name == "_" || name.Name == "" {
					continue
				}
				if opts.allowRegexCmp != nil && opts.allowRegexCmp.MatchString(name.Name) {
					continue
				}
				if isParamUsed(fc, name, body) {
					continue
				}
				var msg string
				if opts.allowRegex != "" {
					msg = fmt.Sprintf("parameter '%s' seems to be unused, consider removing or renaming it to match %s", name.Name, opts.allowRegex)
				} else {
					msg = fmt.Sprintf("parameter '%s' seems to be unused, consider removing or renaming it as _", name.Name)
				}
				out = append(out, fc.nodeFailure(name, msg, "bad practice", 1, ""))
			}
		}
	}
	for _, decl := range fc.ast.Decls {
		if fd, ok := decl.(*ast.FuncDecl); ok {
			checkFunc(fd.Type.Params, fd.Body)
		}
	}
	// Func literals anywhere (but avoid double-checking nested? original checks them)
	ast.Inspect(fc.ast, func(n ast.Node) bool {
		if lit, ok := n.(*ast.FuncLit); ok {
			checkFunc(lit.Type.Params, lit.Body)
		}
		return true
	})
	return out
}

func isParamUsed(fc *fileContext, paramName *ast.Ident, body ast.Node) bool {
	if fc.types == nil {
		// lexical fallback
		used := false
		ast.Inspect(body, func(n ast.Node) bool {
			if id, ok := n.(*ast.Ident); ok && id.Name == paramName.Name && id != paramName {
				used = true
				return false
			}
			return true
		})
		return used
	}
	obj := fc.types.Defs[paramName]
	if obj == nil {
		// might be in Uses? no. Fallback lexical scan but distinguish definitions not easily
		used := false
		ast.Inspect(body, func(n ast.Node) bool {
			if id, ok := n.(*ast.Ident); ok && id != paramName && fc.types.Uses[id] != nil && fc.types.Uses[id].Name() == paramName.Name {
				// could be shadow; accept
				used = true
				return false
			}
			return true
		})
		return used
	}
	for _, u := range fc.types.Uses {
		if u == obj {
			return true
		}
	}
	return false
}

// var-declaration

func defaultType(t types.Type) types.Type {
	if t == nil {
		return nil
	}
	if basic, ok := t.Underlying().(*types.Basic); ok && (basic.Info()&types.IsUntyped) != 0 {
		// only if t itself is the basic untyped
		if b, ok := t.(*types.Basic); ok {
			switch b.Kind() {
			case types.UntypedBool:
				return types.Typ[types.Bool]
			case types.UntypedInt:
				return types.Typ[types.Int]
			case types.UntypedRune:
				return types.Typ[types.Rune]
			case types.UntypedFloat:
				return types.Typ[types.Float64]
			case types.UntypedComplex:
				return types.Typ[types.Complex128]
			case types.UntypedString:
				return types.Typ[types.String]
			case types.UntypedNil:
				return nil
			}
		}
	}
	return t
}

func isZeroValueExpr(expr ast.Expr) bool {
	switch v := expr.(type) {
	case *ast.Ident:
		return v.Name == "nil"
	case *ast.BasicLit:
		switch v.Kind {
		case token.INT, token.FLOAT, token.IMAG:
			return v.Value == "0" || v.Value == "0.0"
		case token.STRING:
			return v.Value == "\"\"" || v.Value == "``"
		}
	}
	return false
}

func ruleVarDeclaration(fc *fileContext, _ interface{}) []failure {
	var out []failure
	ast.Inspect(fc.ast, func(n ast.Node) bool {
		gd, ok := n.(*ast.GenDecl)
		if !ok || gd.Tok != token.VAR {
			return true
		}
		for _, specI := range gd.Specs {
			spec, ok := specI.(*ast.ValueSpec)
			if !ok || spec.Type == nil || len(spec.Values) != 1 || len(spec.Names) != 1 {
				continue
			}
			name := spec.Names[0].Name
			value := spec.Values[0]
			if isZeroValueExpr(value) {
				out = append(out, fc.nodeFailure(value, fmt.Sprintf("should drop = %s from declaration of var %s; it is the zero value", fc.nodeString(value), name), "zero-value", 0.9, ""))
				continue
			}
			lhsType := fc.typeOf(spec.Type)
			rhsType := defaultType(fc.typeOf(value))
			if lhsType == nil || rhsType == nil {
				continue
			}
			if types.Identical(lhsType, rhsType) {
				out = append(out, fc.nodeFailure(spec.Type, fmt.Sprintf("should omit type %s from declaration of var %s; it will be inferred from the right-hand side", fc.nodeString(spec.Type), name), "type-inference", 0.8, ""))
			}
		}
		return true
	})
	return out
}

