// checkDocForm validates a doc comment for an exported declaration.
// kind is "function", "method", "type", "var", "const" etc.
// name is the (simple) declared name used in the expected prefix.
// displayName is used in the failure message's object (e.g. T.M for methods).
func (fc *fileContext) checkDocForm(doc *ast.CommentGroup, kind, name, displayName string, failures *[]failure) {
	if doc == nil {
		return
	}
	text := doc.Text()
	// For types, an optional leading article may precede the name.
	if kind == "type" {
		textForCheck := text
		if strings.HasPrefix(textForCheck, "A ") {
			textForCheck = textForCheck[2:]
		} else if strings.HasPrefix(textForCheck, "An ") {
			textForCheck = textForCheck[3:]
		} else if strings.HasPrefix(textForCheck, "The ") {
			textForCheck = textForCheck[4:]
		}
		if strings.HasPrefix(textForCheck, name+" ") {
			return
		}
		// Check for wrong-casing of name in the article-stripped text.
		if wrongName, ok := wrongCaseName(textForCheck, name); ok {
			msg := fmt.Sprintf("comment on exported %s %s should be of the form \"%s ...\" (with optional leading article) by using its correct casing, not \"%s ...\"", kind, displayName, name, wrongName)
			// special "exported status" wording when there's no article and name is just lowercased
			if textForCheck == text && isFirstLowered(wrongName, name) {
				msg = fmt.Sprintf("comment on exported %s %s should be of the form \"%s ...\" (with optional leading article) to match its exported status, not \"%s ...\"", kind, displayName, name, wrongName)
			}
			*failures = append(*failures, fc.nodeFailure(doc, msg, "comments", 1, ""))
			return
		}
		msg := fmt.Sprintf("comment on exported %s %s should be of the form \"%s ...\" (with optional leading article)", kind, displayName, name)
		*failures = append(*failures, fc.nodeFailure(doc, msg, "comments", 0.8, ""))
		return
	}
	if strings.HasPrefix(text, name+" ") {
		return
	}
	if wrongName, ok := wrongCaseName(text, name); ok {
		var msg string
		if isFirstLowered(wrongName, name) {
			msg = fmt.Sprintf("comment on exported %s %s should be of the form \"%s ...\" to match its exported status, not \"%s ...\"", kind, displayName, name, wrongName)
		} else {
			msg = fmt.Sprintf("comment on exported %s %s should be of the form \"%s ...\" by using its correct casing, not \"%s ...\"", kind, displayName, name, wrongName)
		}
		*failures = append(*failures, fc.nodeFailure(doc, msg, "comments", 1, ""))
		return
	}
	msg := fmt.Sprintf("comment on exported %s %s should be of the form \"%s ...\"", kind, displayName, name)
	*failures = append(*failures, fc.nodeFailure(doc, msg, "comments", 0.8, ""))
}

func wrongCaseName(text, name string) (string, bool) {
	if len(text) <= len(name) {
		return "", false
	}
	candidate := text[:len(name)]
	if text[len(name)] != ' ' {
		return "", false
	}
	if candidate == name {
		return "", false
	}
	if strings.EqualFold(candidate, name) {
		return candidate, true
	}
	return "", false
}

func isFirstLowered(wrong, name string) bool {
	if len(name) == 0 || len(wrong) == 0 {
		return false
	}
	r, size := utf8.DecodeRuneInString(name)
	lowered := string(unicode.ToLower(r)) + name[size:]
	return wrong == lowered
}

func splitCamelWords(s string) []string {
	// Split a CamelCase identifier into words: lower->upper transitions,
	// acronym boundaries (HTTPServer -> HTTP, Server), underscores/digits glued.
	var words []string
	letters := []rune(s)
	start := 0
	for i := 1; i < len(letters); i++ {
		prev, curr := letters[i-1], letters[i]
		if curr == '_' {
			// underscore ends current word before it? treat as boundary at i (word included excludes _)
			// Golint stutter considers Foo_bar first word Foo.
			words = append(words, string(letters[start:i]))
			start = i // next word starts with _ causing remainder "_bar" handling by pos
			// Now skip? Keep approach: next word starts at i but we will compute positions by cumulative lengths in caller differently.
			// Instead we handled by caller scanning.
			continue
		}
		if unicode.IsUpper(curr) && (unicode.IsLower(prev) || unicode.IsDigit(prev) ||
			(unicode.IsUpper(prev) && i+1 < len(letters) && unicode.IsLower(letters[i+1]))) {
			words = append(words, string(letters[start:i]))
			start = i
		}
	}
	words = append(words, string(letters[start:]))
	return words
}

// stutters returns suggested remainder if exported name stutters with package name.
func stutters(pkgName, name string) (string, bool) {
	if pkgName == "" || name == "" {
		return "", false
	}
	// Compute word boundaries in name
	runes := []rune(name)
	var bounds []int // rune indexes at ends of words
	for i := 1; i < len(runes); i++ {
		prev, curr := runes[i-1], runes[i]
		boundary := false
		if curr == '_' {
			boundary = true
		} else if unicode.IsUpper(curr) && (unicode.IsLower(prev) || unicode.IsDigit(prev) || (unicode.IsUpper(prev) && i+1 < len(runes) && unicode.IsLower(runes[i+1]))) {
			boundary = true
		}
		if boundary {
			bounds = append(bounds, i)
		}
	}
	bounds = append(bounds, len(runes))
	for _, b := range bounds {
		if b >= len(runes) {
			break
		}
		prefix := string(runes[:b])
		if strings.EqualFold(prefix, pkgName) {
			remainder := string(runes[b:])
			if remainder == "" {
				return "", false
			}
			return remainder, true
		}
	}
	return "", false
}

func ruleExported(fc *fileContext, optsI interface{}) []failure {
	opts, _ := optsI.(*exportedOptions)
	if opts == nil {
		opts = &exportedOptions{}
	}
	if fc.isTest {
		return nil
	}
	pkgName := ""
	if fc.ast.Name != nil {
		pkgName = fc.ast.Name.Name
	}
	if pkgName == "main" {
		return nil
	}
	var out []failure
	stutterPkg := strings.TrimSuffix(pkgName, "_test")

	for _, decl := range fc.ast.Decls {
		switch d := decl.(type) {
		case *ast.FuncDecl:
			if !isExportedName(d.Name.Name) {
				continue
			}
			if d.Recv != nil {
				rtName := receiverTypeName(d)
				if !isExportedName(rtName) && !opts.checkPrivateReceivers {
					continue
				}
				display := rtName + "." + d.Name.Name
				if d.Doc == nil {
					out = append(out, fc.nodeFailure(d, fmt.Sprintf("exported method %s should have comment or be unexported", display), "comments", 1, ""))
				} else {
					fc.checkDocForm(d.Doc, "method", d.Name.Name, display, &out)
				}
			} else {
				if d.Doc == nil {
					out = append(out, fc.nodeFailure(d, fmt.Sprintf("exported function %s should have comment or be unexported", d.Name.Name), "comments", 1, ""))
				} else {
					fc.checkDocForm(d.Doc, "function", d.Name.Name, d.Name.Name, &out)
				}
				if !opts.disableStutteringCheck {
					if remainder, ok := stutters(stutterPkg, d.Name.Name); ok {
						msg := fmt.Sprintf("func name will be used as %s.%s by other packages, and that stutters; consider calling this %s", pkgName, d.Name.Name, remainder)
						out = append(out, fc.nodeFailure(d.Name, msg, "naming", 0.8, ""))
					}
				}
			}
		case *ast.GenDecl:
			switch d.Tok {
			case token.TYPE:
				for _, specI := range d.Specs {
					spec, ok := specI.(*ast.TypeSpec)
					if !ok || !isExportedName(spec.Name.Name) {
						continue
					}
					if !opts.disableStutteringCheck {
						if remainder, ok := stutters(stutterPkg, spec.Name.Name); ok {
							msg := fmt.Sprintf("type name will be used as %s.%s by other packages, and that stutters; consider calling this %s", pkgName, spec.Name.Name, remainder)
							out = append(out, fc.nodeFailure(spec.Name, msg, "naming", 0.8, ""))
						}
					}
					doc := spec.Doc
					if doc == nil {
						doc = d.Doc
					}
					if doc == nil {
						out = append(out, fc.nodeFailure(spec, fmt.Sprintf("exported type %s should have comment or be unexported", spec.Name.Name), "comments", 1, ""))
					} else {
						// Only validate form if the doc is not shared incorrectly? Reference validates group doc per type.
						fc.checkDocForm(doc, "type", spec.Name.Name, spec.Name.Name, &out)
					}
				}
			case token.VAR, token.CONST:
				kind := "var"
				if d.Tok == token.CONST {
					kind = "const"
				}
				grouped := d.Lparen.IsValid()
				// A comment on the whole block suffices for var/const blocks.
				blockDoc := grouped && d.Doc != nil
			specLoop:
				for _, specI := range d.Specs {
					spec, ok := specI.(*ast.ValueSpec)
					if !ok {
						continue
					}
					// Multi-name: if an exported name appears at index > 0, report it (first such) and skip doc check for this spec.
					ownReported := false
					if len(spec.Names) > 1 {
						for _, name := range spec.Names[1:] {
							if isExportedName(name.Name) {
								if !blockDoc {
									out = append(out, fc.nodeFailure(spec, fmt.Sprintf("exported %s %s should have its own declaration", kind, name.Name), "comments", 1, ""))
								}
								ownReported = true
								break
							}
						}
						if ownReported {
							continue
						}
					}
					// First (only possibly exported at 0) exported name
					var first *ast.Ident
					for _, name := range spec.Names {
						if isExportedName(name.Name) {
							first = name
							break
						}
					}
					if first == nil {
						continue
					}
					if blockDoc {
						continue
					}
					doc := spec.Doc
					if doc == nil && len(d.Specs) == 1 {
						doc = d.Doc
					}
					if doc == nil {
						var msg string
						if kind == "const" && grouped {
							msg = fmt.Sprintf("exported const %s should have comment (or a comment on this block) or be unexported", first.Name)
						} else {
							msg = fmt.Sprintf("exported %s %s should have comment or be unexported", kind, first.Name)
						}
						out = append(out, fc.nodeFailure(spec, msg, "comments", 1, ""))
						if grouped {
							break specLoop
						}
						continue
					}
					fc.checkDocForm(doc, kind, first.Name, first.Name, &out)
				}
			}
		}
	}
	return out
}
