{"command":"cat > /workspace/varnaming.go <<'EOF'
package main

import (
	"bytes"
	"encoding/json"
	"fmt"
	"go/ast"
	"go/token"
	"os/exec"
	"strings"
	"sync"
	"unicode"
	"unicode/utf8"
)

type varNamingOptions struct {
	allowList                []string
	blockList                []string
	upperCaseConst           bool
	skipPackageNameChecks    bool
	skipInitialismNameChecks bool
	extraBadPackageNames     []string
	initialisms              map[string]bool
	stdPackageNames          map[string]bool
}

var defaultInitialisms = []string{
	"ACL", "API", "ASCII", "CPU", "CSS", "DNS", "EOF", "GUID", "HTML", "HTTP", "HTTPS",
	"ID", "IP", "JSON", "LHS", "QPS", "RAM", "RHS", "RPC", "SLA", "SMTP", "SQL", "SSH",
	"TCP", "TLS", "TTL", "UDP", "UI", "UID", "UUID", "URI", "URL", "VM", "XML", "XMPP", "XSRF", "XSS",
}

var badPackageNames = map[string]bool{
	"api": true, "common": true, "misc": true, "shared": true, "types": true, "util": true, "utils": true,
}

var (
	stdPkgsOnce  sync.Once
	stdPkgsCache map[string]bool
	stdPkgsErr   error
)

func loadStdPackageNames() (map[string]bool, error) {
	stdPkgsOnce.Do(func() {
		args := []string{"list", "-e", "-json=Name,ImportPath,Error,Dir,GoFiles,IgnoredGoFiles,IgnoredOtherFiles,CFiles,CgoFiles,CXXFiles,MFiles,HFiles,FFiles,SFiles,SwigFiles,SwigCXXFiles,SysoFiles,CompiledGoFiles,Export", "-compiled=true", "-test=false", "-export=false", "-deps=false", "-find=true", "-pgo=off", "--", "std"}
		cmd := exec.Command("go", args...)
		var stdout, stderr bytes.Buffer
		cmd.Stdout = &stdout
		cmd.Stderr = &stderr
		err := cmd.Run()
		if err != nil {
			stdPkgsErr = fmt.Errorf("load std packages: err: %s: stderr: %s", err.Error(), stderr.String())
			return
		}
		names := map[string]bool{}
		dec := json.NewDecoder(&stdout)
		for dec.More() {
			var pkg struct {
				Name string
			}
			if err := dec.Decode(&pkg); err != nil {
				break
			}
			if pkg.Name != "" {
				names[pkg.Name] = true
			}
		}
		stdPkgsCache = names
	})
	return stdPkgsCache, stdPkgsErr
}

func configureVarNaming(args []interface{}) (interface{}, error) {
	opts := &varNamingOptions{initialisms: map[string]bool{}}
	for _, init := range defaultInitialisms {
		opts.initialisms[init] = true
	}
	// helper to parse a slice-of-strings argument
	parseList := func(arg interface{}) ([]string, error) {
		list, ok := arg.([]interface{})
		if !ok {
			return nil, fmt.Errorf("invalid argument to the var-naming rule. Expecting a allowlist of type slice with initialisms, got %s", typeName(arg))
		}
		var out []string
		for _, e := range list {
			s, ok := e.(string)
			if !ok {
				return nil, fmt.Errorf("invalid %v values of the var-naming rule. Expecting slice of strings but got element of type []interface {}", e)
			}
			out = append(out, s)
		}
		return out, nil
	}
	if len(args) >= 1 {
		list, err := parseList(args[0])
		if err != nil {
			return nil, err
		}
		opts.allowList = list
	}
	if len(args) >= 2 {
		list, err := parseList(args[1])
		if err != nil {
			return nil, err
		}
		opts.blockList = list
	}
	if len(args) >= 3 {
		arg := args[2]
		slice, ok := arg.([]interface{})
		if !ok {
			return nil, fmt.Errorf("invalid third argument to the var-naming rule. Expecting a options of type slice, got %s", typeName(arg))
		}
		if len(slice) != 1 {
			return nil, fmt.Errorf("invalid third argument to the var-naming rule. Expecting a options of type slice, of len==1, but %d", len(slice))
		}
		m, ok := slice[0].(map[string]interface{})
		if !ok {
			return nil, fmt.Errorf("invalid third argument to the var-naming rule. Expecting a options of type slice, of len==1, with map, but %s", typeName(slice[0]))
		}
		for k, v := range m {
			switch k {
			case "upperCaseConst":
				if b, ok := v.(bool); ok {
					opts.upperCaseConst = b
				}
			case "skipPackageNameChecks":
				if b, ok := v.(bool); ok {
					opts.skipPackageNameChecks = b
				}
			case "skipInitialismNameChecks":
				if b, ok := v.(bool); ok {
					opts.skipInitialismNameChecks = b
				}
			case "extraBadPackageNames":
				list, ok := v.([]interface{})
				if !ok {
					return nil, fmt.Errorf("invalid third argument to the var-naming rule. Expecting extraBadPackageNames of type slice of strings, but %s", typeName(v))
				}
				for i, e := range list {
					s, ok := e.(string)
					if !ok {
						return nil, fmt.Errorf("invalid third argument to the var-naming rule: expected element %d of extraBadPackageNames to be a string, but got %v(%s)", i, e, typeName(e))
					}
					opts.extraBadPackageNames = append(opts.extraBadPackageNames, s)
				}
			}
		}
	}
	for _, a := range opts.allowList {
		delete(opts.initialisms, a)
	}
	for _, b := range opts.blockList {
		opts.initialisms[b] = true
	}
	stdNames, err := loadStdPackageNames()
	if err != nil {
		return nil, err
	}
	opts.stdPackageNames = stdNames
	return opts, nil
}

func (opts *varNamingOptions) applyInitialisms(name string) string {
	if opts.skipInitialismNameChecks {
		return name
	}
	words := splitCamelWordSpans(name)
	if len(words) == 0 {
		return name
	}
	var b strings.Builder
	for i, span := range words {
		word := name[span[0]:span[1]]
		upper := strings.ToUpper(word)
		if opts.initialisms[upper] {
			// First word lower-cased form of an initialism in an unexported name stays lower.
			if i == 0 && len(name) > 0 {
				first, _ := utf8.DecodeRuneInString(name)
				if unicode.IsLower(first) && word == strings.ToLower(word) {
					b.WriteString(word)
					continue
				}
			}
			b.WriteString(upper)
		} else {
			b.WriteString(word)
		}
	}
	return b.String()
}

func splitCamelWordSpans(s string) [][2]int {
	if s == "" {
		return nil
	}
	runes := []rune(s)
	// positions in terms of byte offsets computed from rune indices
	byteIdx := make([]int, len(runes)+1)
	pos := 0
	for i, r := range runes {
		byteIdx[i] = pos
		pos += utf8.RuneLen(r)
	}
	byteIdx[len(runes)] = pos
	var spans [][2]int
	start := 0
	for i := 1; i < len(runes); i++ {
		prev, curr := runes[i-1], runes[i]
		if unicode.IsUpper(curr) && (unicode.IsLower(prev) || unicode.IsDigit(prev) || (unicode.IsUpper(prev) && i+1 < len(runes) && unicode.IsLower(runes[i+1]))) {
			spans = append(spans, [2]int{byteIdx[start], byteIdx[i]})
			start = i
		}
	}
	spans = append(spans, [2]int{byteIdx[start], byteIdx[len(runes)]})
	return spans
}

func upperFirst(s string) string {
	if s == "" {
		return s
	}
	r, size := utf8.DecodeRuneInString(s)
	return string(unicode.ToUpper(r)) + s[size:]
}

func (opts *varNamingOptions) snakeToCamel(name string) string {
	prefix := ""
	rest := name
	if strings.HasPrefix(rest, "_") && rest != "_" {
		prefix = "_"
		rest = rest[1:]
	}
	segments := strings.Split(rest, "_")
	var b strings.Builder
	b.WriteString(prefix)
	for i, seg := range segments {
		if seg == "" {
			continue
		}
		if i == 0 {
			b.WriteString(opts.applyInitialisms(seg))
		} else {
			b.WriteString(opts.applyInitialisms(upperFirst(seg)))
		}
	}
	return b.String()
}

func isUpperSnake(name string) bool {
	if !strings.Contains(name, "_") {
		return false
	}
	hasUpper := false
	for _, r := range name {
		if unicode.IsUpper(r) {
			hasUpper = true
		} else if unicode.IsLower(r) {
			return false
		}
	}
	return hasUpper && name == strings.ToUpper(name)
}

func (opts *varNamingOptions) checkName(fc *fileContext, node ast.Node, name, kind string, out *[]failure) {
	if name == "_" || name == "" {
		return
	}
	if kind == "const" && opts.upperCaseConst && isUpperSnake(name) {
		return
	}
	// Allow underscores in test function names in test files
	if fc.isTest && kind == "func" && (strings.HasPrefix(name, "Test") || strings.HasPrefix(name, "Benchmark") || strings.HasPrefix(name, "Example") || strings.HasPrefix(name, "Fuzz")) {
		return
	}
	if strings.Contains(name, "_") {
		if isUpperSnake(name) && len([]rune(name)) > 5 {
			*out = append(*out, fc.nodeFailure(node, "don't use ALL_CAPS in Go names; use CamelCase", "naming", 0.8, ""))
			return
		}
		suggested := opts.snakeToCamel(name)
		if suggested == name {
			return
		}
		if len([]rune(name)) <= 2 {
			*out = append(*out, fc.nodeFailure(node, fmt.Sprintf("%s %s should be %s", kind, name, suggested), "naming", 0.8, ""))
			return
		}
		*out = append(*out, fc.nodeFailure(node, fmt.Sprintf("don't use underscores in Go names; %s %s should be %s", kind, name, suggested), "naming", 0.9, ""))
		return
	}
	if suggested := opts.applyInitialisms(name); suggested != name {
		*out = append(*out, fc.nodeFailure(node, fmt.Sprintf("%s %s should be %s", kind, name, suggested), "naming", 0.8, ""))
	}
}

func ruleVarNaming(fc *fileContext, optsI interface{}) []failure {
	opts, _ := optsI.(*varNamingOptions)
	if opts == nil {
		opts = &varNamingOptions{initialisms: map[string]bool{}}
		for _, i := range defaultInitialisms {
			opts.initialisms[i] = true
		}
	}
	var out []failure
	// package name checks
	if !opts.skipPackageNameChecks && fc.ast.Name != nil {
		pkgName := fc.ast.Name.Name
		node := fc.ast.Name
		if strings.Contains(pkgName, "_") && !strings.HasSuffix(pkgName, "_test") {
			out = append(out, fc.nodeFailure(node, "don't use an underscore in package name", "naming", 1, ""))
		} else {
			lower := strings.ToLower(pkgName)
			extra := false
			for _, x := range opts.extraBadPackageNames {
				if strings.EqualFold(x, pkgName) {
					extra = true
					break
				}
			}
			switch {
			case extra:
				out = append(out, fc.nodeFailure(node, "avoid bad package names", "naming", 1, ""))
			case lower == "pkg":
				out = append(out, fc.nodeFailure(node, "should not have a root level package called pkg", "naming", 1, ""))
			case badPackageNames[lower]:
				out = append(out, fc.nodeFailure(node, "avoid meaningless package names", "naming", 1, ""))
			default:
				if opts.stdPackageNames[lower] {
					out = append(out, fc.nodeFailure(node, "avoid package names that conflict with Go standard library package names", "naming", 1, ""))
				}
				if pkgName != lower {
					out = append(out, fc.nodeFailure(node, fmt.Sprintf("don't use MixedCaps in package names; %s should be %s", pkgName, lower), "naming", 1, ""))
				}
			}
		}
	}

	check := func(node ast.Node, name, kind string) {
		opts.checkName(fc, node, name, kind, &out)
	}

	// Walk with context to know interface methods/struct fields
	var visit func(node ast.Node, inInterface bool)
	// We use ast.Inspect with a stack to detect parents
	type frame struct{ node ast.Node }
	var stack []ast.Node
	ast.Inspect(fc.ast, func(n ast.Node) bool {
		if n == nil {
			stack = stack[:len(stack)-1]
			return true
		}
		switch node := n.(type) {
		case *ast.FuncDecl:
			if node.Recv != nil {
				check(node.Name, node.Name.Name, "method")
				for _, f := range fieldListNames(node.Type.Params) {
					check(f.ident, f.name, "method parameter")
				}
				for _, f := range fieldListNames(node.Type.Results) {
					check(f.ident, f.name, "method result")
				}
			} else {
				check(node.Name, node.Name.Name, "func")
				for _, f := range fieldListNames(node.Type.Params) {
					check(f.ident, f.name, "func parameter")
				}
				for _, f := range fieldListNames(node.Type.Results) {
					check(f.ident, f.name, "func result")
				}
			}
		case *ast.InterfaceType:
			if node.Methods != nil {
				for _, field := range node.Methods.List {
					if ft, ok := field.Type.(*ast.FuncType); ok {
						for _, f := range fieldListNames(ft.Params) {
							check(f.ident, f.name, "interface method parameter")
						}
						for _, f := range fieldListNames(ft.Results) {
							check(f.ident, f.name, "interface method result")
						}
					}
				}
			}
		case *ast.StructType:
			if node.Fields != nil {
				for _, field := range node.Fields.List {
					for _, name := range field.Names {
						check(name, name.Name, "struct field")
					}
				}
			}
		case *ast.GenDecl:
			for _, spec := range node.Specs {
				switch s := spec.(type) {
				case *ast.ValueSpec:
					kind := "var"
					if node.Tok == token.CONST {
						kind = "const"
					}
					if node.Tok == token.VAR || node.Tok == token.CONST {
						for _, name := range s.Names {
							check(name, name.Name, kind)
						}
					}
				case *ast.TypeSpec:
					check(s.Name, s.Name.Name, "type")
				}
			}
		case *ast.AssignStmt:
			if node.Tok == token.DEFINE {
				for _, lhs := range node.Lhs {
					if id, ok := lhs.(*ast.Ident); ok {
						check(id, id.Name, "var")
					}
				}
			}
		case *ast.RangeStmt:
			if node.Tok == token.DEFINE {
				if id, ok := node.Key.(*ast.Ident); ok {
					check(id, id.Name, "range var")
				}
				if id, ok := node.Value.(*ast.Ident); ok {
					check(id, id.Name, "range var")
				}
			}
		}
		_ = visit
		stack = append(stack, n)
		return true
	})
	return out
}

type namedIdent struct {
	name  string
	ident *ast.Ident
}

func fieldListNames(fl *ast.FieldList) []namedIdent {
	if fl == nil {
		return nil
	}
	var out []namedIdent
	for _, f := range fl.List {
		for _, n := range f.Names {
			out = append(out, namedIdent{n.Name, n})
		}
	}
	return out
}
