// ---- add-constant ----

type addConstantOptions struct {
	maxLitCount int
	allowInts   map[string]bool
	allowFloats map[string]bool
	allowStrs   map[string]bool
	ignoreFuncs []*regexp.Regexp
}

func configureAddConstant(args []interface{}) (interface{}, error) {
	opts := &addConstantOptions{maxLitCount: 2, allowInts: map[string]bool{}, allowFloats: map[string]bool{}, allowStrs: map[string]bool{}}
	if len(args) == 0 {
		return opts, nil
	}
	m, ok := args[0].(map[string]interface{})
	if !ok {
		return nil, fmt.Errorf("invalid argument to the add-constant rule, expecting a k,v map. Got %s", typeName(args[0]))
	}
	stringVal := func(v interface{}) (string, error) {
		s, ok := v.(string)
		if !ok {
			return "", fmt.Errorf("invalid argument to the add-constant rule, string expected. Got '%v' (%s)", v, typeName(v))
		}
		return s, nil
	}
	for key, val := range m {
		switch key {
		case "maxLitCount":
			s, ok := val.(string)
			if !ok {
				return nil, fmt.Errorf("invalid argument to the add-constant rule, expecting string representation of an integer. Got '%v' (%s)", val, typeName(val))
			}
			n, err := strconv.Atoi(s)
			if err != nil {
				return nil, fmt.Errorf("invalid argument to the add-constant rule, expecting string representation of an integer. Got '%s'", s)
			}
			opts.maxLitCount = n
		case "allowInts":
			s, err := stringVal(val)
			if err != nil {
				return nil, err
			}
			for _, p := range strings.Split(s, ",") {
				opts.allowInts[p] = true
			}
		case "allowFloats":
			s, err := stringVal(val)
			if err != nil {
				return nil, err
			}
			for _, p := range strings.Split(s, ",") {
				opts.allowFloats[p] = true
			}
		case "allowStrs":
			s, err := stringVal(val)
			if err != nil {
				return nil, err
			}
			// The list is comma-separated but string literals themselves are quoted;
			// splitting by comma is what the reference effectively does for simple cases,
			// but a single quoted literal containing a comma must survive. We treat
			// the whole value as a list of quoted literals if it looks like one.
			for _, p := range splitAllowStrs(s) {
				opts.allowStrs[p] = true
			}
		case "ignoreFuncs":
			s, err := stringVal(val)
			if err != nil {
				return nil, err
			}
			for _, p := range strings.Split(s, ",") {
				p = strings.TrimSpace(p)
				re, err := regexp.Compile(p)
				if err != nil {
					return nil, fmt.Errorf("invalid argument to the ignoreFuncs parameter of add-constant rule: regexp %q does not compile: %s", p, err.Error())
				}
				opts.ignoreFuncs = append(opts.ignoreFuncs, re)
			}
		default:
			// Unknown keys are silently ignored by the reference.
			// However, keys it knows as string-typed would still be type-checked there;
			// we ignore unknown entirely.
		}
	}
	return opts, nil
}

func splitAllowStrs(s string) []string {
	// Split on commas that are outside double quotes.
	var out []string
	var cur strings.Builder
	inQuote := false
	escaped := false
	for _, r := range s {
		if escaped {
			cur.WriteRune(r)
			escaped = false
			continue
		}
		if r == '\\' && inQuote {
			cur.WriteRune(r)
			escaped = true
			continue
		}
		if r == '"' {
			inQuote = !inQuote
			cur.WriteRune(r)
			continue
		}
		if r == ',' && !inQuote {
			out = append(out, cur.String())
			cur.Reset()
			continue
		}
		cur.WriteRune(r)
	}
	out = append(out, cur.String())
	return out
}

func ruleAddConstant(fc *fileContext, optsI interface{}) []failure {
	opts, _ := optsI.(*addConstantOptions)
	if opts == nil {
		opts = &addConstantOptions{maxLitCount: 2, allowInts: map[string]bool{}, allowFloats: map[string]bool{}, allowStrs: map[string]bool{}}
	}
	var out []failure
	strCounts := map[string]int{}
	type frame struct {
		inValueSpec bool
		ignored     bool
	}
	// Walk manually with context: skip ValueSpec subtrees, track ignored calls.
	var walk func(node ast.Node, inValueSpec bool, ignored bool)
	walk = func(node ast.Node, inValueSpec bool, ignored bool) {
		if node == nil {
			return
		}
		switch n := node.(type) {
		case *ast.ValueSpec:
			inValueSpec = true
		case *ast.CallExpr:
			funStr := fc.nodeString(n.Fun)
			for _, re := range opts.ignoreFuncs {
				if re.MatchString(funStr) {
					ignored = true
					break
				}
			}
		case *ast.BasicLit:
			if !inValueSpec && !ignored {
				switch n.Kind {
				case token.INT:
					if !opts.allowInts[n.Value] {
						out = append(out, fc.nodeFailure(n, fmt.Sprintf("avoid magic numbers like '%s', create a named constant for it", n.Value), "style", 1, ""))
					}
				case token.FLOAT:
					if !opts.allowFloats[n.Value] {
						out = append(out, fc.nodeFailure(n, fmt.Sprintf("avoid magic numbers like '%s', create a named constant for it", n.Value), "style", 1, ""))
					}
				case token.STRING:
					if !opts.allowStrs[n.Value] {
						strCounts[n.Value]++
						limit := opts.maxLitCount + 1
						if limit < 1 {
							limit = 1
						}
						if strCounts[n.Value] == limit {
							out = append(out, fc.nodeFailure(n, fmt.Sprintf("string literal %s appears, at least, %d times, create a named constant for it", n.Value, limit), "style", 1, ""))
						}
					}
				}
			}
			return
		}
		for _, child := range childNodes(node) {
			walk(child, inValueSpec, ignored)
		}
	}
	walk(fc.ast, false, false)
	return out
}

// childNodes returns immediate AST children in walk order (approximating ast.Inspect).
func childNodes(node ast.Node) []ast.Node {
	var children []ast.Node
	ast.Inspect(node, func(n ast.Node) bool {
		if n == nil {
			return true
		}
		if n == node {
			return true
		}
		children = append(children, n)
		return false
	})
	return children
}

func ruleBareReturn(fc *fileContext, _ interface{}) []failure {
	var out []failure
	check := func(results *ast.FieldList, body *ast.BlockStmt) {
		if results == nil || len(results.List) == 0 {
			return
		}
		// at least one named result
		named := false
		for _, f := range results.List {
			if len(f.Names) > 0 {
				named = true
			}
		}
		if !named || body == nil {
			return
		}
		ast.Inspect(body, func(n ast.Node) bool {
			switch node := n.(type) {
			case *ast.FuncLit:
				return false
			case *ast.ReturnStmt:
				if len(node.Results) == 0 {
					out = append(out, fc.nodeFailure(node, "avoid using bare returns, please add return expressions", "", 1, ""))
				}
			}
			return true
		})
	}
	for _, d := range fc.ast.Decls {
		if fd, ok := d.(*ast.FuncDecl); ok {
			check(fd.Type.Results, fd.Body)
		}
	}
	ast.Inspect(fc.ast, func(n ast.Node) bool {
		if lit, ok := n.(*ast.FuncLit); ok {
			check(lit.Type.Results, lit.Body)
		}
		return true
	})
	return out
}

func ruleBoolLiteralInExpr(fc *fileContext, _ interface{}) []failure {
	var out []failure
	ast.Inspect(fc.ast, func(n ast.Node) bool {
		be, ok := n.(*ast.BinaryExpr)
		if !ok {
			return true
		}
		switch be.Op {
		case token.EQL, token.NEQ, token.LAND, token.LOR:
		default:
			return true
		}
		if isBoolLiteral(be.X) || isBoolLiteral(be.Y) {
			out = append(out, fc.nodeFailure(be, "omit Boolean literal in expression", "style", 1, ""))
		}
		return true
	})
	return out
}

func isBoolLiteral(e ast.Expr) bool {
	id, ok := e.(*ast.Ident)
	return ok && (id.Name == "true" || id.Name == "false")
}

func ruleCallToGC(fc *fileContext, _ interface{}) []failure {
	var out []failure
	ast.Inspect(fc.ast, func(n ast.Node) bool {
		call, ok := n.(*ast.CallExpr)
		if ok && fc.isCallTo(call, "runtime", "GC") {
			out = append(out, fc.nodeFailure(call, "explicit call to the garbage collector", "bad practice", 1, ""))
		}
		return true
	})
	return out
}

func ruleConfusingResults(fc *fileContext, _ interface{}) []failure {
	var out []failure
	for _, d := range fc.ast.Decls {
		fd, ok := d.(*ast.FuncDecl)
		if !ok || fd.Type.Results == nil {
			continue
		}
		fields := fd.Type.Results.List
		for i := 1; i < len(fields); i++ {
			prev, cur := fields[i-1], fields[i]
			if len(prev.Names) > 0 || len(cur.Names) > 0 {
				continue
			}
			if fc.nodeString(prev.Type) == fc.nodeString(cur.Type) {
				out = append(out, fc.nodeFailure(cur.Type, "unnamed results of the same type may be confusing, consider using named results", "naming", 1, ""))
				break
			}
		}
	}
	return out
}

func equalExpr(fc *fileContext, a, b ast.Expr) bool {
	return fc.nodeString(a) == fc.nodeString(b)
}

func ruleConstantLogicalExpr(fc *fileContext, _ interface{}) []failure {
	var out []failure
	ast.Inspect(fc.ast, func(n ast.Node) bool {
		be, ok := n.(*ast.BinaryExpr)
		if !ok {
			return true
		}
		if !equalExpr(fc, be.X, be.Y) {
			return true
		}
		switch be.Op {
		case token.LAND, token.LOR:
			out = append(out, fc.nodeFailure(be, "left and right hand-side sub-expressions are the same", "logic", 1, ""))
		case token.EQL, token.LEQ, token.GEQ:
			out = append(out, fc.nodeFailure(be, "expression always evaluates to true", "logic", 1, ""))
		case token.NEQ, token.LSS, token.GTR:
			out = append(out, fc.nodeFailure(be, "expression always evaluates to false", "logic", 1, ""))
		}
		return true
	})
	return out
}

func ruleDeepExit(fc *fileContext, _ interface{}) []failure {
	var out []failure
	check := func(node ast.Node) {
		ast.Inspect(node, func(n ast.Node) bool {
			call, ok := n.(*ast.CallExpr)
			if !ok {
				return true
			}
			if fc.isCallTo(call, "os", "Exit") {
				out = append(out, fc.nodeFailure(call, "calls to os.Exit only in main() or init() functions", "bad practice", 1, ""))
			}
			for _, fn := range []string{"Fatal", "Fatalf", "Fatalln"} {
				if fc.isCallTo(call, "log", fn) {
					out = append(out, fc.nodeFailure(call, fmt.Sprintf("calls to log.%s only in main() or init() functions", fn), "bad practice", 1, ""))
				}
			}
			return true
		})
	}
	for _, d := range fc.ast.Decls {
		switch node := d.(type) {
		case *ast.FuncDecl:
			if node.Name.Name == "main" || node.Name.Name == "init" {
				continue
			}
			if node.Body != nil {
				check(node.Body)
			}
		case *ast.GenDecl:
			// package-level variable initialisers containing func literals etc.
			check(node)
		}
	}
	return out
}

func ruleEarlyReturn(fc *fileContext, _ interface{}) []failure {
	var out []failure
	ast.Inspect(fc.ast, func(n ast.Node) bool {
		ifs, ok := n.(*ast.IfStmt)
		if !ok || ifs.Else == nil {
			return true
		}
		elseBlock, ok := ifs.Else.(*ast.BlockStmt)
		if !ok {
			return true
		}
		if _, ok := lastStmt(elseBlock).(*ast.ReturnStmt); !ok {
			return true
		}
		if _, ok := lastStmt(ifs.Body).(*ast.ReturnStmt); ok {
			return true
		}
		out = append(out, fc.nodeFailure(ifs, "if c { ... } else { ... return } can be simplified to if !c { ... return } ...", "", 1, ""))
		return true
	})
	return out
}

func ruleGetReturn(fc *fileContext, _ interface{}) []failure {
	var out []failure
	for _, d := range fc.ast.Decls {
		fd, ok := d.(*ast.FuncDecl)
		if !ok {
			continue
		}
		name := fd.Name.Name
		if len([]rune(name)) <= 3 {
			continue
		}
		if !strings.HasPrefix(name, "Get") && !strings.HasPrefix(name, "get") {
			continue
		}
		fourth := []rune(name)[3]
		// Get/get must be followed by a non-lowercase letter
		if fourth >= 'a' && fourth <= 'z' {
			continue
		}
		if fd.Type.Results != nil && len(fd.Type.Results.List) > 0 {
			continue
		}
		out = append(out, fc.nodeFailure(fd, fmt.Sprintf("function '%s' seems to be a getter but it does not return any result", name), "logic", 0.8, ""))
	}
	return out
}

func ruleIfReturn(fc *fileContext, _ interface{}) []failure {
	var out []failure
	ast.Inspect(fc.ast, func(n ast.Node) bool {
		block, ok := n.(*ast.BlockStmt)
		if !ok {
			return true
		}
		for i := 0; i+1 < len(block.List); i++ {
			if i+2 != len(block.List) {
				continue
			}
			ifs, ok := block.List[i].(*ast.IfStmt)
			if !ok || ifs.Else != nil || ifs.Init == nil {
				continue
			}
			next, ok := block.List[i+1].(*ast.ReturnStmt)
			if !ok || len(next.Results) != 1 || !isIdentName(next.Results[0], "nil") {
				continue
			}
			assign, ok := ifs.Init.(*ast.AssignStmt)
			if !ok || len(assign.Lhs) != 1 {
				continue
			}
			varIdent, ok := assign.Lhs[0].(*ast.Ident)
			if !ok {
				continue
			}
			cond, ok := ifs.Cond.(*ast.BinaryExpr)
			if !ok || cond.Op != token.NEQ || !isIdentName(cond.X, varIdent.Name) || !isIdentName(cond.Y, "nil") {
				continue
			}
			if ifs.Body == nil || len(ifs.Body.List) != 1 {
				continue
			}
			ret, ok := ifs.Body.List[0].(*ast.ReturnStmt)
			if !ok || len(ret.Results) != 1 || !isIdentName(ret.Results[0], varIdent.Name) {
				continue
			}
			out = append(out, fc.nodeFailure(ifs, "redundant if ...; err != nil check, just return error instead.", "", 0.9, ""))
		}
		return true
	})
	return out
}

func isIdentName(expr ast.Expr, name string) bool {
	id, ok := expr.(*ast.Ident)
	return ok && id.Name == name
}

func ruleFlagParameter(fc *fileContext, _ interface{}) []failure {
	var out []failure
	check := func(params *ast.FieldList, body *ast.BlockStmt) {
		if params == nil || body == nil {
			return
		}
		for _, field := range params.List {
			if !isBoolTypeExpr(field.Type) {
				continue
			}
			for _, name := range field.Names {
				if usedAsCondition(fc, name, body) {
					out = append(out, fc.nodeFailure(field, fmt.Sprintf("parameter '%s' seems to be a control flag, avoid control coupling", name.Name), "bad practice", 1, ""))
				}
			}
		}
	}
	for _, d := range fc.ast.Decls {
		if fd, ok := d.(*ast.FuncDecl); ok {
			check(fd.Type.Params, fd.Body)
		}
	}
	ast.Inspect(fc.ast, func(n ast.Node) bool {
		if lit, ok := n.(*ast.FuncLit); ok {
			check(lit.Type.Params, lit.Body)
		}
		return true
	})
	return out
}

func isBoolTypeExpr(expr ast.Expr) bool {
	id, ok := expr.(*ast.Ident)
	if ok && id.Name == "bool" {
		return true
	}
	return false
}

func usedAsCondition(fc *fileContext, param *ast.Ident, body *ast.BlockStmt) bool {
	obj := objectForIdent(fc, param)
	used := false
	ast.Inspect(body, func(n ast.Node) bool {
		if used {
			return false
		}
		var conds []ast.Expr
		switch node := n.(type) {
		case *ast.IfStmt:
			conds = append(conds, node.Cond)
		case *ast.ForStmt:
			if node.Cond != nil {
				conds = append(conds, node.Cond)
			}
		case *ast.BinaryExpr:
			if node.Op == token.LAND || node.Op == token.LOR {
				// handled by containing conditions; not directly needed
			}
		}
		for _, cond := range conds {
			ast.Inspect(cond, func(cn ast.Node) bool {
				if id, ok := cn.(*ast.Ident); ok && id.Name == param.Name {
					if obj == nil || objectForIdent(fc, id) == obj {
						used = true
						return false
					}
				}
				return true
			})
		}
		return true
	})
	return used
}

func objectForIdent(fc *fileContext, id *ast.Ident) types.Object {
	if fc.types == nil {
		return nil
	}
	if o := fc.types.Defs[id]; o != nil {
		return o
	}
	return fc.types.Uses[id]
}

func ruleNestedStructs(fc *fileContext, _ interface{}) []failure {
	var out []failure
	ast.Inspect(fc.ast, func(n ast.Node) bool {
		st, ok := n.(*ast.StructType)
		if !ok || st.Fields == nil {
			return true
		}
		for _, field := range st.Fields.List {
			if inner := nestedStructType(field.Type); inner != nil {
				out = append(out, fc.nodeFailure(inner, "no nested structs are allowed", "style", 1, ""))
			}
		}
		return true
	})
	return out
}

func nestedStructType(expr ast.Expr) *ast.StructType {
	switch t := expr.(type) {
	case *ast.StructType:
		return t
	case *ast.StarExpr:
		return nestedStructType(t.X)
	case *ast.ArrayType:
		return nestedStructType(t.Elt)
	case *ast.MapType:
		// reference does not flag map values? keep only direct containers observed: array/slice/pointer
		return nil
	case *ast.ChanType:
		return nestedStructType(t.Value)
	case *ast.ParenExpr:
		return nestedStructType(t.X)
	}
	return nil
}

func ruleStringOfInt(fc *fileContext, _ interface{}) []failure {
	var out []failure
	ast.Inspect(fc.ast, func(n ast.Node) bool {
		call, ok := n.(*ast.CallExpr)
		if !ok || len(call.Args) != 1 {
			return true
		}
		id, ok := call.Fun.(*ast.Ident)
		if !ok || id.Name != "string" {
			return true
		}
		t := fc.typeOf(call.Args[0])
		if t == nil {
			return true
		}
		basic, ok := t.Underlying().(*types.Basic)
		if !ok {
			return true
		}
		if (basic.Info()&types.IsInteger) != 0 && basic.Kind() != types.Byte && basic.Kind() != types.Rune && basic.Kind() != types.UntypedRune {
			// Untyped integer constant is okay? reference flagged string(123)
			out = append(out, fc.nodeFailure(call, "dubious conversion of an integer into a string, use strconv.Itoa", "", 1, ""))
		}
		return true
	})
	return out
}

func (fc *fileContext) isTimeType(t types.Type) bool {
	named, ok := t.(*types.Named)
	if !ok || named.Obj() == nil {
		return false
	}
	return named.Obj().Name() == "Time" && named.Obj().Pkg() != nil && named.Obj().Pkg().Path() == "time"
}

func ruleTimeEqual(fc *fileContext, _ interface{}) []failure {
	var out []failure
	ast.Inspect(fc.ast, func(n ast.Node) bool {
		be, ok := n.(*ast.BinaryExpr)
		if !ok || (be.Op != token.EQL && be.Op != token.NEQ) {
			return true
		}
		if !fc.isTimeType(fc.typeOf(be.X)) {
			return true
		}
		var msg string
		if be.Op == token.EQL {
			msg = fmt.Sprintf("use %s.Equal(%s) instead of \"==\" operator", fc.nodeString(be.X), fc.nodeString(be.Y))
		} else {
			msg = fmt.Sprintf("use !%s.Equal(%s) instead of \"!=\" operator", fc.nodeString(be.X), fc.nodeString(be.Y))
		}
		out = append(out, fc.nodeFailure(be, msg, "time", 1, ""))
		return true
	})
	return out
}

func ruleUnnecessaryFormat(fc *fileContext, _ interface{}) []failure {
	type entry struct {
		pkg, name, replacement, suffix string
		formatIndex                    int
	}
	entries := []entry{
		{"fmt", "Printf", "fmt.Print", " or \"fmt.Println\"", 0},
		{"fmt", "Sprintf", "fmt.Sprint", " or just the string itself", 0},
		{"fmt", "Errorf", "errors.New", "", 0},
		{"fmt", "Fprintf", "fmt.Fprint", "", 1},
		{"log", "Printf", "log.Print", "", 0},
		{"log", "Fatalf", "log.Fatal", "", 0},
		{"log", "Panicf", "log.Panic", "", 0},
	}
	var out []failure
	for _, e := range entries {
		ast.Inspect(fc.ast, func(n ast.Node) bool {
			call, ok := n.(*ast.CallExpr)
			if !ok || !fc.isCallTo(call, e.pkg, e.name) {
				return true
			}
			if len(call.Args) != e.formatIndex+1 {
				return true
			}
			lit, ok := call.Args[e.formatIndex].(*ast.BasicLit)
			if !ok || lit.Kind != token.STRING {
				return true
			}
			if strings.Contains(lit.Value, "%") {
				return true
			}
			sel := call.Fun.(*ast.SelectorExpr)
			msg := fmt.Sprintf("unnecessary use of formatting function \"%s.%s\", you can replace it with \"%s\"%s", e.pkg, e.name, e.replacement, e.suffix)
			out = append(out, fc.nodeFailure(sel, msg, "optimization", 0.8, ""))
			return true
		})
	}
	return out
}

func negatedCondition(fc *fileContext, cond ast.Expr) string {
	if be, ok := cond.(*ast.BinaryExpr); ok {
		var neg token.Token
		switch be.Op {
		case token.EQL:
			neg = token.NEQ
		case token.NEQ:
			neg = token.EQL
		case token.LSS:
			neg = token.GEQ
		case token.LEQ:
			neg = token.GTR
		case token.GTR:
			neg = token.LEQ
		case token.GEQ:
			neg = token.LSS
		}
		if neg != token.ILLEGAL {
			return fmt.Sprintf("%s %s %s", fc.nodeString(be.X), neg.String(), fc.nodeString(be.Y))
		}
	}
	return "!(" + fc.nodeString(cond) + ")"
}

func singleBoolReturn(block *ast.BlockStmt) (string, bool) {
	if block == nil || len(block.List) != 1 {
		return "", false
	}
	ret, ok := block.List[0].(*ast.ReturnStmt)
	if !ok || len(ret.Results) != 1 {
		return "", false
	}
	id, ok := ret.Results[0].(*ast.Ident)
	if !ok || (id.Name != "true" && id.Name != "false") {
		return "", false
	}
	return id.Name, true
}

func ruleUnnecessaryIf(fc *fileContext, _ interface{}) []failure {
	var out []failure
	ast.Inspect(fc.ast, func(n ast.Node) bool {
		ifs, ok := n.(*ast.IfStmt)
		if !ok || ifs.Init != nil || ifs.Else == nil {
			return true
		}
		elseBlock, ok := ifs.Else.(*ast.BlockStmt)
		if !ok {
			return true
		}
		thenVal, ok1 := singleBoolReturn(ifs.Body)
		elseVal, ok2 := singleBoolReturn(elseBlock)
		if !ok1 || !ok2 || thenVal == elseVal {
			return true
		}
		var expr string
		if thenVal == "true" {
			expr = fc.nodeString(ifs.Cond)
		} else {
			expr = negatedCondition(fc, ifs.Cond)
		}
		out = append(out, fc.nodeFailure(ifs, fmt.Sprintf("replace this conditional by: return %s", expr), "logic", 1, ""))
		return true
	})
	return out
}

func ruleUnnecessaryStmt(fc *fileContext, _ interface{}) []failure {
	var out []failure
	for _, d := range fc.ast.Decls {
		fd, ok := d.(*ast.FuncDecl)
		if !ok || fd.Body == nil {
			continue
		}
		if fd.Type.Results != nil && len(fd.Type.Results.List) > 0 {
			continue
		}
		if len(fd.Body.List) == 0 {
			continue
		}
		if ret, ok := fd.Body.List[len(fd.Body.List)-1].(*ast.ReturnStmt); ok && len(ret.Results) == 0 {
			out = append(out, fc.nodeFailure(ret, "omit unnecessary return statement", "style", 1, ""))
		}
	}
	return out
}

func ruleUseAny(fc *fileContext, _ interface{}) []failure {
	var out []failure
	ast.Inspect(fc.ast, func(n ast.Node) bool {
		it, ok := n.(*ast.InterfaceType)
		if !ok {
			return true
		}
		if it.Methods == nil || len(it.Methods.List) == 0 {
			out = append(out, fc.nodeFailure(it, "since Go 1.18 'interface{}' can be replaced by 'any'", "naming", 1, ""))
		}
		return true
	})
	return out
}

func ruleUseErrorsNew(fc *fileContext, _ interface{}) []failure {
	var out []failure
	ast.Inspect(fc.ast, func(n ast.Node) bool {
		call, ok := n.(*ast.CallExpr)
		if ok && fc.isCallTo(call, "fmt", "Errorf") && len(call.Args) == 1 {
			out = append(out, fc.nodeFailure(call, "replace fmt.Errorf by errors.New", "errors", 1, ""))
		}
		return true
	})
	return out
}

func ruleUseFmtPrint(fc *fileContext, _ interface{}) []failure {
	var out []failure
	ast.Inspect(fc.ast, func(n ast.Node) bool {
		call, ok := n.(*ast.CallExpr)
		if !ok {
			return true
		}
		id, ok := call.Fun.(*ast.Ident)
		if !ok || (id.Name != "print" && id.Name != "println") {
			return true
		}
		// ensure it's the builtin if type info is present
		if fc.types != nil {
			if obj := fc.types.Uses[id]; obj != nil && obj.Parent() != types.Universe {
				return true
			}
		}
		var argStrs []string
		for _, a := range call.Args {
			argStrs = append(argStrs, fc.nodeString(a))
		}
		replacementFn := "fmt.Fprint"
		if id.Name == "println" {
			replacementFn = "fmt.Fprintln"
		}
		replacement := replacementFn + "(os.Stderr, " + strings.Join(argStrs, ", ") + ")"
		msg := fmt.Sprintf("avoid using built-in function \"%s\", replace it by \"%s\"", id.Name, replacement)
		out = append(out, fc.nodeFailure(call, msg, "bad practice", 1, ""))
		return true
	})
	return out
}

func ruleUseSlicesSort(fc *fileContext, _ interface{}) []failure {
	mapping := map[string]string{
		"Ints": "slices.Sort", "Strings": "slices.Sort", "Float64s": "slices.Sort",
		"Slice": "slices.SortFunc", "SliceStable": "slices.SortStableFunc", "SliceIsSorted": "slices.IsSortedFunc",
		"Sort": "slices.SortFunc", "Stable": "slices.SortStableFunc", "IsSorted": "slices.IsSortedFunc",
		"IntsAreSorted": "slices.IsSorted", "StringsAreSorted": "slices.IsSorted", "Float64sAreSorted": "slices.IsSorted",
	}
	var out []failure
	for fn, repl := range mapping {
		ast.Inspect(fc.ast, func(n ast.Node) bool {
			call, ok := n.(*ast.CallExpr)
			if ok && fc.isCallTo(call, "sort", fn) {
				out = append(out, fc.nodeFailure(call, fmt.Sprintf("replace sort.%s by %s", fn, repl), "maintenance", 1, ""))
			}
			return true
		})
	}
	return out
}

func ruleUselessBreak(fc *fileContext, _ interface{}) []failure {
	var out []failure
	checkClause := func(list []ast.Stmt) {
		if len(list) == 0 {
			return
		}
		if br, ok := list[len(list)-1].(*ast.BranchStmt); ok && br.Tok == token.BREAK && br.Label == nil {
			out = append(out, fc.nodeFailure(br, "useless break in case clause", "", 1, ""))
		}
	}
	ast.Inspect(fc.ast, func(n ast.Node) bool {
		switch node := n.(type) {
		case *ast.CaseClause:
			checkClause(node.Body)
		case *ast.CommClause:
			checkClause(node.Body)
		}
		return true
	})
	return out
}

func ruleUselessFallthrough(fc *fileContext, _ interface{}) []failure {
	var out []failure
	ast.Inspect(fc.ast, func(n ast.Node) bool {
		sw, ok := n.(*ast.SwitchStmt)
		if !ok || sw.Body == nil {
			return true
		}
		for _, stmt := range sw.Body.List {
			clause, ok := stmt.(*ast.CaseClause)
			if !ok || len(clause.Body) == 0 {
				continue
			}
			// Only fallthrough when the clause body is just the fallthrough (empty clause effect):
			// reference flags a clause whose sole statement is fallthrough.
			if len(clause.Body) == 1 {
				if br, ok := clause.Body[0].(*ast.BranchStmt); ok && br.Tok == token.FALLTHROUGH {
					out = append(out, fc.nodeFailure(br, "this \"fallthrough\" can be removed by consolidating this case clause with the next one", "style", 1, ""))
				}
			}
		}
		return true
	})
	return out
}
