package main

import (
	"fmt"
	"go/ast"
	"path/filepath"
	"regexp"
	"strings"
)

func init() {
	registerRule("comment-spacings", configureCommentSpacings, ruleCommentSpacings)
	registerRule("comments-density", configureCommentsDensity, ruleCommentsDensity)
	registerRule("duplicated-imports", nil, ruleDuplicatedImports)
	registerRule("enforce-map-style", configureEnforceMapStyle, ruleEnforceMapStyle)
	registerRule("enforce-repeated-arg-type-style", configureEnforceRepeated, ruleEnforceRepeated)
	registerRule("enforce-slice-style", configureEnforceSliceStyle, ruleEnforceSliceStyle)
	registerRule("enforce-switch-style", configEnforceSwitch, ruleEnforceSwitch)
	registerRule("file-header", configureFileHeader, ruleFileHeader)
	registerRule("filename-format", configureFilenameFormat, ruleFilenameFormat)
	registerRule("import-alias-naming", configureImportAliasNaming, ruleImportAliasNaming)
