// comment-spacings
type commentSpacingsOptions struct{ allow []string }

func configureCommentSpacings(args []interface{}) (interface{}, error) {
	opts := &commentSpacingsOptions{}
	for _, arg := range args {
		s, ok := arg.(string)
		if !ok {
			return nil, fmt.Errorf("invalid argument %v for comment-spacings; expected string but got %s", arg, typeName(arg))
		}
		opts.allow = append(opts.allow, s)
	}
	return opts, nil
}

var directiveRe = regexp.MustCompile(`^//[a-z][a-z0-9]*:.+`)

func ruleCommentSpacings(fc *fileContext, optsI interface{}) []failure {
	opts, _ := optsI.(*commentSpacingsOptions)
	if opts == nil {
		opts = &commentSpacingsOptions{}
	}
	var out []failure
	for _, group := range fc.comments {
		for _, c := range group.List {
			text := c.Text
			if len(text) <= 2 {
				continue
			}
			rest := text[2:]
			if rest == "" {
				continue
			}
			first := rest[0]
			if first == ' ' || first == '\t' || first == '\n' || first == '\r' {
				continue
			}
			// Directives like //go:generate, //revive:disable, //export, //extern
			if strings.HasPrefix(text, "//") && (directiveRe.MatchString(text) || strings.HasPrefix(text, "//export") || strings.HasPrefix(text, "//extern")) {
				continue
			}
			allowed := false
			for _, a := range opts.allow {
				if strings.HasPrefix(rest, a) {
					allowed = true
					break
				}
			}
			if allowed {
				continue
			}
			out = append(out, fc.nodeFailure(c, "no space between comment delimiter and comment text", "style", 1, ""))
		}
	}
	return out
}

// comments-density
type commentsDensityOptions struct{ min int }

func configureCommentsDensity(args []interface{}) (interface{}, error) {
	opts := &commentsDensityOptions{}
	if len(args) == 0 {
		return opts, nil
	}
	n, ok := integerArg(args[0])
	if !ok {
		return nil, fmt.Errorf("invalid argument for \"comments-density\" rule: argument should be an int, got %s", typeName(args[0]))
	}
	opts.min = n
	return opts, nil
}

func ruleCommentsDensity(fc *fileContext, optsI interface{}) []failure {
	opts, _ := optsI.(*commentsDensityOptions)
	if opts == nil {
		opts = &commentsDensityOptions{}
	}
	commentLines := 0
	for _, group := range fc.comments {
		text := group.Text()
		if text != "" {
			commentLines += strings.Count(text, "\n")
		}
	}
	codeLines := 0
	ast.Inspect(fc.ast, func(n ast.Node) bool {
		switch n.(type) {
		case *ast.FuncDecl:
			codeLines++
		case ast.Stmt:
			switch n.(type) {
			case *ast.BlockStmt, *ast.LabeledStmt, *ast.EmptyStmt:
				// not counted
			default:
				codeLines++
			}
		}
		return true
	})
	total := commentLines + codeLines
	if total == 0 {
		return nil
	}
	density := 0
	if total > 0 {
		density = (100 * commentLines) / total
	}
	if density < opts.min {
		msg := fmt.Sprintf("the file has a comment density of %3d%% (%d comment lines for %d code lines) but expected a minimum of %d%%", density, commentLines, codeLines, opts.min)
		return []failure{fc.nodeFailure(fc.ast, msg, "", 1, "")}
	}
	return nil
}

func ruleDuplicatedImports(fc *fileContext, _ interface{}) []failure {
	var out []failure
	seen := map[string]bool{}
	for _, spec := range fc.ast.Imports {
		path := spec.Path.Value
		if seen[path] {
			out = append(out, fc.nodeFailure(spec, fmt.Sprintf("Package %s already imported", path), "imports", 1, ""))
		} else {
			seen[path] = true
		}
	}
	return out
}

// enforce-map-style

func configureEnforceMapStyle(args []interface{}) (interface{}, error) {
	style := "any"
	if len(args) > 0 {
		s, ok := args[0].(string)
		if !ok {
			return nil, fmt.Errorf("invalid argument '%v' for 'enforce-map-style' rule. Expecting string, got %s", args[0], typeName(args[0]))
		}
		switch s {
		case "any", "make", "literal":
			style = s
		default:
			return nil, fmt.Errorf("invalid argument to the enforce-map-style rule: invalid map style: %s (expecting one of [any make literal])", s)
		}
	}
	return style, nil
}

func ruleEnforceMapStyle(fc *fileContext, optsI interface{}) []failure {
	style, _ := optsI.(string)
	if style == "any" || style == "" {
		return nil
	}
	var out []failure
	ast.Inspect(fc.ast, func(n ast.Node) bool {
		switch node := n.(type) {
		case *ast.CompositeLit:
			if style == "make" {
				if mt, ok := node.Type.(*ast.MapType); ok && mt != nil && len(node.Elts) == 0 {
					out = append(out, fc.nodeFailure(node, "use make(map[type]type) instead of map[type]type{}", "style", 1, ""))
				}
			}
		case *ast.CallExpr:
			if style == "literal" && isIdentName(node.Fun, "make") && len(node.Args) >= 1 {
				if mt, ok := node.Args[0].(*ast.MapType); ok {
					out = append(out, fc.nodeFailure(mt, "use map[type]type{} instead of make(map[type]type)", "style", 1, ""))
				}
			}
		}
		return true
	})
	return out
}

func configureEnforceSliceStyle(args []interface{}) (interface{}, error) {
	style := "any"
	if len(args) > 0 {
		s, ok := args[0].(string)
		if !ok {
			return nil, fmt.Errorf("invalid argument '%v' for 'enforce-slice-style' rule. Expecting string, got %s", args[0], typeName(args[0]))
		}
		switch s {
		case "any", "make", "literal", "nil":
			style = s
		default:
			return nil, fmt.Errorf("invalid argument to the enforce-slice-style rule: invalid slice style: %s (expecting one of [any make literal nil])", s)
		}
	}
	return style, nil
}

func isZeroLiteral(expr ast.Expr) bool {
	lit, ok := expr.(*ast.BasicLit)
	return ok && lit.Value == "0"
}

func ruleEnforceSliceStyle(fc *fileContext, optsI interface{}) []failure {
	style, _ := optsI.(string)
	if style == "any" || style == "" {
		return nil
	}
	var out []failure
	ast.Inspect(fc.ast, func(n ast.Node) bool {
		switch node := n.(type) {
		case *ast.CompositeLit:
			if arr, ok := node.Type.(*ast.ArrayType); ok && arr.Len == nil && len(node.Elts) == 0 {
				switch style {
				case "make":
					out = append(out, fc.nodeFailure(node, "use make([]type) instead of []type{} (or declare nil slice)", "style", 1, ""))
				case "nil":
					out = append(out, fc.nodeFailure(node, "use nil slice declaration (e.g. var args []type) instead of []type{}", "style", 1, ""))
				}
			}
		case *ast.CallExpr:
			if isIdentName(node.Fun, "make") && len(node.Args) == 2 && isZeroLiteral(node.Args[1]) {
				if arr, ok := node.Args[0].(*ast.ArrayType); ok && arr.Len == nil {
					switch style {
					case "literal":
						out = append(out, fc.nodeFailure(arr, "use []type{} instead of make([]type, 0) (or declare nil slice)", "style", 1, ""))
					case "nil":
						out = append(out, fc.nodeFailure(arr, "use nil slice declaration (e.g. var args []type) instead of make([]type, 0)", "style", 1, ""))
					}
				}
			}
		}
		return true
	})
	return out
}

// enforce-repeated-arg-type-style

type repeatedStyleOptions struct {
	funcArgStyle, funcRetStyle string
}

func validateRepeatedStyle(s string) error {
	switch s {
	case "any", "short", "full":
		return nil
	default:
		return fmt.Errorf("invalid argument to the enforce-repeated-arg-type-style rule: invalid repeated arg type style: %s (expecting one of [any short full])", s)
	}
}

func configureEnforceRepeated(args []interface{}) (interface{}, error) {
	opts := &repeatedStyleOptions{funcArgStyle: "any", funcRetStyle: "any"}
	if len(args) == 0 {
		return opts, nil
	}
	switch arg := args[0].(type) {
	case string:
		if err := validateRepeatedStyle(arg); err != nil {
			return nil, err
		}
		opts.funcArgStyle = arg
		opts.funcRetStyle = arg
	case map[string]interface{}:
		for k, v := range arg {
			if k != "funcArgStyle" && k != "funcRetValStyle" {
				return nil, fmt.Errorf("invalid map key for 'enforce-repeated-arg-type-style' rule. Expecting 'funcArgStyle' or 'funcRetValStyle', got %s", k)
			}
			s, ok := v.(string)
			if !ok {
				return nil, fmt.Errorf("invalid map value type for 'enforce-repeated-arg-type-style' rule. Expecting string, got %s", typeName(v))
			}
			if err := validateRepeatedStyle(s); err != nil {
				return nil, err
			}
			if k == "funcArgStyle" {
				opts.funcArgStyle = s
			} else {
				opts.funcRetStyle = s
			}
		}
	default:
		return nil, fmt.Errorf("invalid argument '%v' for 'import-alias-naming' rule. Expecting string or map[string]string, got %s", arg, typeName(arg))
	}
	return opts, nil
}

func checkRepeatedFieldList(fc *fileContext, fl *ast.FieldList, style string, kind string) []failure {
	if fl == nil || style == "any" || style == "" {
		return nil
	}
	var out []failure
	if style == "full" {
		for _, field := range fl.List {
			if len(field.Names) > 1 {
				out = append(out, fc.nodeFailure(field, kind+" types should not be omitted", "style", 1, ""))
			}
		}
		return out
	}
	// short
	prevType := ""
	prevSingle := false
	for _, field := range fl.List {
		ts := fc.nodeString(field.Type)
		single := len(field.Names) == 1
		if prevSingle && single && prevType == ts {
			what := "argument"
			if kind == "return" {
				what = "return"
			}
			out = append(out, fc.nodeFailure(field.Type, fmt.Sprintf("repeated %s type %q can be omitted", what, ts), "style", 1, ""))
		}
		prevType = ts
		prevSingle = single || len(field.Names) > 0 && prevSingle && prevType == ts
		// A grouped field is already short form; subsequent repeated single fields after a grouped one:
		// prevSingle should reflect that the previous field declares the single type once; grouped counts as having type declared.
		if len(field.Names) > 1 {
			prevSingle = true // type is present on this field; next single same type can be omitted (approximation)
			prevType = ts
		}
		if len(field.Names) == 0 {
			prevSingle = true
			prevType = ts
		}
	}
	return out
}

func ruleEnforceRepeated(fc *fileContext, optsI interface{}) []failure {
	opts, _ := optsI.(*repeatedStyleOptions)
	if opts == nil {
		return nil
	}
	var out []failure
	for _, d := range fc.ast.Decls {
		fd, ok := d.(*ast.FuncDecl)
		if !ok {
			continue
		}
		out = append(out, checkRepeatedFieldList(fc, fd.Type.Params, opts.funcArgStyle, "argument")...)
		out = append(out, checkRepeatedFieldList(fc, fd.Type.Results, opts.funcRetStyle, "return")...)
	}
	return out
}

// enforce-switch-style
type switchStyleOptions struct {
	allowNoDefault, allowDefaultNotLast bool
}

func configEnforceSwitch(args []interface{}) (interface{}, error) {
	opts := &switchStyleOptions{}
	for _, arg := range args {
		s, ok := arg.(string)
		if !ok {
			return nil, fmt.Errorf("invalid argument for rule enforce-switch-style; expected string but got %s", typeName(arg))
		}
		switch s {
		case "allowNoDefault":
			opts.allowNoDefault = true
		case "allowDefaultNotLast":
			opts.allowDefaultNotLast = true
		default:
			return nil, fmt.Errorf("invalid argument %q for rule enforce-switch-style; expected \"allowNoDefault\" or \"allowDefaultNotLast\"", s)
		}
	}
	return opts, nil
}

func ruleEnforceSwitch(fc *fileContext, optsI interface{}) []failure {
	opts, _ := optsI.(*switchStyleOptions)
	if opts == nil {
		opts = &switchStyleOptions{}
	}
	var out []failure
	ast.Inspect(fc.ast, func(n ast.Node) bool {
		sw, ok := n.(*ast.SwitchStmt)
		if !ok || sw.Body == nil || len(sw.Body.List) == 0 {
			return true
		}
		defaultIdx := -1
		var defaultClause *ast.CaseClause
		for i, stmt := range sw.Body.List {
			if c, ok := stmt.(*ast.CaseClause); ok && c.List == nil {
				defaultIdx = i
				defaultClause = c
				break
			}
		}
		if defaultIdx == -1 {
			if !opts.allowNoDefault {
				out = append(out, fc.nodeFailure(sw, "switch must have a default case clause", "style", 1, ""))
			}
		} else if defaultIdx != len(sw.Body.List)-1 && !opts.allowDefaultNotLast {
			out = append(out, fc.nodeFailure(defaultClause, "default case clause must be the last one", "style", 1, ""))
		}
		return true
	})
	return out
}

// file-header
type fileHeaderOptions struct {
	pattern *regexp.Regexp
	hasArg  bool
}

func configureFileHeader(args []interface{}) (interface{}, error) {
	opts := &fileHeaderOptions{}
	if len(args) == 0 {
		return opts, nil
	}
	s, ok := args[0].(string)
	if !ok {
		return nil, fmt.Errorf("invalid argument for \"file-header\" rule: argument should be a string, got %s", typeName(args[0]))
	}
	opts.hasArg = true
	opts.pattern, _ = regexp.Compile(s) // invalid regex -> nil, behaves like reference (only requires existence of a header)
	return opts, nil
}

func fileHeaderText(fc *fileContext) (string, bool) {
	if len(fc.comments) == 0 {
		return "", false
	}
	group := fc.comments[0]
	var parts []string
	for _, c := range group.List {
		text := c.Text
		if strings.HasPrefix(text, "//") {
			text = text[2:]
		} else if strings.HasPrefix(text, "/*") {
			text = strings.TrimPrefix(text, "/*")
			text = strings.TrimSuffix(text, "*/")
		}
		parts = append(parts, text)
	}
	return strings.Join(parts, ""), true
}

func ruleFileHeader(fc *fileContext, optsI interface{}) []failure {
	opts, _ := optsI.(*fileHeaderOptions)
	if opts == nil || !opts.hasArg {
		return nil
	}
	header, has := fileHeaderText(fc)
	if !has {
		return []failure{fc.nodeFailure(fc.ast, "the file doesn't have an appropriate header", "", 1, "")}
	}
	if opts.pattern == nil {
		return nil
	}
	if !opts.pattern.MatchString(header) {
		return []failure{fc.nodeFailure(fc.ast, "the file doesn't have an appropriate header", "", 1, "")}
	}
	return nil
}

// filename-format

type filenameOptions struct {
	patternStr string
	pattern    *regexp.Regexp
}

func configureFilenameFormat(args []interface{}) (interface{}, error) {
	patternStr := `^[_A-Za-z0-9][_A-Za-z0-9-]*\.go$`
	if len(args) > 0 {
		s, ok := args[0].(string)
		if !ok {
			return nil, fmt.Errorf("rule \"filename-format\" expects a string argument, got %v of type %s", args[0], typeName(args[0]))
		}
		patternStr = s
	}
	re, err := regexp.Compile(patternStr)
	if err != nil {
		return nil, fmt.Errorf("rule \"filename-format\" expects a valid regexp argument, got error for %s: %s", patternStr, err.Error())
	}
	return &filenameOptions{patternStr: patternStr, pattern: re}, nil
}

func ruleFilenameFormat(fc *fileContext, optsI interface{}) []failure {
	opts, _ := optsI.(*filenameOptions)
	if opts == nil {
		return nil
	}
	base := filepath.Base(fc.name)
	if !opts.pattern.MatchString(base) {
		return []failure{fc.nodeFailure(fc.ast.Name, fmt.Sprintf("Filename %s is not of the format %s.", base, opts.patternStr), "", 1, "")}
	}
	return nil
}

// import-alias-naming

type importAliasOptions struct {
	allowStr string
	denyStr  string
	allowRe  *regexp.Regexp
	denyRe   *regexp.Regexp
}

func compileAliasRegex(kind, value string) (*regexp.Regexp, error) {
	re, err := regexp.Compile(value)
	if err != nil {
		return nil, fmt.Errorf("invalid argument to the import-alias-naming %s rule. Expecting %q to be a valid regular expression, got: %s", kind, value, err.Error())
	}
	return re, nil
}

func configureImportAliasNaming(args []interface{}) (interface{}, error) {
	opts := &importAliasOptions{allowStr: `^[a-z][a-z0-9]{0,}$`}
	opts.allowRe, _ = regexp.Compile(opts.allowStr)
	if len(args) == 0 {
		return opts, nil
	}
	switch arg := args[0].(type) {
	case string:
		re, err := compileAliasRegex("allowRegexp", arg)
		if err != nil {
			return nil, err
		}
		opts.allowStr = arg
		opts.allowRe = re
	case map[string]interface{}:
		opts.allowStr = ""
		opts.allowRe = nil
		for k, v := range arg {
			if k != "allowRegex" && k != "denyRegex" {
				return nil, fmt.Errorf("invalid map key for 'import-alias-naming' rule. Expecting 'allowRegex' or 'denyRegex', got %s", k)
			}
			s, ok := v.(string)
			kind := "allowRegexp"
			if k == "denyRegex" {
				kind = "denyRegexp"
			}
			if !ok {
				return nil, fmt.Errorf("invalid argument '%v' for import-alias-naming %s rule. Expecting string, got %s", v, kind, typeName(v))
			}
			re, err := compileAliasRegex(kind, s)
			if err != nil {
				return nil, err
			}
			if k == "allowRegex" {
				opts.allowStr = s
				opts.allowRe = re
			} else {
				opts.denyStr = s
				opts.denyRe = re
			}
		}
	default:
		return nil, fmt.Errorf("invalid argument '%v' for 'import-alias-naming' rule. Expecting string or map[string]string, got %s", arg, typeName(arg))
	}
	return opts, nil
}

func ruleImportAliasNaming(fc *fileContext, optsI interface{}) []failure {
	opts, _ := optsI.(*importAliasOptions)
	if opts == nil {
		return nil
	}
	var out []failure
	for _, spec := range fc.ast.Imports {
		if spec.Name == nil {
			continue
		}
		name := spec.Name.Name
		if name == "_" || name == "." {
			continue
		}
		if opts.allowRe != nil && !opts.allowRe.MatchString(name) {
			out = append(out, fc.nodeFailure(spec.Name, fmt.Sprintf("import name (%s) must match the regular expression: %s", name, opts.allowStr), "imports", 1, ""))
			continue
		}
		if opts.denyRe != nil && opts.denyRe.MatchString(name) {
			out = append(out, fc.nodeFailure(spec.Name, fmt.Sprintf("import name (%s) must NOT match the regular expression: %s", name, opts.denyStr), "imports", 1, ""))
		}
	}
	return out
}

// imports-blocklist

func configureImportsBlocklist(args []interface{}) (interface{}, error) {
	var list []string
	for _, arg := range args {
		s, ok := arg.(string)
		if !ok {
			return nil, fmt.Errorf("invalid argument to the imports-blocklist rule. Expecting a string, got %s", typeName(arg))
		}
		list = append(list, s)
	}
	return map[string]boolFrom(list), nil
}

func map[string]boolFrom(list []string) map[string]bool {
	m := map[string]bool{}
	for _, s := range list {
		m[s] = true
	}
	return m
}

func ruleImportsBlocklist(fc *fileContext, optsI interface{}) []failure {
	blocked, _ := optsI.(map[string]bool)
	var out []failure
	for _, spec := range fc.ast.Imports {
		path := strings.Trim(spec.Path.Value, "\"`")
		if blocked[path] {
			out = append(out, fc.nodeFailure(spec.Path, fmt.Sprintf("should not use the following blocklisted import: %s", spec.Path.Value), "imports", 1, ""))
		}
	}
	return out
}

func ruleRedundantImportAlias(fc *fileContext, _ interface{}) []failure {
	var out []failure
	for _, spec := range fc.ast.Imports {
		if spec.Name == nil || spec.Name.Name == "_" || spec.Name.Name == "." {
			continue
		}
		path := strings.Trim(spec.Path.Value, "\"`")
		base := path
		if i := strings.LastIndex(path, "/"); i >= 0 {
			base = path[i+1:]
		}
		if spec.Name.Name == base {
			out = append(out, fc.nodeFailure(spec, fmt.Sprintf("Import alias %q is redundant", spec.Name.Name), "imports", 1, ""))
		}
	}
	return out
}
