func configureArgumentLimit(args []interface{}) (interface{}, error) {
	max := int64(8)
	if len(args) > 0 {
		v, ok := args[0].(int64)
		if !ok {
			return nil, fmt.Errorf("invalid value passed as argument number to the \"argument-limit\" rule")
		}
		max = v
	}
	return max, nil
}

func countFieldListEntries(fl *ast.FieldList) int {
	if fl == nil {
		return 0
	}
	n := 0
	for _, f := range fl.List {
		if len(f.Names) == 0 {
			n++
		} else {
			n += len(f.Names)
		}
	}
	return n
}

func ruleArgumentLimit(fc *fileContext, optsI interface{}) []failure {
	max, _ := optsI.(int64)
	var out []failure
	for _, d := range fc.ast.Decls {
		fd, ok := d.(*ast.FuncDecl)
		if !ok {
			continue
		}
		got := countFieldListEntries(fd.Type.Params)
		if int64(got) > max {
			out = append(out, fc.nodeFailure(fd.Type, fmt.Sprintf("maximum number of arguments per function exceeded; max %d but got %d", max, got), "", 1, ""))
		}
	}
	return out
}

