		got := countFieldListEntries(fd.Type.Results)
		if int64(got) > max {
			out = append(out, fc.nodeFailure(fd.Type, fmt.Sprintf("maximum number of return results per function exceeded; max %d but got %d", max, got), "", 1, ""))
		}
	}
	return out
}

func configureLineLength(args []interface{}) (interface{}, error) {
	max := int64(80)
	if len(args) > 0 {
		v, ok := args[0].(int64)
		if !ok {
			return nil, fmt.Errorf("invalid value passed as argument number to the \"line-length-limit\" rule")
		}
		max = v
	}
	return max, nil
}

func physicalLines(content []byte) []string {
	var lines []string
	sc := bufio.NewScanner(strings.NewReader(string(content)))
	// Increase buffer for very long lines
	sc.Buffer(make([]byte, 1024*64), 1024*1024*16)
	for sc.Scan() {
		lines = append(lines, sc.Text())
	}
	return lines
}

func ruleLineLength(fc *fileContext, optsI interface{}) []failure {
	max, _ := optsI.(int64)
	var out []failure
	lines := physicalLines(fc.content)
	for i, line := range lines {
		l := utf8.RuneCountInString(line)
		if int64(l) > max {
			start := token.Position{Filename: fc.name, Offset: 0, Line: i + 1, Column: 0}
			end := token.Position{Filename: fc.name, Offset: 0, Line: i + 1, Column: l}
			out = append(out, failure{
				Failure:    fmt.Sprintf("line is %d characters, out of limit %d", l, max),
				Category:   "style",
				Position:   failurePosition{Start: start, End: end},
				Confidence: 1,
			})
		}
	}
	return out
}

// file-length-limit
type fileLengthOptions struct {
	max            int64
	skipComments   bool
	skipBlankLines bool
}

func configureFileLength(args []interface{}) (interface{}, error) {
	opts := &fileLengthOptions{}
	if len(args) == 0 {
		return opts, nil
	}
	m, ok := args[0].(map[string]interface{})
	if !ok {
		return nil, fmt.Errorf("invalid argument to the \"file-length-limit\" rule. Expecting a k,v map, got %s", typeName(args[0]))
	}
	for k, v := range m {
		switch k {
		case "max":
			n, ok := v.(int64)
			if !ok || n < 0 {
				return nil, fmt.Errorf("invalid configuration value for max lines in \"file-length-limit\" rule; need positive int64 but got %s", typeName(v))
			}
			opts.max = n
		case "skipComments":
			if b, ok := v.(bool); ok {
				opts.skipComments = b
			}
		case "skipBlankLines":
			if b, ok := v.(bool); ok {
				opts.skipBlankLines = b
			}
		}
	}
	return opts, nil
}

func ruleFileLength(fc *fileContext, optsI interface{}) []failure {
	opts, _ := optsI.(*fileLengthOptions)
	if opts == nil || opts.max == 0 {
		return nil
	}
	lines := physicalLines(fc.content)
	commentLines := map[int]bool{}
	if opts.skipComments {
		for _, group := range fc.comments {
			for _, c := range group.List {
				start := fc.fset.Position(c.Pos()).Line
				end := fc.fset.Position(c.End()).Line
				for l := start; l <= end; l++ {
					commentLines[l] = true
				}
			}
		}
	}
	count := 0
	for i, line := range lines {
		lineNo := i + 1
		if opts.skipComments && commentLines[lineNo] {
			continue
		}
		if opts.skipBlankLines && strings.TrimSpace(line) == "" {
			continue
		}
		count++
	}
	if int64(count) > opts.max {
		start := token.Position{Filename: fc.name, Offset: 0, Line: len(lines), Column: 0}
		return []failure{{
			Failure:    fmt.Sprintf("file length is %d lines, which exceeds the limit of %d", count, opts.max),
			Category:   "style",
			Position:   failurePosition{Start: start, End: token.Position{}},
			Confidence: 1,
		}}
	}
	return nil
}

// function-length
type funcLenOptions struct {
	maxStatements, maxLines int64
}

func configureFunctionLength(args []interface{}) (interface{}, error) {
	opts := &funcLenOptions{maxStatements: 50, maxLines: 75}
	if len(args) == 0 {
		return opts, nil
	}
	if len(args) != 2 {
		return nil, fmt.Errorf("invalid configuration for \"function-length\" rule, expected 2 arguments but got %d", len(args))
	}
	sv, ok := args[0].(int64)
	if !ok {
		return nil, fmt.Errorf("invalid configuration value for max statements in \"function-length\" rule; need int64 but got %s", typeName(args[0]))
	}
	lv, ok := args[1].(int64)
	if !ok {
		return nil, fmt.Errorf("invalid configuration value for max lines in \"function-length\" rule; need int64 but got %s", typeName(args[1]))
	}
	if sv < 0 {
		return nil, fmt.Errorf("the configuration value for max statements in \"function-length\" rule cannot be negative, got %d", sv)
	}
	if lv < 0 {
		return nil, fmt.Errorf("the configuration value for max statements in \"function-length\" rule cannot be negative, got %d", lv)
	}
	opts.maxStatements = sv
	opts.maxLines = lv
	return opts, nil
}

func ruleFunctionLength(fc *fileContext, optsI interface{}) []failure {
	opts, _ := optsI.(*funcLenOptions)
	if opts == nil {
		return nil
	}
	var out []failure
	for _, d := range fc.ast.Decls {
		fd, ok := d.(*ast.FuncDecl)
		if !ok || fd.Body == nil {
			continue
		}
		// lines: physical lines strictly between the line of '{' and line of '}'
		bodyStartLine := fc.fset.Position(fd.Body.Lbrace).Line
		bodyEndLine := fc.fset.Position(fd.Body.Rbrace).Line
		lines := bodyEndLine - bodyStartLine - 1
		if lines < 0 {
			lines = 0
		}
		stmts := 0
		ast.Inspect(fd.Body, func(n ast.Node) bool {
			if _, isStmt := n.(ast.Stmt); isStmt {
				if _, isBlock := n.(*ast.BlockStmt); !isBlock {
					stmts++
				}
			}
			return true
		})
		if opts.maxLines > 0 && int64(lines) > opts.maxLines {
			out = append(out, fc.nodeFailure(fd, fmt.Sprintf("maximum number of lines per function exceeded; max %d but got %d", opts.maxLines, lines), "", 1, ""))
		}
		if opts.maxStatements > 0 && int64(stmts) > opts.maxStatements {
			out = append(out, fc.nodeFailure(fd, fmt.Sprintf("maximum number of statements per function exceeded; max %d but got %d", opts.maxStatements, stmts), "", 1, ""))
		}
	}
	return out
}

// max-public-structs
func configureMaxPublicStructs(args []interface{}) (interface{}, error) {
	max := int64(5) // default will be verified; no-arg behaviour checked by tests
	if len(args) > 0 {
		v, ok := args[0].(int64)
		if !ok {
			return nil, fmt.Errorf("invalid value passed as argument number to the \"max-public-structs\" rule")
		}
		max = v
		return &max, nil
	}
	var p *int64
	return p, nil
}

func ruleMaxPublicStructs(fc *fileContext, optsI interface{}) []failure {
	p, _ := optsI.(*int64)
	if p == nil {
		// default: need to determine; use a large default checked separately
		// The reference with no arguments flags only above its default; placeholder default = 5?
		// We'll compute with defaultMaxPublicStructs.
		v := defaultMaxPublicStructs
		p = &v
	}
	count := 0
	for _, d := range fc.ast.Decls {
		gd, ok := d.(*ast.GenDecl)
		if !ok || gd.Tok != token.TYPE {
			continue
		}
		for _, spec := range gd.Specs {
			ts, ok := spec.(*ast.TypeSpec)
			if !ok {
				continue
			}
			if !isExportedName(ts.Name.Name) {
				continue
			}
			if _, isStruct := ts.Type.(*ast.StructType); isStruct {
				count++
			}
		}
	}
	if int64(count) > *p {
		return []failure{fc.nodeFailure(fc.ast, fmt.Sprintf("you have exceeded the maximum number (%d) of public struct declarations", *p), "style", 1, "")}
	}
	return nil
}

const defaultMaxPublicStructs = int64(5)

// cyclomatic
func configureCyclomatic(args []interface{}) (interface{}, error) {
	max := int64(10)
	if len(args) > 0 {
		v, ok := args[0].(int64)
		if !ok {
			return nil, fmt.Errorf("invalid argument for cyclomatic complexity; expected int but got %s", typeName(args[0]))
		}
		max = v
	}
	return max, nil
}

func funcDisplayName(fd *ast.FuncDecl) string {
	if fd.Recv != nil && len(fd.Recv.List) > 0 {
		rt := receiverTypeName(fd)
		// Determine pointer
		field := fd.Recv.List[0]
		if _, ok := field.Type.(*ast.StarExpr); ok {
			return fmt.Sprintf("(*%s).%s", rt, fd.Name.Name)
		}
		return fmt.Sprintf("(%s).%s", rt, fd.Name.Name)
	}
	return fd.Name.Name
}

func cyclomaticComplexity(body *ast.BlockStmt) int {
	complexity := 1
	ast.Inspect(body, func(n ast.Node) bool {
		switch node := n.(type) {
		case *ast.IfStmt, *ast.ForStmt, *ast.RangeStmt:
			complexity++
		case *ast.CaseClause:
			if node.List != nil {
				complexity++
			}
		case *ast.CommClause:
			if node.Comm != nil {
				complexity++
			}
		case *ast.BinaryExpr:
			if node.Op == token.LAND || node.Op == token.LOR {
				complexity++
			}
		}
		return true
	})
	return complexity
}

func ruleCyclomatic(fc *fileContext, optsI interface{}) []failure {
	max, _ := optsI.(int64)
	var out []failure
	for _, d := range fc.ast.Decls {
		fd, ok := d.(*ast.FuncDecl)
		if !ok || fd.Body == nil {
			continue
		}
		c := cyclomaticComplexity(fd.Body)
		if int64(c) > max {
			out = append(out, fc.nodeFailure(fd, fmt.Sprintf("function %s has cyclomatic complexity %d (> max enabled %d)", funcDisplayName(fd), c, max), "maintenance", 1, ""))
		}
	}
	return out
}

// cognitive complexity

func configureCognitive(args []interface{}) (interface{}, error) {
	max := int64(7)
	if len(args) > 0 {
		v, ok := args[0].(int64)
		if !ok {
			return nil, fmt.Errorf("invalid argument type for cognitive-complexity, expected int64, got %s", typeName(args[0]))
		}
		max = v
	}
	return max, nil
}

type cognitiveCalc struct {
	fc         *fileContext
	funcName   string
	complexity int
}

func (c *cognitiveCalc) visitNode(node ast.Node, nesting int) {
	if node == nil {
		return
	}
	switch n := node.(type) {
	case *ast.FuncLit:
		c.complexity += nesting
		for _, child := range childNodes(n) {
			c.visitNode(child, nesting+1)
		}
	case *ast.IfStmt:
		c.complexity += 1 + nesting
		// condition logical sequences
		c.visitExpr(n.Cond, nesting)
		if n.Init != nil {
			c.visitNode(n.Init, nesting)
		}
		c.visitNode(n.Body, nesting+1)
		if n.Else != nil {
			// else branch visited at same nesting as the if for its own structural increments:
			// an else-if is visited as an IfStmt at current nesting, an else block at nesting+1
			c.visitNode(n.Else, nesting)
		}
	case *ast.ForStmt:
		c.complexity += 1 + nesting
		if n.Init != nil {
			c.visitNode(n.Init, nesting)
		}
		if n.Cond != nil {
			c.visitExpr(n.Cond, nesting)
		}
		if n.Post != nil {
			c.visitNode(n.Post, nesting)
		}
		c.visitNode(n.Body, nesting+1)
	case *ast.RangeStmt:
		c.complexity += 1 + nesting
		c.visitExpr(n.X, nesting)
		if n.Key != nil {
			c.visitExpr(n.Key, nesting)
		}
		if n.Value != nil {
			c.visitExpr(n.Value, nesting)
		}
		c.visitNode(n.Body, nesting+1)
	case *ast.SwitchStmt:
		c.complexity += 1 + nesting
		for _, child := range childNodes(n) {
			// body children at nesting+1, tag/init at nesting
			if child == ast.Node(n.Body) {
				c.visitNode(child, nesting+1)
			} else {
				c.visitNode(child, nesting)
			}
		}
	case *ast.TypeSwitchStmt:
		c.complexity += 1 + nesting
		for _, child := range childNodes(n) {
			if child == ast.Node(n.Body) {
				c.visitNode(child, nesting+1)
			} else {
				c.visitNode(child, nesting)
			}
		}
	case *ast.SelectStmt:
		c.complexity += 1 + nesting
		c.visitNode(n.Body, nesting+1)
	case *ast.BranchStmt:
		if n.Label != nil && (n.Tok == token.BREAK || n.Tok == token.CONTINUE) {
			c.complexity++
		} else if n.Tok == token.GOTO {
			c.complexity++
		}
	case *ast.CallExpr:
		if id, ok := n.Fun.(*ast.Ident); ok && id.Name == c.funcName {
			c.complexity++
		}
		for _, child := range childNodes(n) {
			c.visitNode(child, nesting)
		}
	case *ast.BinaryExpr:
		if n.Op == token.LAND || n.Op == token.LOR {
			c.complexity += countLogicalSequences(n)
			// visit operands but avoid recounting sub-logical: visit non-logical subparts via visitExpr on leaves
			leafExprs := logicalLeaves(n)
			for _, leaf := range leafExprs {
				c.visitNode(leaf, nesting)
			}
		} else {
			for _, child := range childNodes(n) {
				c.visitNode(child, nesting)
			}
		}
	default:
		for _, child := range childNodes(node) {
			c.visitNode(child, nesting)
		}
	}
}

func (c *cognitiveCalc) visitExpr(expr ast.Expr, nesting int) {
	if expr != nil {
		c.visitNode(expr, nesting)
	}
}

func countLogicalSequences(expr ast.Expr) int {
	var ops []token.Token
	var collect func(e ast.Expr)
	collect = func(e ast.Expr) {
		switch be := e.(type) {
		case *ast.BinaryExpr:
			if be.Op == token.LAND || be.Op == token.LOR {
				collect(be.X)
				ops = append(ops, be.Op)
				collect(be.Y)
			}
		case *ast.ParenExpr:
			collect(be.X)
		}
	}
	collect(expr)
	if len(ops) == 0 {
		return 0
	}
	seq := 1
	for i := 1; i < len(ops); i++ {
		if ops[i] != ops[i-1] {
			seq++
		}
	}
	return seq
}

func logicalLeaves(expr ast.Expr) []ast.Expr {
	var leaves []ast.Expr
	var collect func(e ast.Expr)
	collect = func(e ast.Expr) {
		switch be := e.(type) {
		case *ast.BinaryExpr:
			if be.Op == token.LAND || be.Op == token.LOR {
				collect(be.X)
				collect(be.Y)
				return
			}
			leaves = append(leaves, e)
		case *ast.ParenExpr:
			collect(be.X)
		default:
			leaves = append(leaves, e)
		}
	}
	collect(expr)
	return leaves
}

func ruleCognitive(fc *fileContext, optsI interface{}) []failure {
	max, _ := optsI.(int64)
	var out []failure
	for _, d := range fc.ast.Decls {
		fd, ok := d.(*ast.FuncDecl)
		if !ok || fd.Body == nil {
			continue
		}
		calc := &cognitiveCalc{fc: fc, funcName: fd.Name.Name}
		for _, stmt := range fd.Body.List {
			calc.visitNode(stmt, 0)
		}
		if int64(calc.complexity) > max {
			out = append(out, fc.nodeFailure(fd, fmt.Sprintf("function %s has cognitive complexity %d (> max enabled %d)", funcDisplayName(fd), calc.complexity, max), "maintenance", 1, ""))
		}
	}
	return out
}

// max-control-nesting
func configureMaxControlNesting(args []interface{}) (interface{}, error) {
	max := int64(5)
	if len(args) > 0 {
		v, ok := args[0].(int64)
		if !ok {
			return nil, fmt.Errorf("invalid value passed as argument number to the \"max-control-nesting\" rule")
		}
		max = v
	}
	return max, nil
}

func ruleMaxControlNesting(fc *fileContext, optsI interface{}) []failure {
	max, _ := optsI.(int64)
	var out []failure
	var visit func(node ast.Node, depth int64)
	visit = func(node ast.Node, depth int64) {
		if node == nil {
			return
		}
		switch n := node.(type) {
		case *ast.FuncLit:
			// reset depth
			if n.Body != nil {
				for _, stmt := range n.Body.List {
					visit(stmt, 0)
				}
			}
			return
		case *ast.IfStmt, *ast.ForStmt, *ast.SwitchStmt, *ast.TypeSwitchStmt, *ast.SelectStmt:
			nd := depth + 1
			if nd > max {
				out = append(out, fc.nodeFailure(node, fmt.Sprintf("control flow nesting exceeds %d", max), "complexity", 1, ""))
				return
			}
			for _, child := range childNodes(node) {
				visit(child, nd)
			}
			return
		}
		for _, child := range childNodes(node) {
			visit(child, depth)
		}
	}
	for _, d := range fc.ast.Decls {
		if fd, ok := d.(*ast.FuncDecl); ok {
			if max < 0 {
				out = append(out, failure{
					Failure:    fmt.Sprintf("control flow nesting exceeds %d", max),
					Category:   "complexity",
					Position:   failurePosition{Start: token.Position{}, End: token.Position{}},
					Confidence: 1,
				})
				continue
			}
			if fd.Body != nil {
				for _, stmt := range fd.Body.List {
					visit(stmt, 0)
				}
			}
		}
	}
	return out
}
