func findGoVersion(dir string, filenames []string) string {
	start := dir
	if start == "" && len(filenames) > 0 {
		start = pathDir(filenames[0])
	}
	abs, err := filepathAbs(start)
	if err != nil {
		abs = start
	}
	for {
		gomod := abs + string(byte(47)) + "go.mod"
		if data, err := osReadFile(gomod); err == nil {
