func goVersionAtLeast(version string, major int, minor int) bool {
	if version == "" {
		return false
	}
	parts := strings.Split(version, ".")
	if len(parts) < 2 {
		return false
	}
	parseInt := func(s string) int {
		n := 0
		for i := 0; i < len(s); i++ {
			if s[i] < '0' || s[i] > '9' {
				break
			}
			n = n*10 + int(s[i]-'0')
		}
		return n
	}
	maj := parseInt(parts[0])
	min := parseInt(parts[1])
	if maj != major {
		return maj > major
	}
	return min >= minor
}

