package main

import (
	"fmt"
	"go/ast"
	"go/token"
	"go/types"
	"regexp"
	"strings"
)

func init() {
	registerRule("atomic", nil, ruleAtomic)
	registerRule("datarace", nil, ruleDatarace)
	registerRule("defer", configureDefer, ruleDefer)
	registerRule("modifies-value-receiver", nil, ruleModifiesValueReceiver)
