		// LHS denotes the same location as first argument?
		first := call.Args[0]
		lhs := as.Lhs[0]
		same := false
		// x = atomic.Add(&x, ...)
		if u, ok := first.(*ast.UnaryExpr); ok && u.Op == token.AND {
			if equalExpr(fc, lhs, u.X) {
				same = true
			}
		}
		// *p = atomic.Add(p, ...)
		if star, ok := lhs.(*ast.StarExpr); ok {
			if equalExpr(fc, star.X, first) {
				same = true
			}
		}
		if same {
			out = append(out, fc.nodeFailure(as, "direct assignment to atomic value", "", 1, ""))
		}
		return true
	})
	return out
}

func ruleWaitgroupByValue(fc *fileContext, _ interface{}) []failure {
	var out []failure
	isWG := func(expr ast.Expr) bool {
		if t := fc.typeOf(expr); t != nil {
			if named, ok := t.(*types.Named); ok && named.Obj() != nil {
				return named.Obj().Name() == "WaitGroup" && named.Obj().Pkg() != nil && named.Obj().Pkg().Path() == "sync"
			}
		}
		sel, ok := expr.(*ast.SelectorExpr)
		if !ok || sel.Sel.Name != "WaitGroup" {
			return false
		}
		id, ok := sel.X.(*ast.Ident)
		return ok && fc.importNameForPath("sync") == id.Name
	}
	for _, d := range fc.ast.Decls {
		fd, ok := d.(*ast.FuncDecl)
		if !ok || fd.Type.Params == nil {
			continue
		}
		for _, field := range fd.Type.Params.List {
			if isWG(field.Type) {
				out = append(out, fc.nodeFailure(field, "sync.WaitGroup passed by value, the function will get a copy of the original one", "", 1, ""))
			}
		}
	}
	return out
}

// defer

type deferOptions struct{ enabled map[string]bool }

func configureDefer(args []interface{}) (interface{}, error) {
	opts := &deferOptions{enabled: map[string]bool{"loop": true, "immediate-recover": true, "call-chain": true}}
	if len(args) == 0 {
		return opts, nil
	}
	list, ok := args[0].([]interface{})
	if !ok {
		return nil, fmt.Errorf("invalid argument '%v' for 'defer' rule. Expecting []string, got %s", args[0], typeName(args[0]))
	}
	opts.enabled = map[string]bool{}
	for _, e := range list {
		s, ok := e.(string)
		if !ok {
			return nil, fmt.Errorf("invalid argument '%v' for 'defer' rule. Expecting string, got %s", e, typeName(e))
		}
		opts.enabled[s] = true
	}
	return opts, nil
}

func ruleDefer(fc *fileContext, optsI interface{}) []failure {
	opts, _ := optsI.(*deferOptions)
	if opts == nil {
		opts = &deferOptions{enabled: map[string]bool{"loop": true, "immediate-recover": true, "call-chain": true}}
	}
	var out []failure
	var visit func(node ast.Node, inLoop bool)
	visit = func(node ast.Node, inLoop bool) {
		if node == nil {
			return
		}
		switch n := node.(type) {
		case *ast.FuncLit:
			if n.Body != nil {
				for _, stmt := range n.Body.List {
					visit(stmt, false)
				}
			}
			return
		case *ast.ForStmt:
			if n.Init != nil {
				visit(n.Init, inLoop)
			}
			if n.Cond != nil {
				visit(n.Cond, inLoop)
			}
			if n.Post != nil {
				visit(n.Post, inLoop)
			}
			visit(n.Body, true)
			return
		case *ast.RangeStmt:
			visit(n.X, inLoop)
			visit(n.Body, true)
			return
		case *ast.DeferStmt:
			if opts.enabled["loop"] && inLoop {
				out = append(out, fc.nodeFailure(n, "prefer not to defer inside loops", "bad practice", 1, ""))
			}
			if n.Call != nil {
				if opts.enabled["immediate-recover"] {
					if id, ok := n.Call.Fun.(*ast.Ident); ok && id.Name == "recover" {
						if obj := functionObject(fc, id); obj == nil || obj.Parent() == types.Universe {
							out = append(out, fc.nodeFailure(n, "recover must be called inside a deferred function, this is executing recover immediately", "logic", 1, ""))
						}
					}
				}
				if opts.enabled["call-chain"] {
					if inner, ok := n.Call.Fun.(*ast.CallExpr); ok {
						out = append(out, fc.nodeFailure(inner, "prefer not to defer chains of function calls", "bad practice", 1, ""))
					}
				}
				// continue visiting arguments / nested literals with same inLoop status for literals reset in their case
				visit(n.Call, inLoop)
			}
			return
		}
		for _, child := range childNodes(node) {
			visit(child, inLoop)
		}
	}
	for _, d := range fc.ast.Decls {
		visit(d, false)
	}
	return out
}

func functionObject(fc *fileContext, id *ast.Ident) types.Object {
	if fc.types == nil {
		return nil
	}
	return fc.types.Uses[id]
}

func ruleModifiesValueReceiver(fc *fileContext, _ interface{}) []failure {
	var out []failure
	for _, d := range fc.ast.Decls {
		fd, ok := d.(*ast.FuncDecl)
		if !ok || fd.Recv == nil || len(fd.Recv.List) == 0 || fd.Body == nil {
			continue
		}
		field := fd.Recv.List[0]
		if len(field.Names) == 0 {
			continue
		}
		if _, isStar := field.Type.(*ast.StarExpr); isStar {
			continue
		}
		recvName := field.Names[0].Name
		recvObj := objectForIdent(fc, field.Names[0])
		ast.Inspect(fd.Body, func(n ast.Node) bool {
			switch node := n.(type) {
			case *ast.AssignStmt:
				for _, lhs := range node.Lhs {
					if isReceiverRootAssign(fc, lhs, recvName, recvObj) {
						out = append(out, fc.nodeFailure(node, "suspicious assignment to a by-value method receiver", "", 1, ""))
						break
					}
				}
			case *ast.IncDecStmt:
				if isReceiverRootAssign(fc, node.X, recvName, recvObj) {
					out = append(out, fc.nodeFailure(node, "suspicious assignment to a by-value method receiver", "", 1, ""))
				}
			}
			return true
		})
	}
	return out
}

func isReceiverRootAssign(fc *fileContext, expr ast.Expr, recvName string, recvObj types.Object) bool {
	switch e := expr.(type) {
	case *ast.Ident:
		return e.Name == recvName && (recvObj == nil || objectForIdent(fc, e) == recvObj)
	case *ast.SelectorExpr:
		// only a direct field of the receiver counts (t.x)
		if id, ok := e.X.(*ast.Ident); ok {
			return id.Name == recvName && (recvObj == nil || objectForIdent(fc, id) == recvObj)
		}
		return false
	}
	return false
}

// Range loop helpers

type rangeVar struct {
	ident *ast.Ident
	obj   types.Object
}

func rangeVars(fc *fileContext, rs *ast.RangeStmt) (key *rangeVar, value *rangeVar) {
	if id, ok := rs.Key.(*ast.Ident); ok && id.Name != "_" {
		key = &rangeVar{ident: id, obj: objectForIdent(fc, id)}
	}
	if id, ok := rs.Value.(*ast.Ident); ok && id.Name != "_" {
		value = &rangeVar{ident: id, obj: objectForIdent(fc, id)}
	}
	return
}

func isRangeVarUse(fc *fileContext, id *ast.Ident, rv *rangeVar) bool {
	if rv == nil {
		return false
	}
	if rv.obj != nil {
		return objectForIdent(fc, id) == rv.obj
	}
	return id.Name == rv.ident.Name
}

func ruleRangeValAddress(fc *fileContext, _ interface{}) []failure {
	if fc.goVersionAtLeast122() {
		return nil
	}
	var out []failure
	// Need parent tracking for unary &value.
	ast.Inspect(fc.ast, func(n ast.Node) bool {
		rs, ok := n.(*ast.RangeStmt)
		if !ok {
			return true
		}
		_, value := rangeVars(fc, rs)
		if value == nil {
			return true
		}
		// walk body with parent stack
		var stack []ast.Node
		ast.Inspect(rs.Body, func(node ast.Node) bool {
			if node == nil {
				stack = stack[:len(stack)-1]
				return true
			}
			if u, ok := node.(*ast.UnaryExpr); ok && u.Op == token.AND {
				if id, ok := u.X.(*ast.Ident); ok && isRangeVarUse(fc, id, value) {
					if len(stack) > 0 {
						switch stack[len(stack)-1].(type) {
						case *ast.AssignStmt, *ast.CompositeLit, *ast.ReturnStmt:
							out = append(out, fc.nodeFailure(u, fmt.Sprintf("suspicious assignment of '%s'. range-loop variables always have the same address", id.Name), "", 1, ""))
						}
					}
				}
			}
			stack = append(stack, node)
			return true
		})
		return true
	})
	return out
}

func collectCapturesInGoDefer(fc *fileContext, body ast.Node, vars []*rangeVar, goroutineOnly bool, out *[]failure, msgFor func(name string) (string, string)) {
	seenPos := map[token.Pos]bool{}
	var checkLit func(lit *ast.FuncLit)
	checkUses := func(node ast.Node) {
		ast.Inspect(node, func(n ast.Node) bool {
			id, ok := n.(*ast.Ident)
			if !ok {
				return true
			}
			for _, rv := range vars {
				if isRangeVarUse(fc, id, rv) {
					if seenPos[id.Pos()] {
						return true
					}
					seenPos[id.Pos()] = true
					msg, cat := msgFor(id.Name)
					*out = append(*out, fc.nodeFailure(id, msg, cat, 1, ""))
				}
			}
			return true
		})
	}
	checkLit = func(lit *ast.FuncLit) {
		if lit.Body != nil {
			checkUses(lit.Body)
		}
	}
	ast.Inspect(body, func(n ast.Node) bool {
		switch node := n.(type) {
		case *ast.GoStmt:
			if node.Call != nil {
				if lit, ok := node.Call.Fun.(*ast.FuncLit); ok {
					checkLit(lit)
				}
			}
			return true
		case *ast.DeferStmt:
			if goroutineOnly {
				return true
			}
			if node.Call != nil {
				if lit, ok := node.Call.Fun.(*ast.FuncLit); ok {
					checkLit(lit)
				}
			}
			return true
		case *ast.RangeStmt:
			// nested ranges are handled by the outer ast.Inspect in callers (they re-enter),
			// but within a single range body walk, still descend.
			return true
		}
		return true
	})
	_ = checkLit
}

func ruleRangeValInClosure(fc *fileContext, _ interface{}) []failure {
	if fc.goVersionAtLeast122() {
		return nil
	}
	var out []failure
	ast.Inspect(fc.ast, func(n ast.Node) bool {
		rs, ok := n.(*ast.RangeStmt)
		if !ok {
			return true
		}
		key, value := rangeVars(fc, rs)
		var vars []*rangeVar
		if key != nil {
			vars = append(vars, key)
		}
		if value != nil {
			vars = append(vars, value)
		}
		if len(vars) == 0 {
			return true
		}
		collectCapturesInGoDefer(fc, rs.Body, vars, false, &out, func(name string) (string, string) {
			return fmt.Sprintf("loop variable %s captured by func literal", name), ""
		})
		return true
	})
	return out
}

func ruleDatarace(fc *fileContext, _ interface{}) []failure {
	if fc.goVersionAtLeast122() {
		return nil
	}
	var out []failure
	ast.Inspect(fc.ast, func(n ast.Node) bool {
		rs, ok := n.(*ast.RangeStmt)
		if !ok {
			return true
		}
		key, value := rangeVars(fc, rs)
		var vars []*rangeVar
		if key != nil {
			vars = append(vars, key)
		}
		if value != nil {
			vars = append(vars, value)
		}
		if len(vars) == 0 {
			return true
		}
		collectCapturesInGoDefer(fc, rs.Body, vars, true, &out, func(name string) (string, string) {
			return fmt.Sprintf("datarace: range value %s is captured (by-reference) in goroutine", name), "logic"
		})
		return true
	})
	return out
}

// unchecked-type-assertion

type uncheckedOptions struct{ acceptIgnored bool }

func configureUncheckedAssertion(args []interface{}) (interface{}, error) {
	opts := &uncheckedOptions{}
	if len(args) == 0 {
		return opts, nil
	}
	m, ok := args[0].(map[string]interface{})
	if !ok {
		return nil, fmt.Errorf("unable to get arguments. Expected object of key-value-pairs")
	}
	for k, v := range m {
		if k != "acceptIgnoredAssertionResult" {
			return nil, fmt.Errorf("unknown argument: %s", k)
		}
		b, ok := v.(bool)
		if !ok {
			return nil, fmt.Errorf("unable to parse argument 'acceptIgnoredAssertionResult'. Expected boolean")
		}
		opts.acceptIgnored = b
	}
	return opts, nil
}

func ruleUncheckedAssertion(fc *fileContext, optsI interface{}) []failure {
	opts, _ := optsI.(*uncheckedOptions)
	if opts == nil {
		opts = &uncheckedOptions{}
	}
	// Find which type assertions are in the comma-ok position of an assignment.
	type assertInfo struct {
		commaOK bool // assignment has 2 LHS whose 2nd is not blank
		ignored bool // 2 LHS, 2nd is blank
	}
	infos := map[*ast.TypeAssertExpr]assertInfo{}
	unwrap := func(e ast.Expr) ast.Expr {
		for {
			if p, ok := e.(*ast.ParenExpr); ok {
				e = p.X
			} else {
				return e
			}
		}
	}
	ast.Inspect(fc.ast, func(n ast.Node) bool {
		as, ok := n.(*ast.AssignStmt)
		if !ok || len(as.Rhs) != 1 || len(as.Lhs) != 2 {
			return true
		}
		if ta, ok := unwrap(as.Rhs[0]).(*ast.TypeAssertExpr); ok {
			ignored := isIdentName(as.Lhs[1], "_")
			infos[ta] = assertInfo{commaOK: !ignored, ignored: ignored}
		}
		return true
	})
	var out []failure
	ast.Inspect(fc.ast, func(n ast.Node) bool {
		ta, ok := n.(*ast.TypeAssertExpr)
		if !ok || ta.Type == nil {
			return true
		}
		if info, present := infos[ta]; present {
			if info.commaOK {
				return true
			}
			if info.ignored {
				if opts.acceptIgnored {
					return true
				}
				out = append(out, fc.nodeFailure(ta, fmt.Sprintf("type cast result is unchecked in %s - type assertion result ignored", fc.nodeString(ta)), "bad practice", 1, ""))
				return true
			}
		}
		out = append(out, fc.nodeFailure(ta, fmt.Sprintf("type cast result is unchecked in %s - type assertion will panic if not matched", fc.nodeString(ta)), "bad practice", 1, ""))
		return true
	})
	return out
}

// unused-receiver (shares unused-param style option parsing but with slightly different errors)

func configureUnusedReceiver(args []interface{}) (interface{}, error) {
	opts := &unusedParamOptions{}
	if len(args) == 0 {
		return opts, nil
	}
	m, ok := args[0].(map[string]interface{})
	if !ok {
		return opts, nil
	}
	if v, present := m["allowRegex"]; present {
		s, ok := v.(string)
		if !ok {
			return nil, fmt.Errorf("error configuring [unused-receiver] rule: allowRegex is not string but [%s]", typeName(v))
		}
		re, err := regexp.Compile(s)
		if err != nil {
			return nil, fmt.Errorf("error configuring [unused-receiver] rule: allowRegex is not valid regex [%s]: %s", s, err.Error())
		}
		opts.allowRegex = s
		opts.allowRegexCmp = re
	}
	return opts, nil
}

func ruleUnusedReceiver(fc *fileContext, optsI interface{}) []failure {
	opts, _ := optsI.(*unusedParamOptions)
	if opts == nil {
		opts = &unusedParamOptions{}
	}
	var out []failure
	for _, d := range fc.ast.Decls {
		fd, ok := d.(*ast.FuncDecl)
		if !ok || fd.Recv == nil || len(fd.Recv.List) == 0 || fd.Body == nil {
			continue
		}
		field := fd.Recv.List[0]
		if len(field.Names) == 0 {
			continue
		}
		name := field.Names[0]
		if name.Name == "_" {
			continue
		}
		if opts.allowRegexCmp != nil && opts.allowRegexCmp.MatchString(name.Name) {
			continue
		}
		if isParamUsed(fc, name, fd.Body) {
			continue
		}
		var msg string
		if opts.allowRegex != "" {
			msg = fmt.Sprintf("method receiver '%s' is not referenced in method's body, consider removing or renaming it to match %s", name.Name, opts.allowRegex)
		} else {
			msg = fmt.Sprintf("method receiver '%s' is not referenced in method's body, consider removing or renaming it as _", name.Name)
		}
		out = append(out, fc.nodeFailure(name, msg, "bad practice", 1, ""))
	}
	return out
}
