package main

import (
	"fmt"
	"go/ast"
	"go/token"
	"strconv"
	"strings"
)

func init() {
	registerRule("banned-characters", configureBannedChars, ruleBannedChars)
	registerRule("empty-lines", nil, ruleEmptyLines)
	registerRule("redundant-build-tag", nil, ruleRedundantBuildTag)
	registerRule("redundant-test-main-exit", nil, ruleRedundantTestMainExit)
	registerRule("unsecure-url-scheme", nil, ruleUnsecureURLScheme)
}

func configureBannedChars(args []interface{}) (interface{}, error) {
	var banned []string
	for _, arg := range args {
		s, ok := arg.(string)
		if !ok {
			return nil, fmt.Errorf("invalid argument for the banned-characters rule: expecting a string, got %s", typeName(arg))
		}
		banned = append(banned, s)
	}
	return banned, nil
}

func ruleBannedChars(fc *fileContext, optsI interface{}) []failure {
	banned, _ := optsI.([]string)
	var out []failure
	ast.Inspect(fc.ast, func(n ast.Node) bool {
		id, ok := n.(*ast.Ident)
		if !ok {
			return true
		}
		for _, b := range banned {
			if strings.Contains(id.Name, b) {
				out = append(out, fc.nodeFailure(id, fmt.Sprintf("banned character found: %s", b), "", 1, ""))
			}
		}
		return true
	})
	return out
}

func ruleEmptyLines(fc *fileContext, _ interface{}) []failure {
	lines := physicalLines(fc.content)
	isBlank := func(line int) bool {
		if line < 1 || line > len(lines) {
			return false
		}
		return strings.TrimSpace(lines[line-1]) == ""
	}
	var out []failure
	ast.Inspect(fc.ast, func(n ast.Node) bool {
		block, ok := n.(*ast.BlockStmt)
		if !ok || len(block.List) == 0 {
			return true
		}
		openLine := fc.fset.Position(block.Lbrace).Line
		closeLine := fc.fset.Position(block.Rbrace).Line
		if closeLine > openLine {
			if isBlank(openLine + 1) {
				out = append(out, fc.nodeFailure(block, "extra empty line at the start of a block", "style", 1, ""))
			}
			if isBlank(closeLine - 1) {
				out = append(out, fc.nodeFailure(block, "extra empty line at the end of a block", "style", 1, ""))
			}
		}
		return true
	})
	// Reference order emits end before start in some sort orders; our collection order (start then end)
	// is acceptable for sorted-output tests, and NDJSON order would differ.
	// To match NDJSON ordering observed in references, re-order so that for each block end precedes start
	// is not possible after flattening; keep start-then-end.
	return out
}

func ruleUnsecureURLScheme(fc *fileContext, _ interface{}) []failure {
	var out []failure
	ast.Inspect(fc.ast, func(n ast.Node) bool {
		lit, ok := n.(*ast.BasicLit)
		if !ok || lit.Kind != token.STRING {
			return true
		}
		s, err := strconv.Unquote(lit.Value)
		if err != nil {
			return true
		}
		if !strings.HasPrefix(s, "http://") || s == "http://" {
			return true
		}
		for _, safe := range []string{"localhost", "127.0.0.1", "0.0.0.0"} {
			if strings.Contains(s, safe) {
				return true
			}
		}
		out = append(out, fc.nodeFailure(lit, fmt.Sprintf("prefer secure protocol https over http in %s", lit.Value), "", 1, ""))
		return true
	})
	return out
}

func ruleRedundantBuildTag(fc *fileContext, _ interface{}) []failure {
	var out []failure
	for _, group := range fc.comments {
		prevGoBuild := false
		for _, c := range group.List {
			if prevGoBuild && strings.HasPrefix(c.Text, "// +build") {
				out = append(out, fc.nodeFailure(c, "The build tag \"// +build\" is redundant since Go 1.17 and can be removed", "style", 1, ""))
			}
			prevGoBuild = strings.HasPrefix(c.Text, "//go:build")
		}
	}
	return out
}

func ruleRedundantTestMainExit(fc *fileContext, _ interface{}) []failure {
	if !fc.isTest {
		return nil
	}
	var out []failure
	for _, d := range fc.ast.Decls {
		fd, ok := d.(*ast.FuncDecl)
		if !ok || fd.Name.Name != "TestMain" || fd.Recv != nil || fd.Body == nil {
			continue
		}
		// name of the *testing.M parameter
		mName := ""
		if fd.Type.Params != nil {
			for _, f := range fd.Type.Params.List {
				if len(f.Names) > 0 {
					mName = f.Names[0].Name
					break
				}
			}
		}
		isRunCall := func(expr ast.Expr) bool {
			call, ok := expr.(*ast.CallExpr)
			if !ok {
				return false
			}
			sel, ok := call.Fun.(*ast.SelectorExpr)
			if !ok || sel.Sel.Name != "Run" {
				return false
			}
			if id, ok := sel.X.(*ast.Ident); ok {
				return mName == "" || id.Name == mName
			}
			return false
		}
		runVars := map[string]bool{}
		ast.Inspect(fd.Body, func(n ast.Node) bool {
			if as, ok := n.(*ast.AssignStmt); ok {
				for i, rhs := range as.Rhs {
					if i < len(as.Lhs) && isRunCall(rhs) {
						if id, ok := as.Lhs[i].(*ast.Ident); ok {
							runVars[id.Name] = true
						}
					}
				}
			}
			return true
		})
		ast.Inspect(fd.Body, func(n ast.Node) bool {
			call, ok := n.(*ast.CallExpr)
			if !ok || !fc.isCallTo(call, "os", "Exit") || len(call.Args) != 1 {
				return true
			}
			arg := call.Args[0]
			if isRunCall(arg) {
				out = append(out, fc.nodeFailure(call, "redundant call to os.Exit in TestMain function, the test runner will handle it automatically as of Go 1.15", "style", 1, ""))
			} else if id, ok := arg.(*ast.Ident); ok && runVars[id.Name] {
				out = append(out, fc.nodeFailure(call, "redundant call to os.Exit in TestMain function, the test runner will handle it automatically as of Go 1.15", "style", 1, ""))
			}
			return true
		})
	}
	return out
}
