func ruleUnsecureURLScheme(fc *fileContext, _ interface{}) []failure {
	var out []failure
	ast.Inspect(fc.ast, func(n ast.Node) bool {
		lit, ok := n.(*ast.BasicLit)
		if !ok || lit.Kind != token.STRING {
			return true
		}
		s, err := strconv.Unquote(lit.Value)
		if err != nil {
			return true
		}
		if !strings.HasPrefix(s, "http://") || s == "http://" {
			return true
		}
		for _, safe := range []string{"localhost", "127.0.0.1", "0.0.0.0"} {
			if strings.Contains(s, safe) {
				return true
			}
		}
		out = append(out, fc.nodeFailure(lit, fmt.Sprintf("prefer secure protocol https over http in %s", lit.Value), "", 1, ""))
		return true
	})
	return out
}

