{"command":"cat > /workspace/rules_batch_f.go <<'EOF'
package main

import (
	"fmt"
	"go/ast"
	"go/constant"
	"go/token"
	"go/types"
	"strconv"
	"strings"
	"time"
)

func init() {
	registerRule("epoch-naming", nil, ruleEpochNaming)
	registerRule("import-shadowing", nil, ruleImportShadowing)
	registerRule("struct-tag", configureStructTag, ruleStructTag)
	registerRule("time-date", nil, ruleTimeDate)
	registerRule("unconditional-recursion", nil, ruleUnconditionalRecursion)
	registerRule("unhandled-error", configureUnhandledError, ruleUnhandledError)
}

// ---- epoch-naming ----

var epochSuffixes = map[string][]string{
	"Unix":      {"Sec", "Second", "Seconds"},
	"UnixMilli": {"Milli", "Ms"},
	"UnixMicro": {"Micro", "Microsecond", "Microseconds", "Us"},
	"UnixNano":  {"Nano", "Ns"},
}

func (fc *fileContext) isTimeTimeType(t types.Type) bool {
	if t == nil {
		return false
	}
	if ptr, ok := t.(*types.Pointer); ok {
		t = ptr.Elem()
	}
	named, ok := t.(*types.Named)
	if !ok || named.Obj() == nil {
		return false
	}
	return named.Obj().Name() == "Time" && named.Obj().Pkg() != nil && named.Obj().Pkg().Path() == "time"
}

func ruleEpochNaming(fc *fileContext, _ interface{}) []failure {
	var out []failure
	checkPair := func(name *ast.Ident, rhs ast.Expr) {
		if name == nil || name.Name == "_" {
			return
		}
		call, ok := rhs.(*ast.CallExpr)
		if !ok {
			return
		}
		sel, ok := call.Fun.(*ast.SelectorExpr)
		if !ok {
			return
		}
		suffixes, ok := epochSuffixes[sel.Sel.Name]
		if !ok {
			return
		}
		if !fc.isTimeTimeType(fc.typeOf(sel.X)) {
			return
		}
		for _, suf := range suffixes {
			if strings.HasSuffix(strings.ToLower(name.Name), strings.ToLower(suf)) {
				return
			}
		}
		out = append(out, fc.nodeFailure(name, fmt.Sprintf("var %s should have one of these suffixes: %s", name.Name, strings.Join(suffixes, ", ")), "naming", 0.9, ""))
	}
	ast.Inspect(fc.ast, func(n ast.Node) bool {
		switch node := n.(type) {
		case *ast.AssignStmt:
			if node.Tok == token.DEFINE {
				for i, lhs := range node.Lhs {
					if id, ok := lhs.(*ast.Ident); ok && i < len(node.Rhs) {
						checkPair(id, node.Rhs[i])
					}
				}
			}
		case *ast.ValueSpec:
			for i, name := range node.Names {
				if i < len(node.Values) {
					checkPair(name, node.Values[i])
				}
			}
		}
		return true
	})
	return out
}

// ---- import-shadowing ----

func ruleImportShadowing(fc *fileContext, _ interface{}) []failure {
	importNames := map[string]bool{}
	for _, spec := range fc.ast.Imports {
		path := strings.Trim(spec.Path.Value, "\"`")
		var local string
		if spec.Name != nil {
			local = spec.Name.Name
		} else {
			// Derive package name from imported package object if possible, else last element.
			local = path
			if i := strings.LastIndex(path, "/"); i >= 0 {
				local = path[i+1:]
			}
			// Use type info: find a PkgName object for this path in Uses/Defs is not directly keyed;
			// package clause objects are in fc.types by ident in the file scope, but simplest: try types imports of the checked package
			if fc.typesPkg != nil {
				for _, imp := range fc.typesPkg.Imports() {
					if imp.Path() == path {
						local = imp.Name()
						break
					}
				}
			}
		}
		if local != "" && local != "_" && local != "." {
			importNames[local] = true
		}
	}
	if len(importNames) == 0 {
		return nil
	}
	var out []failure
	// Check declarations in inner scopes: parameters, short vars, local specs, receivers?, named results.
	checkIdent := func(id *ast.Ident) {
		if id != nil && importNames[id.Name] {
			out = append(out, fc.nodeFailure(id, fmt.Sprintf("The name '%s' shadows an import name", id.Name), "naming", 1, ""))
		}
	}
	ast.Inspect(fc.ast, func(n ast.Node) bool {
		switch node := n.(type) {
		case *ast.FuncDecl:
			// parameters and results only (not receiver, to approximate reference)
			for _, f := range fieldListNames(node.Type.Params) {
				checkIdent(f.ident)
			}
			for _, f := range fieldListNames(node.Type.Results) {
				checkIdent(f.ident)
			}
		case *ast.FuncLit:
			for _, f := range fieldListNames(node.Type.Params) {
				checkIdent(f.ident)
			}
			for _, f := range fieldListNames(node.Type.Results) {
				checkIdent(f.ident)
			}
		case *ast.AssignStmt:
			if node.Tok == token.DEFINE {
				for _, lhs := range node.Lhs {
					if id, ok := lhs.(*ast.Ident); ok {
						if fc.types == nil || fc.types.Defs[id] != nil {
							checkIdent(id)
						}
					}
				}
			}
		case *ast.GenDecl:
			// Only local declarations shadow imports; top-level declarations are in package scope,
			// but GenDecls inside functions are visited here as well as top level. Distinguish by
			// checking if this GenDecl is a top-level decl.
		}
		return true
	})
	// Local GenDecls inside function bodies
	for _, d := range fc.ast.Decls {
		fd, ok := d.(*ast.FuncDecl)
		if !ok || fd.Body == nil {
			continue
		}
		ast.Inspect(fd.Body, func(n ast.Node) bool {
			if gd, ok := n.(*ast.GenDecl); ok && gd.Tok != token.IMPORT {
				for _, spec := range gd.Specs {
					switch s := spec.(type) {
					case *ast.ValueSpec:
						for _, name := range s.Names {
							checkIdent(name)
						}
					case *ast.TypeSpec:
						checkIdent(s.Name)
					}
				}
			}
			return true
		})
	}
	return out
}

// ---- time-date ----

func constIntValue(fc *fileContext, expr ast.Expr) (int64, bool) {
	if fc.types != nil {
		if tv, ok := fc.types.Types[expr]; ok && tv.Value != nil {
			if tv.Value.Kind() == constant.Int {
				if v, ok := constant.Val(tv.Value).(int64); ok {
					return v, true
				}
				if s := tv.Value.String(); s != "" {
					if n, err := strconv.ParseInt(s, 10, 64); err == nil {
						return n, true
					}
				}
			}
		}
	}
	// Literal fallback
	switch e := expr.(type) {
	case *ast.BasicLit:
		if e.Kind == token.INT {
			n, err := strconv.ParseInt(strings.ReplaceAll(e.Value, "_", ""), 0, 64)
			return n, err == nil
		}
	case *ast.UnaryExpr:
		if e.Op == token.SUB {
			if v, ok := constIntValue(fc, e.X); ok {
				return -v, true
			}
		} else if e.Op == token.ADD {
			return constIntValue(fc, e.X)
		}
	case *ast.ParenExpr:
		return constIntValue(fc, e.X)
	}
	return 0, false
}

func daysInMonth(year int64, month int64) int {
	// Use Go's time.Date normalisation trick: day 0 of next month.
	if month < 1 || month > 12 {
		return 31
	}
	// The date that is the 0th day of next month is last day of this month.
	t := time.Date(int(year), time.Month(month)+1, 0, 0, 0, 0, 0, time.UTC)
	return t.Day()
}

func ruleTimeDate(fc *fileContext, _ interface{}) []failure {
	var out []failure
	ast.Inspect(fc.ast, func(n ast.Node) bool {
		call, ok := n.(*ast.CallExpr)
		if !ok || !fc.isCallTo(call, "time", "Date") || len(call.Args) < 8 {
			return true
		}
		year, yearOK := constIntValue(fc, call.Args[0])
		month, monthOK := constIntValue(fc, call.Args[1])
		day, dayOK := constIntValue(fc, call.Args[2])
		hour, hourOK := constIntValue(fc, call.Args[3])
		minute, minuteOK := constIntValue(fc, call.Args[4])
		second, secondOK := constIntValue(fc, call.Args[5])
		nsec, nsecOK := constIntValue(fc, call.Args[6])

		monthValid := monthOK && month >= 1 && month <= 12
		if monthOK {
			if month == 0 {
				out = append(out, fc.nodeFailure(call.Args[1], "time.Date month argument should not be zero", "time", 1, ""))
			} else if month < 1 || month > 12 {
				out = append(out, fc.nodeFailure(call.Args[1], fmt.Sprintf("time.Date month argument should be between 1 and 12: %d", month), "time", 0.8, ""))
			}
		}
		if dayOK {
			if day == 0 {
				out = append(out, fc.nodeFailure(call.Args[2], "time.Date day argument should not be zero", "time", 1, ""))
			} else if monthValid && day > 0 {
				maxDay := int64(daysInMonth(year, month))
				if !yearOK {
					// without a year February still has 28 days at most if year unknown? keep 29? use non-leap 2023 for Feb
					maxDay = int64(daysInMonth(2023, month))
				}
				if day > maxDay {
					mname := time.Month(month).String()
					var msg string
					if month == 2 {
						msg = fmt.Sprintf("time.Date day argument is %d, but %s %d has only %d days", day, mname, year, maxDay)
						if !yearOK {
							msg = fmt.Sprintf("time.Date day argument is %d, but %s has only %d days", day, mname, maxDay)
						}
					} else {
						msg = fmt.Sprintf("time.Date day argument is %d, but %s has only %d days", day, mname, maxDay)
					}
					out = append(out, fc.nodeFailure(call.Args[2], msg, "time", 0.8, ""))
				}
			} else if day < 0 {
				// Negative days are out of range too; approximate with the "only X days" form not known.
			}
		}
		if hourOK && (hour < 0 || hour > 23) {
			out = append(out, fc.nodeFailure(call.Args[3], fmt.Sprintf("time.Date hour argument should be between 0 and 23: %d", hour), "time", 0.8, ""))
		}
		if minuteOK && (minute < 0 || minute > 59) {
			out = append(out, fc.nodeFailure(call.Args[4], fmt.Sprintf("time.Date minute argument should be between 0 and 59: %d", minute), "time", 0.8, ""))
		}
		if secondOK && (second < 0 || second > 60) {
			out = append(out, fc.nodeFailure(call.Args[5], fmt.Sprintf("time.Date second argument should be between 0 and 59: %d", second), "time", 0.8, ""))
		}
		if nsecOK && (nsec < 0 || nsec > 999999999) {
			out = append(out, fc.nodeFailure(call.Args[6], fmt.Sprintf("time.Date nanosecond argument should be between 0 and 999999999: %d", nsec), "time", 0.8, ""))
		}
		return true
	})
	return out
}

// ---- unconditional-recursion ----

func ruleUnconditionalRecursion(fc *fileContext, _ interface{}) []failure {
	var out []failure
	for _, d := range fc.ast.Decls {
		fd, ok := d.(*ast.FuncDecl)
		if !ok || fd.Body == nil {
			continue
		}
		v := &recurVisitor{fc: fc, fd: fd, out: &out}
		for _, stmt := range fd.Body.List {
			v.visit(stmt, false)
		}
	}
	return out
}

type recurVisitor struct {
	fc                   *fileContext
	fd                   *ast.FuncDecl
	out                  *[]failure
	hasConditionalReturn bool
}

func (v *recurVisitor) isRecursiveCall(call *ast.CallExpr) bool {
	if v.fd.Recv == nil {
		id, ok := call.Fun.(*ast.Ident)
		if !ok || id.Name != v.fd.Name.Name {
			return false
		}
		if v.fc.types != nil {
			if obj := v.fc.types.Uses[id]; obj != nil {
				if def := v.fc.types.Defs[v.fd.Name]; def != nil {
					return obj == def
				}
			}
		}
		return true
	}
	sel, ok := call.Fun.(*ast.SelectorExpr)
	if !ok || sel.Sel.Name != v.fd.Name.Name {
		return false
	}
	recvField := v.fd.Recv.List[0]
	if len(recvField.Names) == 0 {
		return false
	}
	id, ok := sel.X.(*ast.Ident)
	return ok && id.Name == recvField.Names[0].Name
}

func (v *recurVisitor) visit(node ast.Node, conditional bool) {
	if node == nil {
		return
	}
	switch n := node.(type) {
	case *ast.CallExpr:
		if v.isRecursiveCall(n) && !conditional && !v.hasConditionalReturn {
			*v.out = append(*v.out, v.fc.nodeFailure(n, "unconditional recursive call", "logic", 0.8, ""))
		}
		// Visit function expression and arguments.
		if lit, ok := unwrapParen(n.Fun).(*ast.FuncLit); ok {
			// immediately invoked literal inherits current conditionality
			if lit.Body != nil {
				for _, stmt := range lit.Body.List {
					v.visit(stmt, conditional)
				}
			}
		} else {
			v.visit(n.Fun, conditional)
		}
		for _, arg := range n.Args {
			v.visit(arg, conditional)
		}
		return
	case *ast.FuncLit:
		// Non-immediately invoked literals: body is conditional.
		if n.Body != nil {
			for _, stmt := range n.Body.List {
				v.visit(stmt, true)
			}
		}
		return
	case *ast.IfStmt:
		if n.Init != nil {
			v.visit(n.Init, conditional)
		}
		v.visit(n.Cond, conditional)
		v.visit(n.Body, true)
		if n.Else != nil {
			v.visit(n.Else, true)
		}
		return
	case *ast.SwitchStmt:
		if n.Init != nil {
			v.visit(n.Init, conditional)
		}
		if n.Tag != nil {
			v.visit(n.Tag, conditional)
		}
		if n.Body != nil {
			for _, stmt := range n.Body.List {
				v.visit(stmt, conditional)
			}
		}
		return
	case *ast.TypeSwitchStmt:
		if n.Init != nil {
			v.visit(n.Init, conditional)
		}
		v.visit(n.Assign, conditional)
		if n.Body != nil {
			for _, stmt := range n.Body.List {
				v.visit(stmt, conditional)
			}
		}
		return
	case *ast.SelectStmt:
		if n.Body != nil {
			for _, stmt := range n.Body.List {
				v.visit(stmt, conditional)
			}
		}
		return
	case *ast.CaseClause:
		for _, e := range n.List {
			v.visit(e, conditional)
		}
		for _, stmt := range n.Body {
			v.visit(stmt, true)
		}
		return
	case *ast.CommClause:
		if n.Comm != nil {
			v.visit(n.Comm, conditional)
		}
		for _, stmt := range n.Body {
			v.visit(stmt, true)
		}
		return
	case *ast.ForStmt:
		if n.Init != nil {
			v.visit(n.Init, conditional)
		}
		if n.Cond != nil {
			v.visit(n.Cond, conditional)
		}
		if n.Post != nil {
			v.visit(n.Post, conditional)
		}
		bodyCond := conditional || n.Cond != nil
		v.visit(n.Body, bodyCond)
		return
	case *ast.RangeStmt:
		v.visit(n.X, conditional)
		v.visit(n.Body, true)
		return
	case *ast.ReturnStmt:
		for _, res := range n.Results {
			v.visit(res, conditional)
		}
		if conditional {
			v.hasConditionalReturn = true
		}
		return
	case *ast.ExprStmt:
		// panic(...) as a statement counts like a conditional return when conditional
		isPanic := false
		if call, ok := n.X.(*ast.CallExpr); ok {
			if id, ok := call.Fun.(*ast.Ident); ok && id.Name == "panic" {
				isPanic = true
			}
		}
		v.visit(n.X, conditional)
		if isPanic && conditional {
			v.hasConditionalReturn = true
		}
		return
	}
	for _, child := range childNodes(node) {
		v.visit(child, conditional)
	}
}

func unwrapParen(e ast.Expr) ast.Expr {
	for {
		if p, ok := e.(*ast.ParenExpr); ok {
			e = p.X
		} else {
			return e
		}
	}
}

// ---- unhandled-error ----

func configureUnhandledError(args []interface{}) (interface{}, error) {
	var ignored []string
	for _, arg := range args {
		s, ok := arg.(string)
		if !ok {
			return nil, fmt.Errorf("invalid argument to the unhandled-error rule. Expecting a string, got %s", typeName(arg))
		}
		ignored = append(ignored, s)
	}
	return ignored, nil
}

func ruleUnhandledError(fc *fileContext, optsI interface{}) []failure {
	ignoredList, _ := optsI.([]string)
	ignored := map[string]bool{}
	for _, s := range ignoredList {
		ignored[s] = true
	}
	var out []failure
	ast.Inspect(fc.ast, func(n ast.Node) bool {
		stmt, ok := n.(*ast.ExprStmt)
		if !ok {
			return true
		}
		call, ok := stmt.X.(*ast.CallExpr)
		if !ok {
			return true
		}
		t := fc.typeOf(call)
		if t == nil {
			return true
		}
		if !returnsError(t) {
			return true
		}
		funName := fc.nodeString(call.Fun)
		// Normalise method values like os.File.WriteString: nodeString gives "os.Stdout.WriteString";
		// the reference instead derives the name from the function type's origin when possible.
		funName = displayCallName(fc, call, funName)
		if ignored[funName] {
			return true
		}
		out = append(out, fc.nodeFailure(call, fmt.Sprintf("Unhandled error in call to function %s", funName), "bad practice", 1, ""))
		return true
	})
	return out
}

func returnsError(t types.Type) bool {
	if t == nil {
		return false
	}
	if isErrorType(t) {
		return true
	}
	if tup, ok := t.(*types.Tuple); ok {
		for i := 0; i < tup.Len(); i++ {
			if isErrorType(tup.At(i).Type()) {
				return true
			}
		}
	}
	return false
}

func displayCallName(fc *fileContext, call *ast.CallExpr, fallback string) string {
	// For selector calls on a value (e.g. os.Stdout.WriteString), reference renders
	// it as ReceiverType.Method (e.g. os.File.WriteString).
	sel, ok := call.Fun.(*ast.SelectorExpr)
	if !ok {
		return fallback
	}
	if fc.types != nil {
		if selInfo := fc.types.Selections[sel]; selInfo != nil {
			// selInfo.Recv() is the receiver type.
			recv := selInfo.Recv()
			if ptr, ok := recv.(*types.Pointer); ok {
				recv = ptr.Elem()
			}
			if recv != nil {
				return typeStringQualified(recv) + "." + sel.Sel.Name
			}
		}
	}
	return fallback
}
