					}
					if protoName != "" {
						if seenProtoNames[protoName] {
							out = append(out, fc.nodeFailure(tagLit, fmt.Sprintf("duplicated tag name %q in protobuf tag", protoName), "", 1, ""))
						} else {
							seenProtoNames[protoName] = true
						}
					}
					if protoNumber != "" {
						if seenProtoNumbers[protoNumber] {
							out = append(out, fc.nodeFailure(tagLit, fmt.Sprintf("duplicated tag number %s in protobuf tag", protoNumber), "", 1, ""))
						} else {
							seenProtoNumbers[protoNumber] = true
						}
					}
				default:
