	}
	return goVersionAtLeast(fc.pkg.goVersion, major, minor)
}

func isIntTypeName(s string) bool {
	switch s {
	case "int", "int8", "int16", "int32", "int64", "uint", "uint8", "uint16", "uint32", "uint64":
