		if len(parts) <= 1 {
			// plain tag name alone does not add custom checking in the reference
			continue
		}
		tagName := parts[0]
		if _, known := knownTagOptions[tagName]; !known && tagName != "protobuf" {
			// Args only extend pre-existing frameworks (observed)
			continue
		}
		if opts.extraOptions[tagName] == nil {
			opts.extraOptions[tagName] = map[string]bool{}
		}
		for _, o := range parts[1:] {
			opts.extraOptions[tagName][o] = true
		}
	}
	return opts, nil
}

type parsedTag struct {
	key   string
	value string
}

func parseStructTag(raw string) ([]parsedTag, bool) {
	s := raw
	// A field tag literal is typically a raw string; its content is `s`.
	var tags []parsedTag
	for s != "" {
		// skip leading spaces
		i := 0
		for i < len(s) && s[i] == ' ' {
			i++
		}
		s = s[i:]
		if s == "" {
			break
		}
		// scan key
		i = 0
		for i < len(s) && s[i] > ' ' && s[i] != ':' && s[i] != '"' && s[i] != 0x7f {
			i++
		}
		if i == 0 || i+1 >= len(s) || s[i] != ':' || s[i+1] != '"' {
			return nil, false
		}
		key := s[:i]
		s = s[i+1:]
		// scan quoted value
		i = 1
		for i < len(s) && s[i] != '"' {
			if s[i] == '\\' {
				i++
			}
			i++
		}
		if i >= len(s) {
			return nil, false
		}
		qvalue := s[:i+1]
		value, err := strconv.Unquote(qvalue)
		if err != nil {
			return nil, false
		}
		tags = append(tags, parsedTag{key, value})
		s = s[i+1:]
	}
	return tags, true
}

func ruleStructTag(fc *fileContext, optsI interface{}) []failure {
	opts, _ := optsI.(*structTagOptions)
	if opts == nil {
		opts = &structTagOptions{extraOptions: map[string]map[string]bool{}}
	}
	var out []failure
	ast.Inspect(fc.ast, func(n ast.Node) bool {
		st, ok := n.(*ast.StructType)
		if !ok || st.Fields == nil {
			return true
		}
		seenNames := map[string]map[string]bool{}
		seenASN1Numbers := map[string]bool{}
		seenProtoNames := map[string]bool{}
		seenProtoNumbers := map[string]bool{}
		addDup := func(tagKey string, field *ast.Field, tag *ast.BasicLit, name string) {
			if name == "" || name == "-" {
				return
			}
			if seenNames[tagKey] == nil {
				seenNames[tagKey] = map[string]bool{}
			}
			if seenNames[tagKey][name] {
				out = append(out, fc.nodeFailure(tag, fmt.Sprintf("duplicated tag name %q in %s tag", name, tagKey), "", 1, ""))
			} else {
				seenNames[tagKey][name] = true
			}
			_ = field
		}
		for _, field := range st.Fields.List {
			if field.Tag == nil {
				continue
			}
			tagLit := field.Tag
			content, err := strconv.Unquote(tagLit.Value)
			if err != nil {
				out = append(out, fc.nodeFailure(tagLit, "malformed tag", "", 1, ""))
				continue
			}
			tags, ok := parseStructTag(content)
			if !ok {
				out = append(out, fc.nodeFailure(tagLit, "malformed tag", "", 1, ""))
				continue
			}
			for _, tg := range tags {
				key, value := tg.key, tg.value
				parts := strings.Split(value, ",")
				switch key {
				case "asn1":
					// All components are options; several have special syntax.
					for _, p := range parts {
						switch {
						case strings.HasPrefix(p, "tag:"):
							numStr := strings.TrimPrefix(p, "tag:")
							num, err := strconv.Atoi(numStr)
							if err != nil {
								out = append(out, fc.nodeFailure(tagLit, fmt.Sprintf("tag must be a number but is %q in asn1 tag", numStr), "", 1, ""))
							} else {
								keyNum := strconv.Itoa(num)
								if seenASN1Numbers[keyNum] {
									out = append(out, fc.nodeFailure(tagLit, fmt.Sprintf("duplicated tag number %d in asn1 tag", num), "", 1, ""))
								} else {
									seenASN1Numbers[keyNum] = true
								}
							}
						case strings.HasPrefix(p, "default:"):
							def := strings.TrimPrefix(p, "default:")
							// If the field is numeric-ish (int family), the default must parse as an integer.
							if len(field.Names) > 0 {
								t := fc.typeOf(field.Type)
								if t != nil {
									ts := t.String()
									if isIntTypeName(ts) {
										if _, err := strconv.ParseInt(def, 10, 64); err != nil {
											out = append(out, fc.nodeFailure(tagLit, "type mismatch between field type and default value type in asn1 tag", "", 1, ""))
										}
									}
								} else if isIntTypeName(fc.nodeString(field.Type)) {
									if _, err := strconv.ParseInt(def, 10, 64); err != nil {
										out = append(out, fc.nodeFailure(tagLit, "type mismatch between field type and default value type in asn1 tag", "", 1, ""))
									}
								}
							}
						default:
							if !knownTagOptions["asn1"][p] && !opts.extraOptions["asn1"][p] {
								out = append(out, fc.nodeFailure(tagLit, fmt.Sprintf("unknown option %q in asn1 tag", p), "", 1, ""))
							}
						}
					}
				case "protobuf":
					if len(parts) == 0 {
						continue
					}
					first := parts[0]
					if !protobufTagNames[first] {
						out = append(out, fc.nodeFailure(tagLit, fmt.Sprintf("invalid tag name %q in protobuf tag", first), "", 1, ""))
						continue
					}
					hasName := false
					seenOpt := map[string]bool{}
					protoName := ""
					protoNumber := ""
					for _, p := range parts[1:] {
						optKey := p
						optVal := ""
						hasEq := false
						if idx := strings.Index(p, "="); idx >= 0 {
							optKey = p[:idx]
							optVal = p[idx+1:]
							hasEq = true
						}
						// A bare number is the field number.
						if !hasEq {
							if num, err := strconv.Atoi(p); err == nil {
								protoNumber = strconv.Itoa(num)
								continue
							}
						}
						// duplicated option detection
						dupKey := optKey
						if seenOpt[dupKey] {
							out = append(out, fc.nodeFailure(tagLit, fmt.Sprintf("duplicated option %q in protobuf tag", optKey), "", 1, ""))
							continue
						}
						seenOpt[dupKey] = true
						switch {
						case hasEq && optKey == "name":
							hasName = true
							protoName = optVal
						case hasEq && optKey == "json":
							// allowed
						case !hasEq && knownTagOptions["protobuf"][p]:
							// allowed
						case opts.extraOptions["protobuf"][optKey] || opts.extraOptions["protobuf"][p]:
							// allowed via args
						default:
							out = append(out, fc.nodeFailure(tagLit, fmt.Sprintf("unknown option %q in protobuf tag", optKey), "", 1, ""))
						}
					}
					if !hasName {
						out = append(out, fc.nodeFailure(tagLit, "mandatory option \"name\" not found in protobuf tag", "", 1, ""))
					}
					if protoName != "" {
						if seenProtoNames[protoName] {
							out = append(out, fc.nodeFailure(tagLit, fmt.Sprintf("duplicated tag name %q in protobuf tag", protoName), "", 1, ""))
						} else {
							seenProtoNames[protoName] = true
						}
					}
					if protoNumber != "" {
						if seenProtoNumbers[protoNumber] {
							out = append(out, fc.nodeFailure(tagLit, fmt.Sprintf("duplicated tag number %s in protobuf tag", protoNumber), "", 1, ""))
						} else {
							seenProtoNumbers[protoNumber] = true
						}
					}
				default:
					known, isKnown := knownTagOptions[key]
					if !isKnown {
						continue
					}
					name := ""
					var options []string
					if len(parts) > 0 {
						name = parts[0]
						options = parts[1:]
					}
					for _, o := range options {
						if o == "" {
							out = append(out, fc.nodeFailure(tagLit, fmt.Sprintf("option can not be empty in %s tag", key), "", 1, ""))
							continue
						}
						if key == "json" && o == "omitzero" && !fc.goVersionAtLeast(1, 24) {
							out = append(out, fc.nodeFailure(tagLit, "prior Go 1.24, option \"omitzero\" is unsupported in json tag", "", 1, ""))
							continue
						}
						if !known[o] && !opts.extraOptions[key][o] {
							out = append(out, fc.nodeFailure(tagLit, fmt.Sprintf("unknown option %q in %s tag", o, key), "", 1, ""))
						}
					}
					if dupNameTags[key] {
						addDup(key, field, tagLit, name)
					}
				}
			}
		}
		return true
	})
	return out
}

func (fc *fileContext) goVersionAtLeast(major, minor int) bool {
	if fc.pkg == nil {
		return false
	}
	return goVersionAtLeast(fc.pkg.goVersion, major, minor)
}

func isIntTypeName(s string) bool {
	switch s {
	case "int", "int8", "int16", "int32", "int64", "uint", "uint8", "uint16", "uint32", "uint64":
		return true
	}
	return false
}
