package main

import (
	"fmt"
	"go/ast"
	"path/filepath"
	"regexp"
	"strconv"
	"strings"
)

func init() {
	registerRule("confusing-naming", nil, ruleConfusingNaming)
	registerRule("forbidden-call-in-wg-go", nil, ruleForbiddenCallInWGGo)
	registerRule("package-directory-mismatch", configurePkgDirMismatch, rulePkgDirMismatch)
	registerRule("string-format", configureStringFormat, ruleStringFormat)
	registerRule("use-waitgroup-go", nil, ruleUseWaitgroupGo)
}

// confusing-naming

func ruleConfusingNaming(fc *fileContext, _ interface{}) []failure {
	var out []failure
	// Package-level functions
	seenFuncs := map[string]string{}
	// Methods grouped by receiver base type
	methodsByType := map[string]map[string]string{}
	for _, d := range fc.ast.Decls {
		switch node := d.(type) {
		case *ast.FuncDecl:
			name := node.Name.Name
			key := strings.ToLower(name)
			if node.Recv == nil {
				if prev, ok := seenFuncs[key]; ok && prev != name {
					out = append(out, fc.nodeFailure(node.Name, fmt.Sprintf("Method '%s' differs only by capitalization to function '%s' in the same source file", name, prev), "naming", 1, ""))
				} else if !ok {
					seenFuncs[key] = name
				}
			} else {
				rt := receiverTypeName(node)
				if methodsByType[rt] == nil {
					methodsByType[rt] = map[string]string{}
				}
				m := methodsByType[rt]
				if prev, ok := m[key]; ok && prev != name {
					out = append(out, fc.nodeFailure(node.Name, fmt.Sprintf("Method '%s' differs only by capitalization to method '%s' in the same source file", name, prev), "naming", 1, ""))
				} else if !ok {
					m[key] = name
				}
			}
		case *ast.GenDecl:
			for _, spec := range node.Specs {
				ts, ok := spec.(*ast.TypeSpec)
				if !ok {
					continue
				}
				st, ok := ts.Type.(*ast.StructType)
				if !ok || st.Fields == nil {
					continue
				}
				seenFields := map[string]string{}
				for _, field := range st.Fields.List {
					for _, fname := range field.Names {
						key := strings.ToLower(fname.Name)
						if prev, ok := seenFields[key]; ok && prev != fname.Name {
							out = append(out, fc.nodeFailure(fname, fmt.Sprintf("Field '%s' differs only by capitalization to other field in the struct type %s", fname.Name, ts.Name.Name), "naming", 1, ""))
						} else if !ok {
							seenFields[key] = fname.Name
						}
					}
				}
			}
		}
	}
	return out
}

// string-format

type stringFormatCheck struct {
	scope    string
	regexStr string
	regex    *regexp.Regexp
	message  string
}

func configureStringFormat(args []interface{}) (interface{}, error) {
	var checks []stringFormatCheck
	for i, arg := range args {
		list, ok := arg.([]interface{})
		if !ok {
			return nil, fmt.Errorf("invalid configuration for string-format: argument is not a slice [argument %d, option 0]", i)
		}
		if len(list) < 2 {
			opt := len(list) - 1
			if len(list) == 0 {
				opt = -1
			} else {
				opt = 0
			}
			return nil, fmt.Errorf("invalid configuration for string-format: less than two slices found in argument, scope and regex are required [argument %d, option %d]", i, opt)
		}
		var strs []string
		for j, elem := range list {
			if j > 2 {
				break
			}
			s, ok := elem.(string)
			if !ok {
				return nil, fmt.Errorf("invalid configuration for string-format: unexpected value, string was expected [argument %d, option %d]", i, j)
			}
			strs = append(strs, s)
		}
		// Even with extra options beyond index 2, the original validates types up to 2 only (observed).
		regexStr := strs[1]
		if len(regexStr) < 2 {
			return nil, fmt.Errorf("invalid configuration for string-format: regex is too small (regexes should begin and end with '/') [argument %d, option 1]", i)
		}
		inner := regexStr[1 : len(regexStr)-1]
		re, err := regexp.Compile(inner)
		if err != nil {
			return nil, fmt.Errorf("failed to parse configuration for string-format: unable to compile %s as regexp [argument %d, option 1]", regexStr, i)
		}
		chk := stringFormatCheck{scope: strs[0], regexStr: regexStr, regex: re}
		if len(strs) > 2 && len(list) == 3 {
			chk.message = strs[2]
		}
		checks = append(checks, chk)
	}
	return checks, nil
}

func ruleStringFormat(fc *fileContext, optsI interface{}) []failure {
	checks, _ := optsI.([]stringFormatCheck)
	if len(checks) == 0 {
		return nil
	}
	var out []failure
	ast.Inspect(fc.ast, func(n ast.Node) bool {
		call, ok := n.(*ast.CallExpr)
		if !ok || len(call.Args) == 0 {
			return true
		}
		funStr := fc.nodeString(call.Fun)
		for _, chk := range checks {
			if chk.scope != funStr {
				continue
			}
			lit, ok := call.Args[0].(*ast.BasicLit)
			if !ok || lit.Kind != 14 { // token.STRING constant value is not accessible here without import alias; compared below
				// fallback check through kind string
			}
			if !ok {
				continue
			}
			val, err := strconv.Unquote(lit.Value)
			if err != nil {
				continue
			}
			if !chk.regex.MatchString(val) {
				msg := chk.message
				if msg == "" {
					msg = fmt.Sprintf("string literal doesn't match user defined regex %s", chk.regexStr)
				}
				out = append(out, fc.nodeFailure(lit, msg, "", 1, ""))
			}
		}
		return true
	})
	return out
}

// package-directory-mismatch

type pkgDirOptions struct{ ignore []string }

func configurePkgDirMismatch(args []interface{}) (interface{}, error) {
	opts := &pkgDirOptions{}
	if len(args) == 0 {
		return opts, nil
	}
	m, ok := args[0].(map[string]interface{})
	if !ok {
		return nil, fmt.Errorf("invalid argument type: expected map[string]any, got %s", typeName(args[0]))
	}
	for k, v := range m {
		if k != "ignoreDirectories" {
			return nil, fmt.Errorf("unknown argument %s for package-directory-mismatch rule", k)
		}
		list, ok := v.([]interface{})
		if !ok {
			return nil, fmt.Errorf("invalid value %v for argument ignoreDirectories of rule package-directory-mismatch, expected []string got %s", v, typeName(v))
		}
		for _, e := range list {
			s, ok := e.(string)
			if !ok {
				return nil, fmt.Errorf("invalid value in ignoreDirectories argument of rule package-directory-mismatch: expected string, got %s", typeName(e))
			}
			opts.ignore = append(opts.ignore, s)
		}
	}
	return opts, nil
}

func rulePkgDirMismatch(fc *fileContext, optsI interface{}) []failure {
	opts, _ := optsI.(*pkgDirOptions)
	if opts == nil {
		opts = &pkgDirOptions{}
	}
	pkgName := fc.ast.Name.Name
	if pkgName == "main" {
		return nil
	}
	dir := filepath.Dir(fc.name)
	if dir == "." || dir == "" {
		return nil
	}
	// ignored directories: entry matches if absDir == entry or has suffix "/entry"
	absDir, err := filepath.Abs(dir)
	if err != nil {
		absDir = dir
	}
	for _, ig := range opts.ignore {
		if ig == absDir || strings.HasSuffix(absDir, "/"+ig) || filepath.Base(absDir) == ig && !strings.HasSuffix(ig, "/") {
			// NOTE: filepath.Base case replicates "foo" but not "foo/" (ig with trailing slash excluded above)
			return nil
		}
	}
	base := filepath.Base(dir)
	normalized := strings.NewReplacer("-", "", "_", "", ".", "").Replace(base)
	if pkgName != normalized {
		return []failure{fc.nodeFailure(fc.ast.Name, fmt.Sprintf("package name %q does not match directory name %q", pkgName, base), "", 1, "")}
	}
	return nil
}

// WaitGroup Go helpers

func isWaitGroupReceiverCall(fc *fileContext, call *ast.CallExpr, method string) (ast.Expr, bool) {
	sel, ok := call.Fun.(*ast.SelectorExpr)
	if !ok || sel.Sel.Name != method {
		return nil, false
	}
	return sel.X, true
}

func ruleUseWaitgroupGo(fc *fileContext, _ interface{}) []failure {
	if !fc.goVersionAtLeast(1, 25) {
		return nil
	}
	var out []failure
	ast.Inspect(fc.ast, func(n ast.Node) bool {
		block, ok := n.(*ast.BlockStmt)
		if !ok {
			return true
		}
		for i := 0; i+1 < len(block.List); i++ {
			exprStmt, ok := block.List[i].(*ast.ExprStmt)
			if !ok {
				continue
			}
			addCall, ok := exprStmt.X.(*ast.CallExpr)
			if !ok {
				continue
			}
			recv, ok := isWaitGroupReceiverCall(fc, addCall, "Add")
			if !ok || len(addCall.Args) != 1 || !isIntLiteral(addCall.Args[0], "1") {
				continue
			}
			goStmt, ok := block.List[i+1].(*ast.GoStmt)
			if !ok || goStmt.Call == nil {
				continue
			}
			lit, ok := unwrapParen(goStmt.Call.Fun).(*ast.FuncLit)
			if !ok || lit.Body == nil {
				continue
			}
			// Does the literal call recv.Done() anywhere (including deferred)?
			found := false
			ast.Inspect(lit.Body, func(inner ast.Node) bool {
				if call, ok := inner.(*ast.CallExpr); ok {
					if sel, ok := call.Fun.(*ast.SelectorExpr); ok && sel.Sel.Name == "Done" {
						if equalExpr(fc, sel.X, recv) {
							found = true
							return false
						}
					}
				}
				return true
			})
			if found {
				out = append(out, fc.nodeFailure(addCall, "replace wg.Add()...go {...wg.Done()...} with wg.Go(...)", "style", 1, ""))
			}
		}
		return true
	})
	return out
}

func isIntLiteral(expr ast.Expr, val string) bool {
	lit, ok := expr.(*ast.BasicLit)
	return ok && lit.Value == val
}

func ruleForbiddenCallInWGGo(fc *fileContext, _ interface{}) []failure {
	if !fc.goVersionAtLeast(1, 25) {
		return nil
	}
	var out []failure
	ast.Inspect(fc.ast, func(n ast.Node) bool {
		call, ok := n.(*ast.CallExpr)
		if !ok || len(call.Args) != 1 {
			return true
		}
		recv, ok := isWaitGroupReceiverCall(fc, call, "Go")
		if !ok {
			return true
		}
		lit, ok := unwrapParen(call.Args[0]).(*ast.FuncLit)
		if !ok || lit.Body == nil {
			return true
		}
		ast.Inspect(lit.Body, func(inner ast.Node) bool {
			if doneCall, ok := inner.(*ast.CallExpr); ok {
				if sel, ok := doneCall.Fun.(*ast.SelectorExpr); ok && sel.Sel.Name == "Done" {
					if equalExpr(fc, sel.X, recv) {
						out = append(out, fc.nodeFailure(doneCall, "do not call wg.Done inside wg.Go", "errors", 1, ""))
					}
				}
			}
			return true
		})
		return true
	})
	return out
}
