type stringFormatCheck struct {
	scope    string
	regexStr string
	regex    *regexp.Regexp
	message  string
}

func configureStringFormat(args []interface{}) (interface{}, error) {
	var checks []stringFormatCheck
	for i, arg := range args {
		list, ok := arg.([]interface{})
		if !ok {
			return nil, fmt.Errorf("invalid configuration for string-format: argument is not a slice [argument %d, option 0]", i)
		}
		if len(list) < 2 {
			opt := len(list) - 1
			if len(list) == 0 {
				opt = -1
			} else {
				opt = 0
			}
			return nil, fmt.Errorf("invalid configuration for string-format: less than two slices found in argument, scope and regex are required [argument %d, option %d]", i, opt)
		}
		var strs []string
		for j, elem := range list {
			if j > 2 {
				break
			}
			s, ok := elem.(string)
			if !ok {
				return nil, fmt.Errorf("invalid configuration for string-format: unexpected value, string was expected [argument %d, option %d]", i, j)
			}
			strs = append(strs, s)
		}
		// Even with extra options beyond index 2, the original validates types up to 2 only (observed).
		regexStr := strs[1]
		if len(regexStr) < 2 {
			return nil, fmt.Errorf("invalid configuration for string-format: regex is too small (regexes should begin and end with '/') [argument %d, option 1]", i)
		}
		inner := regexStr[1 : len(regexStr)-1]
		re, err := regexp.Compile(inner)
		if err != nil {
			return nil, fmt.Errorf("failed to parse configuration for string-format: unable to compile %s as regexp [argument %d, option 1]", regexStr, i)
		}
		chk := stringFormatCheck{scope: strs[0], regexStr: regexStr, regex: re}
		if len(strs) > 2 && len(list) == 3 {
			chk.message = strs[2]
		}
		checks = append(checks, chk)
	}
	return checks, nil
}

