	}
	if fc.types != nil {
		if tv, ok := fc.types.Types[expr]; ok && tv.Value != nil {
			// If the constant expression mentions a typed constant/variable, the
			// recorded type is meaningful; otherwise use the default type for the
			// constant kind (so `var x MyInt = 1` is not flagged).
			hasTyped := false
			ast.Inspect(expr, func(n ast.Node) bool {
				id, ok := n.(*ast.Ident)
				if !ok {
					return true
				}
				if id.Name == "true" || id.Name == "false" || id.Name == "nil" || id.Name == "iota" {
					return true
				}
				if obj := objectForIdent(fc, id); obj != nil {
					ot := obj.Type()
					if ot != nil {
						if basic, ok := ot.(*types.Basic); !ok || (basic.Info()&types.IsUntyped) == 0 {
							hasTyped = true
						}
					}
				}
				if sel, ok := n.(*ast.SelectorExpr); ok {
					_ = sel
					hasTyped = true
				}
				return true
			})
			// Selector expressions (e.g. time.Second) also count as typed.
			ast.Inspect(expr, func(n ast.Node) bool {
				if _, ok := n.(*ast.SelectorExpr); ok {
					hasTyped = true
				}
				return true
			})
			if !hasTyped {
				// Pure literal / constant arithmetic: use default type by constant kind.
				if lit, ok := unwrapParen(expr).(*ast.BasicLit); ok && lit.Kind == token.CHAR {
					return types.Typ[types.Rune]
				}
				switch tv.Value.Kind() {
				case constant.Int:
					return types.Typ[types.Int]
				case constant.Float:
					return types.Typ[types.Float64]
				case constant.Complex:
					return types.Typ[types.Complex128]
				case constant.String:
					return types.Typ[types.String]
				case constant.Bool:
					return types.Typ[types.Bool]
				}
			}
		}
	}
	return defaultType(t)
}

