{"command":"cat > /workspace/rules_unexportednaming.go <<'EOF'
package main

import (
	"fmt"
	"go/ast"
	"go/token"
)

func init() {
	registerRule("unexported-naming", nil, ruleUnexportedNaming)
}

func ruleUnexportedNaming(fc *fileContext, _ interface{}) []failure {
	var out []failure
	check := func(id *ast.Ident) {
		if id == nil || !isExportedName(id.Name) {
			return
		}
		out = append(out, fc.nodeFailure(id, fmt.Sprintf("the symbol %s is local, its name should start with a lowercase letter", id.Name), "naming", 1, ""))
	}
	checkFunc := func(ft *ast.FuncType) {
		for _, f := range fieldListNames(ft.Params) {
			check(f.ident)
		}
		for _, f := range fieldListNames(ft.Results) {
			check(f.ident)
		}
	}
	ast.Inspect(fc.ast, func(n ast.Node) bool {
		switch node := n.(type) {
		case *ast.FuncDecl:
			checkFunc(node.Type)
		case *ast.FuncLit:
			checkFunc(node.Type)
		case *ast.AssignStmt:
			if node.Tok == token.DEFINE {
				for _, lhs := range node.Lhs {
					if id, ok := lhs.(*ast.Ident); ok {
						if fc.types == nil || fc.types.Defs[id] != nil {
							check(id)
						}
					}
				}
			}
		case *ast.DeclStmt:
			if gd, ok := node.Decl.(*ast.GenDecl); ok {
				for _, spec := range gd.Specs {
					if vs, ok := spec.(*ast.ValueSpec); ok {
						for _, name := range vs.Names {
							check(name)
						}
					}
				}
			}
		}
		return true
	})
	return out
}
EOF
