func ruleEarlyReturn(fc *fileContext, optsI interface{}) []failure {
	preserveScope, _ := optsI.(bool)
	var out []failure
	ast.Inspect(fc.ast, func(n ast.Node) bool {
		ifs, ok := n.(*ast.IfStmt)
		if !ok || ifs.Else == nil {
			return true
		}
		elseBlock, ok := ifs.Else.(*ast.BlockStmt)
		if !ok {
			return true
		}
		if _, ok := lastStmt(elseBlock).(*ast.ReturnStmt); !ok {
			return true
		}
		if last := lastStmt(ifs.Body); last != nil {
			if _, ok := last.(*ast.ReturnStmt); ok {
				return true
			}
			if _, ok := last.(*ast.BranchStmt); ok {
				return true
			}
			if _, ok := terminatingCallKind(fc, last); ok {
				return true
			}
		}
		hasShortVarDecl := false
		if as, ok := ifs.Init.(*ast.AssignStmt); ok && as.Tok == token.DEFINE {
			hasShortVarDecl = true
		}
		if preserveScope {
			if hasShortVarDecl {
				return true
			}
			for _, stmt := range ifs.Body.List {
				switch st := stmt.(type) {
				case *ast.AssignStmt:
					if st.Tok == token.DEFINE {
						return true
					}
				case *ast.DeclStmt:
					return true
				}
			}
		}
		msg := "if c { ... } else { ... return } can be simplified to if !c { ... return } ..."
		if hasShortVarDecl {
			msg += " (move short variable declaration to its own line if necessary)"
		}
		out = append(out, fc.nodeFailure(ifs, msg, "", 1, ""))
		return true
	})
	return out
}

