var commonMethodNames = map[string]bool{
	"Error": true, "Read": true, "ServeHTTP": true, "String": true, "Write": true,
}

// implementsSortInterface reports whether the method's receiver type (in the
// same package) declares the full sort.Interface method set with exact signatures.
func (fc *fileContext) implementsSortInterface(fd *ast.FuncDecl) bool {
	if fd.Name.Name != "Len" && fd.Name.Name != "Less" && fd.Name.Name != "Swap" {
		return false
	}
	rt := receiverTypeName(fd)
	if rt == "" || fc.pkg == nil {
		return false
	}
	want := map[string]string{
		"Len":  "func() int",
		"Less": "func(int, int) bool",
		"Swap": "func(int, int)",
	}
	found := map[string]bool{}
	for _, file := range fc.pkg.files {
		for _, decl := range file.ast.Decls {
			m, ok := decl.(*ast.FuncDecl)
			if !ok || m.Recv == nil {
				continue
			}
			if receiverTypeName(m) != rt {
				continue
			}
			exp, ok := want[m.Name.Name]
			if !ok {
				continue
			}
			// Build a signature string without parameter/result names.
			sig := signatureString(file, m.Type)
			if sig == exp {
				found[m.Name.Name] = true
			}
		}
	}
	return len(found) == 3
}

func signatureString(fc *fileContext, ft *ast.FuncType) string {
	var params []string
	if ft.Params != nil {
		for _, f := range ft.Params.List {
			n := len(f.Names)
			if n == 0 {
				n = 1
			}
			for i := 0; i < n; i++ {
				params = append(params, fc.nodeString(f.Type))
			}
		}
	}
	var results []string
	if ft.Results != nil {
		for _, f := range ft.Results.List {
			n := len(f.Names)
			if n == 0 {
				n = 1
			}
			for i := 0; i < n; i++ {
				results = append(results, fc.nodeString(f.Type))
			}
		}
	}
	s := "func(" + strings.Join(params, ", ") + ")"
	if len(results) == 1 {
		s += " " + results[0]
	} else if len(results) > 1 {
		s += " (" + strings.Join(results, ", ") + ")"
	}
	return s
}
