func (fc *fileContext) standaloneTypePure(expr ast.Expr) (types.Type, bool) {
	if pure := fc.pureConstDefaultType(expr); pure != nil {
		return pure, true
	}
	switch e := expr.(type) {
	case *ast.ParenExpr:
		return fc.standaloneTypePure(e.X)
	case *ast.UnaryExpr:
		switch e.Op {
		case token.ADD, token.SUB, token.XOR:
