	case *ast.BinaryExpr:
		lt, lp := fc.standaloneTypePure(e.X)
		rt, rp := fc.standaloneTypePure(e.Y)
		if lt == nil || rt == nil {
			return fc.typeOf(expr), false
		}
		switch e.Op {
		case token.SHL, token.SHR:
			return lt, lp
		case token.EQL, token.NEQ, token.LSS, token.LEQ, token.GTR, token.GEQ, token.LAND, token.LOR:
			return types.Typ[types.Bool], lp && rp
		}
		if lp && !rp {
			return rt, false
		}
		if rp && !lp {
			return lt, false
		}
		if types.Identical(lt, rt) {
			return lt, lp && rp
		}
		return fc.typeOf(expr), false
